/* =========================================================
   PAINTCRAFT
   PART 2 — MAIN CSS + DARK MODE
   PAINTING & HOME RENOVATION WEBSITE
========================================================= */


/* =========================================================
   01. ROOT VARIABLES
========================================================= */

:root {

    /* -----------------------------------------------------
       FONT FAMILY
    ----------------------------------------------------- */

    --font-family: "Inter", sans-serif;


    /* -----------------------------------------------------
       FONT SIZE
       CONSISTENT THROUGHOUT WEBSITE
    ----------------------------------------------------- */

    --fs-h1: 48px;
    --fs-h2: 36px;
    --fs-h3: 24px;
    --fs-h4: 20px;

    --fs-body: 16px;
    --fs-small: 14px;
    --fs-label: 13px;
    --fs-nav: 15px;
    --fs-button: 15px;


    /* -----------------------------------------------------
       FONT WEIGHT
    ----------------------------------------------------- */

    --fw-regular: 400;
    --fw-medium: 500;
    --fw-semibold: 600;
    --fw-bold: 700;
    --fw-extrabold: 800;


    /* -----------------------------------------------------
       BRAND COLORS
    ----------------------------------------------------- */

    --color-orange: #ff5a36;
    --color-orange-dark: #e94a28;
    --color-orange-light: #ff704d;

    --color-green: #63b83f;
    --color-green-dark: #4f9d31;
    --color-green-light: #7acb55;


    /* -----------------------------------------------------
       LIGHT THEME
    ----------------------------------------------------- */

    --color-bg: #ffffff;
    --color-bg-soft: #f8f8f6;
    --color-bg-alt: #f3f4f2;

    --color-surface: #ffffff;
    --color-surface-soft: #fafafa;

    --color-text: #252525;
    --color-text-dark: #1d1d1d;
    --color-text-light: #666666;
    --color-text-muted: #888888;

    --color-border: #e4e4e4;
    --color-border-light: #eeeeee;


    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    --header-bg: #ffffff;
    --header-border: #eeeeee;

    --nav-text: #292929;
    --nav-hover: var(--color-orange);


    /* -----------------------------------------------------
       DROPDOWN
    ----------------------------------------------------- */

    --dropdown-bg: #ffffff;
    --dropdown-text: #333333;
    --dropdown-hover-bg: #fff3ef;
    --dropdown-border: #eeeeee;


    /* -----------------------------------------------------
       BUTTON
    ----------------------------------------------------- */

    --button-text: #ffffff;


    /* -----------------------------------------------------
       SHADOW
    ----------------------------------------------------- */

    --shadow-small:
        0 2px 10px rgba(0, 0, 0, 0.06);

    --shadow-medium:
        0 8px 25px rgba(0, 0, 0, 0.10);

    --shadow-dropdown:
        0 12px 30px rgba(0, 0, 0, 0.12);


    /* -----------------------------------------------------
       BORDER RADIUS
    ----------------------------------------------------- */

    --radius-small: 6px;
    --radius-medium: 10px;
    --radius-large: 14px;
    --radius-pill: 999px;


    /* -----------------------------------------------------
       TRANSITION
    ----------------------------------------------------- */

    --transition-fast: 0.2s ease;
    --transition-normal: 0.3s ease;


    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    --header-height: 82px;


    /* -----------------------------------------------------
       CONTAINER
    ----------------------------------------------------- */

    --container-width: 1700px;
    --container-padding: 30px;
}
/* =========================================================
   ACTIVE NAVIGATION MENU
========================================================= */

.desktop-navigation .nav-link.active,
.desktop-navigation .dropdown-toggle.active {
    color: #ff5a36;
}

/* Active underline */
.desktop-navigation .nav-link.active::after,
.desktop-navigation .dropdown-toggle.active::after {
    width: 100%;
    background: #ff5a36;
}

/* Active dropdown item */
.desktop-navigation .dropdown-menu a.active {
    color: #ff5a36;
    background: rgba(255, 90, 54, 0.08);
    font-weight: 700;
}

/* =========================================================
   02. DARK MODE VARIABLES
========================================================= */

body.dark-mode {

    --color-bg: #121212;
    --color-bg-soft: #181818;
    --color-bg-alt: #1d1d1d;

    --color-surface: #222222;
    --color-surface-soft: #252525;

    --color-text: #f5f5f5;
    --color-text-dark: #ffffff;
    --color-text-light: #b8b8b8;
    --color-text-muted: #8f8f8f;

    --color-border: #363636;
    --color-border-light: #2c2c2c;

    --header-bg: #161616;
    --header-border: #303030;

    --nav-text: #f1f1f1;
    --nav-hover: var(--color-orange-light);

    --dropdown-bg: #222222;
    --dropdown-text: #f5f5f5;
    --dropdown-hover-bg: #2d2d2d;
    --dropdown-border: #383838;

    --shadow-small:
        0 2px 10px rgba(0, 0, 0, 0.30);

    --shadow-medium:
        0 8px 25px rgba(0, 0, 0, 0.40);

    --shadow-dropdown:
        0 12px 30px rgba(0, 0, 0, 0.45);
}


/* =========================================================
   03. GLOBAL RESET
========================================================= */

*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}


html {
    scroll-behavior: smooth;
    font-size: 16px;
}


body {
    margin: 0;

    font-family: var(--font-family);
    font-size: var(--fs-body);
    font-weight: var(--fw-regular);
    line-height: 1.6;

    color: var(--color-text);
    background-color: var(--color-bg);

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;

    transition:
        background-color var(--transition-normal),
        color var(--transition-normal);
}


/* =========================================================
   04. FORM ELEMENTS
========================================================= */

button,
input,
textarea,
select {
    font-family: var(--font-family);
    font-size: inherit;
}


button {
    border: 0;
    background: none;
    cursor: pointer;
}


input,
textarea,
select {
    outline: none;
}


/* =========================================================
   05. GLOBAL ELEMENTS
========================================================= */

a {
    color: inherit;
    text-decoration: none;
}


img {
    display: block;
    max-width: 100%;
}


ul,
ol {
    list-style: none;
}


p {
    margin: 0;
}


/* =========================================================
   06. TYPOGRAPHY
========================================================= */

h1,
h2,
h3,
h4,
h5,
h6 {
    margin: 0;

    color: var(--color-text-dark);

    font-family: var(--font-family);

    line-height: 1.2;
}


h1 {
    font-size: var(--fs-h1);
    font-weight: var(--fw-extrabold);
}


h2 {
    font-size: var(--fs-h2);
    font-weight: var(--fw-bold);
}


h3 {
    font-size: var(--fs-h3);
    font-weight: var(--fw-bold);
}


h4 {
    font-size: var(--fs-h4);
    font-weight: var(--fw-semibold);
}


h5 {
    font-size: 18px;
    font-weight: var(--fw-semibold);
}


h6 {
    font-size: 16px;
    font-weight: var(--fw-semibold);
}


p {
    font-size: var(--fs-body);
    font-weight: var(--fw-regular);
}


.small-text {
    font-size: var(--fs-small);
}


.label-text {
    font-size: var(--fs-label);
    font-weight: var(--fw-semibold);
}


/* =========================================================
   07. COMMON CONTAINER
========================================================= */

.container {
    width: 100%;
    max-width: var(--container-width);

    margin-left: auto;
    margin-right: auto;

    padding-left: var(--container-padding);
    padding-right: var(--container-padding);
}


/* =========================================================
   08. SITE HEADER
========================================================= */

.site-header {
    position: fixed;

    width: 100%;

    background-color: var(--header-bg);

    border-bottom: 1px solid var(--header-border);

    z-index: 1000;

    transition:
        background-color var(--transition-normal),
        border-color var(--transition-normal);
}


/* =========================================================
   09. HEADER CONTAINER
========================================================= */

/* =========================================================
   HEADER CONTAINER
========================================================= */

.header-container {
    width: 100%;
    max-width: 1700px;

    min-height: var(--header-height);

    margin: 0 auto;

    padding:
        0
        var(--container-padding);

    display: grid;

    grid-template-columns:
        1fr
        auto
        1fr;

    align-items: center;

    box-sizing: border-box;
}


/* =========================================================
   10. LOGO
========================================================= */

.site-logo {
    flex: 0 0 185px;

    width: 185px;

    display: flex;
    align-items: center;
    justify-content: flex-start;

    line-height: 0;
}


.logo-image {
    width: 185px;
    height: auto;

    display: block;

    object-fit: contain;

    transition:
        opacity var(--transition-fast);
}


.site-logo:hover .logo-image {
    opacity: 0.9;
}


/* =========================================================
   11. DESKTOP NAVIGATION
========================================================= */

.desktop-navigation {
    flex: 1 1 auto;

    min-width: 0;

    display: flex;
    align-items: center;
    justify-content: flex-start;
}


.nav-menu {
    width: 100%;

    display: flex;
    align-items: center;
    justify-content: flex-start;

    gap: 0;

    white-space: nowrap;
}


.nav-item {
    position: relative;

    flex: 0 0 auto;
}


.nav-link {
    min-height: 42px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 6px;

    padding: 8px 9px;

    color: var(--nav-text);

    font-family: var(--font-family);
    font-size: var(--fs-nav);
    font-weight: var(--fw-medium);

    line-height: 1.2;

    white-space: nowrap;

    border-radius: var(--radius-small);

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast);
}


.nav-link:hover,
.nav-link:focus-visible {
    color: var(--color-orange);

    background-color: var(--color-bg-soft);
}


/* =========================================================
   12. DESKTOP DROPDOWNS
========================================================= */

.has-dropdown {
    position: relative;
}


.dropdown-toggle i {
    font-size: 11px;

    transition:
        transform var(--transition-fast);
}


.has-dropdown:has(.dropdown-toggle[aria-expanded="true"])
.dropdown-toggle i {
    transform: rotate(180deg);
}


.dropdown-menu {
    position: absolute;

    top: calc(100% + 8px);
    left: 0;

    min-width: 210px;

    padding: 8px;

    background-color: var(--dropdown-bg);

    border: 1px solid var(--dropdown-border);

    border-radius: var(--radius-medium);

    box-shadow: var(--shadow-dropdown);

    opacity: 0;
    visibility: hidden;

    transform: translateY(-8px);

    pointer-events: none;

    transition:
        opacity var(--transition-fast),
        visibility var(--transition-fast),
        transform var(--transition-fast);

    z-index: 1100;
}


.has-dropdown
.dropdown-toggle[aria-expanded="true"]
~ .dropdown-menu {
    opacity: 1;
    visibility: visible;

    transform: translateY(0);

    pointer-events: auto;
}


.dropdown-menu li {
    width: 100%;
}


.dropdown-menu a {
    width: 100%;

    min-height: 40px;

    display: flex;
    align-items: center;

    padding: 9px 12px;

    color: var(--dropdown-text);

    font-size: var(--fs-small);
    font-weight: var(--fw-medium);

    border-radius: var(--radius-small);

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast);
}


.dropdown-menu a:hover,
.dropdown-menu a:focus-visible {
    color: var(--color-orange);

    background-color: var(--dropdown-hover-bg);
}


/* =========================================================
   13. DESKTOP HEADER ACTIONS
========================================================= */

.desktop-header-actions {
    flex: 0 0 auto;

    display: flex;
    align-items: center;
    justify-content: flex-end;

    gap: 8px;

    white-space: nowrap;
}


/* =========================================================
   14. COMMON HEADER ACTION BUTTON
========================================================= */

.header-action-btn {
    height: 44px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    padding: 0 14px;

    color: var(--color-text);

    background-color: var(--color-bg-soft);

    border: 1px solid var(--color-border);

    border-radius: var(--radius-small);

    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast);
}


.header-action-btn:hover,
.header-action-btn:focus-visible {
    color: var(--color-orange);

    background-color: var(--color-bg);

    border-color: var(--color-orange);

    transform: translateY(-1px);
}


/* =========================================================
   15. DESKTOP RTL + DARK MODE
   ICON ONLY
========================================================= */

.desktop-header-actions .rtl-btn,
.desktop-header-actions .dark-mode-btn {
    width: 72px;
    min-width: 72px;

    height: 44px;
    min-height: 44px;

    flex: 0 0 72px;

    padding: 0;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 0;
}


.desktop-header-actions .rtl-btn i,
.desktop-header-actions .dark-mode-btn i {
    font-size: 18px;
    line-height: 1;
}


/* =========================================================
   16. LOGIN BUTTON
========================================================= */

.primary-btn {
    min-height: 44px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 7px;

    padding: 0 18px;

    color: #ffffff;

    background-color: var(--color-orange);

    border: 1px solid var(--color-orange);

    border-radius: var(--radius-small);

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);

    line-height: 1;

    white-space: nowrap;

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}


.primary-btn:hover,
.primary-btn:focus-visible {
    color: var(--color-orange);

    background-color: #ffffff;

    border-color: var(--color-orange);

    transform: translateY(-1px);

    box-shadow: var(--shadow-small);
}


.primary-btn i {
    font-size: 14px;
}


.desktop-header-actions .login-btn {
    min-width: 86px;

    flex: 0 0 auto;
}


/* =========================================================
   17. SECONDARY BUTTON
========================================================= */
/* =========================================================
   HEADER QUOTE BUTTON WIDTH
========================================================= */

.desktop-header-actions .header-quote-btn {
    width: 220px;
    min-width: 220px;
    padding: 0 20px;
}
/* =========================================================
   HEADER QUOTE BUTTON
========================================================= */

.desktop-header-actions .header-quote-btn {
    min-height: 44px;
    width: 200px;
    min-width: 200px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    padding: 0 16px;
    gap: 8px;

    color: var(--color-orange);
    background-color: transparent;
    border: 1px solid var(--color-orange);
    border-radius: var(--radius-small);

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;

    white-space: nowrap;

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast),
        border-color var(--transition-fast);
}

/* Hover */
.desktop-header-actions .header-quote-btn:hover {
    color: #ffffff;
    background-color: var(--color-orange);
    border-color: var(--color-orange);
}
/* Reduce Header Quote Button Width */
.desktop-header-actions .header-quote-btn {
    width: 170px !important;
    min-width: 170px !important;
    padding: 0 12px !important;
}





.desktop-header-actions .header-quote-btn {
    min-width: 218px;

    flex: 0 0 auto;
}


/* =========================================================
   18. HAMBURGER BUTTON
========================================================= */

.hamburger-button {
    width: 46px;
    height: 46px;

    flex: 0 0 46px;

    display: none;

    align-items: center;
    justify-content: center;

    flex-direction: column;

    gap: 5px;

    padding: 0;

    color: var(--color-text);

    background-color: var(--color-bg);

    border: 1px solid var(--color-border);

    border-radius: var(--radius-small);

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast),
        border-color var(--transition-fast);
}


.hamburger-button:hover,
.hamburger-button:focus-visible {
    color: var(--color-orange);

    border-color: var(--color-orange);
}


.hamburger-line {
    width: 20px;
    height: 2px;

    display: block;

    background-color: currentColor;

    border-radius: 2px;

    transition:
        transform var(--transition-fast),
        opacity var(--transition-fast);
}


.hamburger-button.active
.hamburger-line:nth-child(1) {
    transform:
        translateY(7px)
        rotate(45deg);
}


.hamburger-button.active
.hamburger-line:nth-child(2) {
    opacity: 0;
}


.hamburger-button.active
.hamburger-line:nth-child(3) {
    transform:
        translateY(-7px)
        rotate(-45deg);
}


/* =========================================================
   19. MOBILE NAVIGATION DRAWER
========================================================= */

.mobile-navigation {
    position: fixed;

    top: 0;
    right: 0;

    width: 400px;
    max-width: 90vw;

    height: 100vh;

    display: none;

    background-color: var(--color-bg);

    border-left: 1px solid var(--color-border);

    box-shadow:
        -10px 0 35px rgba(0, 0, 0, 0.12);

    overflow-y: auto;

    z-index: 9999;

    transform: translateX(100%);

    visibility: hidden;
    opacity: 0;

    transition:
        transform var(--transition-normal),
        opacity var(--transition-normal),
        visibility var(--transition-normal);
}


.mobile-navigation.active {
    transform: translateX(0);

    visibility: visible;
    opacity: 1;
}


.mobile-navigation-inner {
    width: 100%;
    min-height: 100%;

    padding: 26px;

    display: flex;
    flex-direction: column;
}


/* =========================================================
   20. MOBILE MENU HEADER
========================================================= */

.mobile-menu-header {
    width: 100%;

    min-height: 52px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding-bottom: 14px;

    border-bottom: 1px solid var(--color-border);
}


.mobile-menu-title {
    color: var(--color-text-dark);

    font-size: 21px;
    font-weight: var(--fw-bold);
}


.mobile-menu-close {
    width: 42px;
    height: 42px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    color: var(--color-text);

    background-color: var(--color-bg-soft);

    border: 1px solid var(--color-border);

    border-radius: var(--radius-small);

    font-size: 18px;

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast),
        border-color var(--transition-fast);
}


.mobile-menu-close:hover,
.mobile-menu-close:focus-visible {
    color: var(--color-orange);

    background-color: var(--color-bg);

    border-color: var(--color-orange);
}


/* =========================================================
   21. MOBILE MENU
========================================================= */

.mobile-menu {
    width: 100%;

    padding-top: 14px;
}


.mobile-nav-list {
    width: 100%;
}


.mobile-nav-item {
    width: 100%;

    border-bottom: 1px solid var(--color-border-light);
}


.mobile-nav-link {
    width: 100%;
    min-height: 52px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 12px;

    padding: 11px 2px;

    color: var(--color-text);

    background-color: transparent;

    font-family: var(--font-family);
    font-size: var(--fs-nav);
    font-weight: var(--fw-medium);

    text-align: left;

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast);
}


.mobile-nav-link:hover,
.mobile-nav-link:focus-visible {
    color: var(--color-orange);
}


.mobile-dropdown-toggle i {
    font-size: 11px;

    transition:
        transform var(--transition-fast);
}


.has-mobile-dropdown.active
.mobile-dropdown-toggle i {
    transform: rotate(180deg);
}


/* =========================================================
   22. MOBILE DROPDOWN
========================================================= */

.mobile-dropdown-menu {
    width: 100%;

    max-height: 0;

    padding-left: 12px;

    overflow: hidden;

    opacity: 0;

    transition:
        max-height var(--transition-normal),
        opacity var(--transition-normal);
}


.has-mobile-dropdown.active
.mobile-dropdown-menu {
    max-height: 600px;

    opacity: 1;
}


.mobile-dropdown-menu li {
    width: 100%;
}


.mobile-dropdown-menu a {
    width: 100%;

    min-height: 42px;

    display: flex;
    align-items: center;

    padding: 8px 10px;

    color: var(--color-text-light);

    border-left: 2px solid transparent;

    font-size: var(--fs-small);
    font-weight: var(--fw-medium);

    transition:
        color var(--transition-fast),
        background-color var(--transition-fast),
        border-color var(--transition-fast);
}


.mobile-dropdown-menu a:hover,
.mobile-dropdown-menu a:focus-visible {
    color: var(--color-orange);

    background-color: var(--color-bg-soft);

    border-left-color: var(--color-orange);
}


/* =========================================================
   23. MOBILE HEADER ACTIONS
========================================================= */

.mobile-header-actions {
    width: 100%;

    margin-top: auto;

    padding-top: 24px;

    display: flex;
    flex-direction: column;

    gap: 10px;
}


/* =========================================================
   24. MOBILE ACTION BUTTONS
========================================================= */

.mobile-header-actions .mobile-action-btn {
    width: 100%;
    min-height: 46px;

    display: flex;
    align-items: center;
    justify-content: center;

    box-sizing: border-box;
}


/* RTL + DARK MODE */

.mobile-header-actions .rtl-btn,
.mobile-header-actions .dark-mode-btn {
    width: 100%;
    min-width: 100%;

    height: 46px;
    min-height: 46px;

    padding: 0;
}


.mobile-header-actions .rtl-btn i,
.mobile-header-actions .dark-mode-btn i {
    font-size: 18px;
}


/* LOGIN */

.mobile-header-actions .login-btn {
    width: 100%;
    min-height: 46px;
}


/* QUOTE */

.mobile-header-actions .mobile-quote-btn {
    width: 100%;
    min-height: 46px;
}


/* =========================================================
   25. DARK MODE — GENERAL ELEMENTS
========================================================= */

body.dark-mode .site-header {
    background-color: var(--header-bg);

    border-color: var(--header-border);
}


body.dark-mode .mobile-navigation {
    background-color: var(--color-bg);

    border-color: var(--color-border);
}


body.dark-mode .hamburger-button {
    color: #f1f1f1;

    background-color: #1c1c1c;

    border-color: #383838;
}


body.dark-mode .hamburger-button:hover,
body.dark-mode .hamburger-button:focus-visible {
    color: var(--color-orange-light);

    background-color: #252525;

    border-color: var(--color-orange-light);
}


body.dark-mode .mobile-menu-close {
    color: #f1f1f1;

    background-color: #1c1c1c;

    border-color: #383838;
}


body.dark-mode .mobile-menu-close:hover,
body.dark-mode .mobile-menu-close:focus-visible {
    color: var(--color-orange-light);

    background-color: #252525;

    border-color: var(--color-orange-light);
}


/* =========================================================
   26. DARK MODE — BUTTONS
========================================================= */

body.dark-mode .header-action-btn {
    color: #f1f1f1;

    background-color: #222222;

    border-color: #383838;
}


body.dark-mode .header-action-btn:hover,
body.dark-mode .header-action-btn:focus-visible {
    color: var(--color-orange-light);

    background-color: #2b2b2b;

    border-color: var(--color-orange-light);
}


/* PRIMARY BUTTON */

body.dark-mode .primary-btn {
    color: #ffffff;

    background-color: var(--color-orange);

    border-color: var(--color-orange);
}


body.dark-mode .primary-btn:hover,
body.dark-mode .primary-btn:focus-visible {
    color: var(--color-orange);

    background-color: #ffffff;

    border-color: #ffffff;
}


/* SECONDARY BUTTON */

body.dark-mode .secondary-btn {
    color: var(--color-orange-light);

    background-color: transparent;

    border-color: var(--color-orange-light);
}


body.dark-mode .secondary-btn:hover,
body.dark-mode .secondary-btn:focus-visible {
    color: #121212;

    background-color: var(--color-orange-light);

    border-color: var(--color-orange-light);
}


/* =========================================================
   27. DARK MODE — DROPDOWNS
========================================================= */

body.dark-mode .dropdown-menu {
    background-color: var(--dropdown-bg);

    border-color: var(--dropdown-border);
}


body.dark-mode .dropdown-menu a {
    color: var(--dropdown-text);
}


body.dark-mode .dropdown-menu a:hover,
body.dark-mode .dropdown-menu a:focus-visible {
    color: var(--color-orange-light);

    background-color: var(--dropdown-hover-bg);
}


body.dark-mode .mobile-dropdown-menu a {
    color: var(--color-text-light);
}


body.dark-mode .mobile-dropdown-menu a:hover,
body.dark-mode .mobile-dropdown-menu a:focus-visible {
    color: var(--color-orange-light);

    background-color: var(--color-bg-soft);

    border-left-color: var(--color-orange-light);
}


/* =========================================================
   28. DARK MODE — MOBILE MENU
========================================================= */

body.dark-mode .mobile-menu-header {
    border-color: var(--color-border);
}


body.dark-mode .mobile-nav-item {
    border-color: var(--color-border-light);
}


body.dark-mode .mobile-nav-link {
    color: var(--color-text);
}


body.dark-mode .mobile-nav-link:hover,
body.dark-mode .mobile-nav-link:focus-visible {
    color: var(--color-orange-light);
}


/* =========================================================
   29. RTL FOUNDATION
========================================================= */

html[dir="rtl"] {
    direction: rtl;
}


html[dir="rtl"] body {
    direction: rtl;
}


html[dir="rtl"] .header-container {
    direction: rtl;
}


html[dir="rtl"] .desktop-navigation {
    direction: rtl;
}


html[dir="rtl"] .nav-menu {
    direction: rtl;
}


html[dir="rtl"] .nav-link {
    direction: rtl;
}


html[dir="rtl"] .dropdown-menu {
    left: auto;
    right: 0;

    direction: rtl;
}


html[dir="rtl"] .mobile-navigation {
    right: auto;
    left: 0;

    transform: translateX(-100%);

    border-left: 0;
    border-right: 1px solid var(--color-border);

    direction: rtl;
}


html[dir="rtl"] .mobile-navigation.active {
    transform: translateX(0);
}


html[dir="rtl"] .mobile-navigation-inner {
    direction: rtl;
}


html[dir="rtl"] .mobile-menu {
    direction: rtl;
}


html[dir="rtl"] .mobile-nav-link {
    text-align: right;
}


html[dir="rtl"] .mobile-dropdown-menu {
    padding-left: 0;
    padding-right: 12px;
}


html[dir="rtl"] .mobile-dropdown-menu a {
    border-left: 0;
    border-right: 2px solid transparent;
}


html[dir="rtl"]
.mobile-dropdown-menu a:hover,
html[dir="rtl"]
.mobile-dropdown-menu a:focus-visible {
    border-right-color: var(--color-orange);

    border-left-color: transparent;
}


html[dir="rtl"] .mobile-header-actions {
    direction: rtl;
}


html[dir="rtl"] .secondary-btn i {
    transform: rotate(180deg);
}


html[dir="rtl"] .secondary-btn:hover i {
    transform:
        rotate(180deg)
        translateX(3px);
}


/* =========================================================
   30. MOBILE MENU SCROLLBAR
========================================================= */

.mobile-navigation::-webkit-scrollbar {
    width: 5px;
}


.mobile-navigation::-webkit-scrollbar-track {
    background: transparent;
}


.mobile-navigation::-webkit-scrollbar-thumb {
    background-color: var(--color-border);

    border-radius: var(--radius-pill);
}


.mobile-navigation::-webkit-scrollbar-thumb:hover {
    background-color: var(--color-orange);
}


/* =========================================================
   31. BODY WHEN MENU IS OPEN
========================================================= */

body.menu-open {
    overflow: hidden;
}


/* =========================================================
   32. FOCUS ACCESSIBILITY
========================================================= */

button:focus-visible,
a:focus-visible {
    outline: 2px solid var(--color-orange);

    outline-offset: 2px;
}


/* =========================================================
   33. REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    *,
    *::before,
    *::after {
        scroll-behavior: auto !important;

        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
    }

}


/* =========================================================
   34. END OF MAIN CSS
========================================================= */



/* =========================================================
   PAINTCRAFT FOOTER
   PART 2 — MAIN FOOTER CSS
========================================================= */


/* =========================================================
   FOOTER BASE
========================================================= */

.site-footer {
    width: 100%;
    margin: 0;
    padding: 0;
    background: #17212b;
    color: #ffffff;
    direction: inherit;
}

.footer-main {
    width: 100%;
    padding: 70px 0 55px;
    background: #17212b;
}

.footer-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding-left: 30px;
    padding-right: 30px;
}


/* =========================================================
   FOOTER MAIN GRID
========================================================= */

.footer-main .footer-container {
    display: grid;
    grid-template-columns: 1.35fr 1fr 1fr 1.25fr;
    gap: 55px;
    align-items: start;
}


/* =========================================================
   FOOTER BRAND
========================================================= */

.footer-brand {
    min-width: 0;
}

.footer-logo {
    display: inline-flex;
    align-items: center;
    text-decoration: none;
    margin-bottom: 22px;
}

.footer-logo-image {
    display: block;
    width: 175px;
    height: auto;
    max-width: 100%;
    object-fit: contain;
}

.footer-description {
    max-width: 390px;
    margin: 0 0 25px;
    color: #cbd3da;
    font-family: "Inter", sans-serif;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   FOOTER SOCIAL
========================================================= */

.footer-social {
    display: flex;
    align-items: center;
    gap: 11px;
}

.footer-social a {
    width: 40px;
    height: 40px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(255, 255, 255, 0.20);
    border-radius: 50%;

    color: #ffffff;
    background: transparent;

    text-decoration: none;

    font-size: 15px;

    transition:
        background-color 0.25s ease,
        border-color 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease;
}

.footer-social a:hover {
    background: #ff5a36;
    border-color: #ff5a36;
    color: #ffffff;
    transform: translateY(-2px);
}


/* =========================================================
   FOOTER TITLES
========================================================= */

.footer-title {
    position: relative;

    margin: 0 0 24px;

    color: #ffffff;

    font-family: "Inter", sans-serif;
    font-size: 18px;
    font-weight: 700;
    line-height: 1.4;
}

.footer-title::after {
    content: "";

    display: block;

    width: 42px;
    height: 3px;

    margin-top: 10px;

    background: #ff5a36;
    border-radius: 3px;
}


/* =========================================================
   FOOTER LINKS
========================================================= */

.footer-links {
    display: flex;
    flex-direction: column;

    gap: 13px;

    margin: 0;
    padding: 0;

    list-style: none;
}

.footer-links li {
    margin: 0;
    padding: 0;
}

.footer-links a {
    display: inline-flex;
    align-items: center;

    position: relative;

    color: #cbd3da;

    font-family: "Inter", sans-serif;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.5;

    text-decoration: none;

    transition:
        color 0.25s ease,
        padding 0.25s ease;
}

.footer-links a::before {
    content: "\f061";

    margin-right: 9px;

    color: #ff5a36;

    font-family: "Font Awesome 6 Free";
    font-size: 10px;
    font-weight: 900;

    transition:
        transform 0.25s ease,
        margin 0.25s ease;
}

.footer-links a:hover {
    color: #ffffff;
    padding-left: 3px;
}

.footer-links a:hover::before {
    transform: translateX(2px);
}


/* =========================================================
   FOOTER CONTACT
========================================================= */

.footer-contact-list {
    display: flex;
    flex-direction: column;
    gap: 18px;

    margin: 0;
    padding: 0;

    list-style: none;
}

.footer-contact-item {
    display: flex;
    align-items: flex-start;
    gap: 13px;

    color: #cbd3da;

    font-family: "Inter", sans-serif;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.65;
}

.footer-contact-item i {
    flex: 0 0 20px;

    width: 20px;

    margin-top: 3px;

    color: #ff5a36;

    font-size: 16px;
    text-align: center;
}

.footer-contact-item span {
    display: block;
}

.footer-contact-item a {
    color: #cbd3da;
    text-decoration: none;

    transition: color 0.25s ease;
}

.footer-contact-item a:hover {
    color: #ffffff;
}


/* =========================================================
   FOOTER CTA
========================================================= */

.footer-cta {
    width: 100%;

    background: #ff5a36;

    padding: 35px 0;
}

.footer-cta-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 30px;
}

.footer-cta-content {
    min-width: 0;
}

.footer-cta-content h2 {
    margin: 0 0 7px;

    color: #ffffff;

    font-family: "Inter", sans-serif;
    font-size: 25px;
    font-weight: 700;
    line-height: 1.35;
}

.footer-cta-content p {
    margin: 0;

    color: rgba(255, 255, 255, 0.90);

    font-family: "Inter", sans-serif;
    font-size: 15px;
    font-weight: 400;
    line-height: 1.6;
}


/* =========================================================
   FOOTER CTA BUTTON
========================================================= */

.footer-cta-button {
    flex: 0 0 auto;

    min-height: 48px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;

    padding: 0 24px;

    border: 2px solid #ffffff;
    border-radius: 8px;

    background: #ffffff;
    color: #ff5a36;

    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;

    text-decoration: none;
    white-space: nowrap;

    transition:
        background-color 0.25s ease,
        color 0.25s ease,
        border-color 0.25s ease,
        transform 0.25s ease;
}

.footer-cta-button i {
    font-size: 13px;
    transition: transform 0.25s ease;
}

.footer-cta-button:hover {
    background: transparent;
    color: #ffffff;
    border-color: #ffffff;
    transform: translateY(-2px);
}

.footer-cta-button:hover i {
    transform: translateX(3px);
}


/* =========================================================
   FOOTER BOTTOM
========================================================= */

.footer-bottom {
    width: 100%;

    background: #111a22;

    border-top: 1px solid rgba(255, 255, 255, 0.10);

    padding: 20px 0;
}

.footer-bottom-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 20px;
}

.footer-copyright {
    margin: 0;

    color: #9da8b2;

    font-family: "Inter", sans-serif;
    font-size: 13px;
    font-weight: 400;
    line-height: 1.5;
}

.footer-legal-links {
    display: flex;
    align-items: center;
    gap: 22px;
}

.footer-legal-links a {
    color: #9da8b2;

    font-family: "Inter", sans-serif;
    font-size: 13px;
    font-weight: 400;

    text-decoration: none;

    transition: color 0.25s ease;
}

.footer-legal-links a:hover {
    color: #ffffff;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .site-footer {
    background: #0d141b;
}

body.dark-mode .footer-main {
    background: #0d141b;
}

body.dark-mode .footer-bottom {
    background: #080d12;
    border-top-color: rgba(255, 255, 255, 0.08);
}

body.dark-mode .footer-description,
body.dark-mode .footer-links a,
body.dark-mode .footer-contact-item,
body.dark-mode .footer-contact-item a {
    color: #b8c1ca;
}

body.dark-mode .footer-links a:hover,
body.dark-mode .footer-contact-item a:hover {
    color: #ffffff;
}

body.dark-mode .footer-social a {
    border-color: rgba(255, 255, 255, 0.18);
}

body.dark-mode .footer-social a:hover {
    background: #e94a28;
    border-color: #e94a28;
}

body.dark-mode .footer-title {
    color: #ffffff;
}

body.dark-mode .footer-cta {
    background: #e94a28;
}

body.dark-mode .footer-cta-button {
    color: #e94a28;
}

body.dark-mode .footer-cta-button:hover {
    background: transparent;
    color: #ffffff;
}


/* =========================================================
   RTL SUPPORT
========================================================= */

html[dir="rtl"] .site-footer,
body.rtl .site-footer {
    direction: rtl;
}

html[dir="rtl"] .footer-links a::before,
body.rtl .footer-links a::before {
    content: "\f060";

    margin-right: 0;
    margin-left: 9px;
}

html[dir="rtl"] .footer-links a:hover,
body.rtl .footer-links a:hover {
    padding-left: 0;
    padding-right: 3px;
}

html[dir="rtl"] .footer-links a:hover::before,
body.rtl .footer-links a:hover::before {
    transform: translateX(-2px);
}

html[dir="rtl"] .footer-contact-item,
body.rtl .footer-contact-item {
    flex-direction: row;
}

html[dir="rtl"] .footer-cta-button i,
body.rtl .footer-cta-button i {
    transform: rotate(180deg);
}

html[dir="rtl"] .footer-cta-button:hover i,
body.rtl .footer-cta-button:hover i {
    transform: rotate(180deg) translateX(3px);
}


/* =========================================================
   TABLET — IPAD PRO
========================================================= */

@media (min-width: 769px) and (max-width: 1199px) {

    .footer-main {
        padding: 60px 0 45px;
    }

    .footer-main .footer-container {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 45px 40px;
    }

    .footer-logo-image {
        width: 165px;
    }

    .footer-description {
        max-width: 450px;
    }

    .footer-cta {
        padding: 30px 0;
    }

    .footer-cta-content h2 {
        font-size: 23px;
    }

    .footer-bottom {
        padding: 18px 0;
    }
}


/* =========================================================
   TABLET — IPAD MINI
========================================================= */

@media (min-width: 481px) and (max-width: 768px) {

    .footer-container {
        padding-left: 25px;
        padding-right: 25px;
    }

    .footer-main {
        padding: 55px 0 40px;
    }

    .footer-main .footer-container {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 40px 30px;
    }

    .footer-logo-image {
        width: 155px;
    }

    .footer-description {
        font-size: 14px;
    }

    .footer-title {
        font-size: 17px;
    }

    .footer-links a,
    .footer-contact-item {
        font-size: 14px;
    }

    .footer-cta {
        padding: 28px 0;
    }

    .footer-cta-inner {
        align-items: flex-start;
        flex-direction: column;
    }

    .footer-cta-content h2 {
        font-size: 22px;
    }

    .footer-cta-button {
        min-height: 46px;
    }

    .footer-bottom-inner {
        align-items: flex-start;
        flex-direction: column;
    }
}


/* =========================================================
   MOBILE
========================================================= */

@media (max-width: 480px) {

    .footer-container {
        padding-left: 20px;
        padding-right: 20px;
    }

    .footer-main {
        padding: 48px 0 35px;
    }

    .footer-main .footer-container {
        grid-template-columns: 1fr;
        gap: 35px;
    }

    .footer-logo-image {
        width: 150px;
    }

    .footer-description {
        max-width: 100%;
        font-size: 14px;
        line-height: 1.75;
    }

    .footer-title {
        margin-bottom: 20px;
        font-size: 17px;
    }

    .footer-links {
        gap: 11px;
    }

    .footer-links a,
    .footer-contact-item {
        font-size: 14px;
    }

    .footer-social a {
        width: 38px;
        height: 38px;
    }

    .footer-cta {
        padding: 28px 0;
    }

    .footer-cta-inner {
        align-items: flex-start;
        flex-direction: column;
        gap: 20px;
    }

    .footer-cta-content h2 {
        font-size: 20px;
    }

    .footer-cta-content p {
        font-size: 14px;
    }

    .footer-cta-button {
        width: 100%;
        min-height: 46px;
    }

    .footer-bottom {
        padding: 18px 0;
    }

    .footer-bottom-inner {
        align-items: flex-start;
        flex-direction: column;
        gap: 12px;
    }

    .footer-legal-links {
        flex-wrap: wrap;
        gap: 10px 18px;
    }

    .footer-copyright,
    .footer-legal-links a {
        font-size: 12px;
    }
}


/* =========================================================
   SMALL MOBILE
========================================================= */

@media (max-width: 360px) {

    .footer-container {
        padding-left: 16px;
        padding-right: 16px;
    }

    .footer-main {
        padding-top: 42px;
    }

    .footer-logo-image {
        width: 140px;
    }

    .footer-title {
        font-size: 16px;
    }

    .footer-description,
    .footer-links a,
    .footer-contact-item {
        font-size: 13px;
    }

    .footer-cta-content h2 {
        font-size: 19px;
    }

    .footer-cta-content p {
        font-size: 13px;
    }
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .footer-social a:hover,
    .footer-links a:hover,
    .footer-cta-button:hover {
        transform: none;
    }

    .footer-social a:active {
        transform: scale(0.96);
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .footer-social a,
    .footer-links a,
    .footer-links a::before,
    .footer-contact-item a,
    .footer-cta-button,
    .footer-cta-button i {
        transition: none;
    }
}






