/* =========================================================
   HOME 1
   HERO SECTION
   PART 2 — MAIN CSS
========================================================= */


/* =========================================================
   HERO SECTION BASE
========================================================= */

.hero-section {
    position: relative;
    width: 100%;
    min-height: 680px;
    overflow: hidden;
    isolation: isolate;
}

.hero-slider {
    position: relative;
    width: 100%;
    min-height: 680px;
}


/* =========================================================
   HERO SLIDES
========================================================= */

.hero-slide {
    position: absolute;
    inset: 0;

    width: 100%;
    min-height: 680px;

    display: flex;
    align-items: center;
    justify-content: center;

    background-position: center;
    background-repeat: no-repeat;
    background-size: cover;

    opacity: 0;
    visibility: hidden;

    transition:
        opacity 0.8s ease,
        visibility 0.8s ease;

    z-index: 1;
}

.hero-slide.active {
    opacity: 1;
    visibility: visible;
    z-index: 2;
}


/* =========================================================
   HERO OVERLAY
========================================================= */

.hero-overlay {
    position: absolute;
    inset: 0;

    width: 100%;
    height: 100%;

    background:
        linear-gradient(
            90deg,
            rgba(0, 0, 0, 0.68) 0%,
            rgba(0, 0, 0, 0.50) 45%,
            rgba(0, 0, 0, 0.38) 100%
        );

    z-index: -1;
}


/* =========================================================
   HERO CONTAINER
========================================================= */

.hero-container {
    position: relative;

    width: 100%;
    max-width: 1700px;

    margin: 0 auto;
    padding: 60px 30px;

    display: flex;
    align-items: center;
    justify-content: center;

    text-align: center;

    z-index: 2;
}


/* =========================================================
   HERO CONTENT
========================================================= */

.hero-content {
    width: 100%;
    max-width: 900px;

    margin: 0 auto;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}


/* =========================================================
   HERO SUBTITLE
========================================================= */

.hero-subtitle {
    display: inline-block;

    margin-bottom: 18px;

    color: #ffffff;

    font-family: "Inter", sans-serif;
    font-size: 15px;
    font-weight: 600;
    line-height: 1.5;

    letter-spacing: 0.8px;
    text-transform: uppercase;
}


/* =========================================================
   HERO TITLE
========================================================= */

.hero-title {
    max-width: 900px;

    margin: 0;

    color: #ffffff;

    font-family: "Inter", sans-serif;
    font-size: 58px;
    font-weight: 800;
    line-height: 1.12;

    letter-spacing: -1.5px;
}

.hero-title span {
    display: block;

    margin-top: 4px;

    color: #ff704d;
}


/* =========================================================
   HERO DESCRIPTION
========================================================= */

.hero-description {
    max-width: 720px;

    margin: 22px auto 0;

    color: rgba(255, 255, 255, 0.90);

    font-family: "Inter", sans-serif;
    font-size: 17px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   HERO BUTTONS
========================================================= */

.hero-buttons {
    display: flex;
    align-items: center;
    justify-content: center;

    gap: 14px;

    margin-top: 32px;
}


/* =========================================================
   HERO BUTTON BASE
========================================================= */

.hero-button {
    min-height: 50px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    gap: 10px;

    padding: 0 25px;

    border-radius: 8px;

    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;

    line-height: 1;
    text-decoration: none;
    white-space: nowrap;

    transition:
        background-color 0.25s ease,
        color 0.25s ease,
        border-color 0.25s ease,
        transform 0.25s ease;
}

.hero-button i {
    font-size: 13px;

    transition: transform 0.25s ease;
}


/* =========================================================
   PRIMARY BUTTON
========================================================= */

.hero-button-primary {
    border: 2px solid #ff5a36;

    background: #ff5a36;
    color: #ffffff;
}

.hero-button-primary:hover {
    border-color: #ff704d;
    background: #ff704d;
    color: #ffffff;

    transform: translateY(-2px);
}

.hero-button-primary:hover i {
    transform: translateX(3px);
}


/* =========================================================
   SECONDARY BUTTON
========================================================= */

.hero-button-secondary {
    border: 2px solid #ffffff;

    background: transparent;
    color: #ffffff;
}

.hero-button-secondary:hover {
    border-color: #ffffff;
    background: #ffffff;
    color: #ff5a36;

    transform: translateY(-2px);
}

.hero-button-secondary:hover i {
    transform: translateX(3px);
}


/* =========================================================
   HERO INDICATORS
========================================================= */

.hero-indicators {
    position: absolute;

    left: 50%;
    bottom: 28px;

    transform: translateX(-50%);

    display: flex;
    align-items: center;
    justify-content: center;

    gap: 9px;

    z-index: 10;
}

.hero-indicator {
    width: 9px;
    height: 9px;

    margin: 0;
    padding: 0;

    border: 0;
    border-radius: 50%;

    background: rgba(255, 255, 255, 0.55);

    cursor: pointer;

    transition:
        width 0.25s ease,
        background-color 0.25s ease,
        opacity 0.25s ease;
}

.hero-indicator.active {
    width: 28px;

    border-radius: 10px;

    background: #ff5a36;
}

.hero-indicator:hover {
    opacity: 0.85;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .hero-overlay {
    background:
        linear-gradient(
            90deg,
            rgba(0, 0, 0, 0.76) 0%,
            rgba(0, 0, 0, 0.58) 45%,
            rgba(0, 0, 0, 0.45) 100%
        );
}

body.dark-mode .hero-title span {
    color: #ff704d;
}

body.dark-mode .hero-button-primary {
    background: #e94a28;
    border-color: #e94a28;
}

body.dark-mode .hero-button-primary:hover {
    background: #ff704d;
    border-color: #ff704d;
}

body.dark-mode .hero-button-secondary:hover {
    color: #e94a28;
}

body.dark-mode .hero-indicator.active {
    background: #e94a28;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .hero-section,
body.rtl .hero-section {
    direction: rtl;
}

html[dir="rtl"] .hero-button i,
body.rtl .hero-button i {
    transform: rotate(180deg);
}

html[dir="rtl"] .hero-button:hover i,
body.rtl .hero-button:hover i {
    transform: rotate(180deg) translateX(3px);
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .hero-button-primary:hover,
    .hero-button-secondary:hover {
        transform: none;
    }

    .hero-indicator:hover {
        opacity: 1;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .hero-slide,
    .hero-button,
    .hero-button i,
    .hero-indicator {
        transition: none;
    }
}

