/* =========================================================
   SECTION HEADER
========================================================= */

.how-it-works-header {
    max-width: 760px;
    margin: 0 auto 60px;
    text-align: center;
}

.how-it-works-header .section-subtitle {
    display: inline-block;
    margin-bottom: 10px;
    color: var(--color-primary);
    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.4;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.how-it-works-header .section-title {
    margin: 0;
    color: var(--color-text);
    font-family: "Inter", sans-serif;
    font-size: 44px;
    font-weight: 800;
    line-height: 1.2;
}

.how-it-works-header .section-title span {
    color: var(--color-primary);
}

.how-it-works-header .section-description {
    max-width: 680px;
    margin: 18px auto 0;
    color: var(--color-text-muted);
    font-family: "Inter", sans-serif;
    font-size: 16px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   STEPS WRAPPER
========================================================= */

.how-it-works-steps {
    position: relative;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 30px;
}


/* =========================================================
   CONNECTING LINE
========================================================= */

.how-it-works-steps::before {
    content: "";
    position: absolute;
    top: 42px;
    left: 12.5%;
    right: 12.5%;
    height: 2px;
    background: var(--color-primary);
    opacity: 0.35;
    z-index: 0;
}


/* =========================================================
   INDIVIDUAL STEP
========================================================= */

.how-it-works-step {
    position: relative;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    z-index: 1;
}


/* =========================================================
   STEP NUMBER
========================================================= */

.step-number {
    width: 84px;
    height: 84px;
    flex: 0 0 84px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 26px;
    background: var(--color-bg);
    border: 2px solid var(--color-primary);
    border-radius: 50%;
    box-shadow: 0 0 0 8px var(--color-bg);
}

.step-number span {
    color: var(--color-primary);
    font-family: "Inter", sans-serif;
    font-size: 22px;
    font-weight: 800;
    line-height: 1;
}


/* =========================================================
   STEP CONTENT
========================================================= */

.step-content {
    max-width: 300px;
}

.step-content h3 {
    margin: 0;
    color: var(--color-text);
    font-family: "Inter", sans-serif;
    font-size: 20px;
    font-weight: 750;
    line-height: 1.35;
}

.step-content p {
    margin: 12px 0 0;
    color: var(--color-text-muted);
    font-family: "Inter", sans-serif;
    font-size: 14px;
    font-weight: 400;
    line-height: 1.65;
}


/* =========================================================
   HOVER EFFECT
========================================================= */

.how-it-works-step {
    transition: transform 0.25s ease;
}

.how-it-works-step:hover {
    transform: translateY(-5px);
}

.how-it-works-step:hover .step-number {
    background: var(--color-primary);
}

.how-it-works-step:hover .step-number span {
    color: black;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .how-it-works-section {
    background: var(--color-bg);
    border-top-color: var(--color-border);
}

body.dark-mode .step-number {
    background: var(--color-bg);
    box-shadow: 0 0 0 8px var(--color-bg);
}

body.dark-mode .how-it-works-step:hover .step-number {
    background: var(--color-primary);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .how-it-works-header {
    text-align: center;
}

html[dir="rtl"] .how-it-works-step {
    text-align: center;
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.how-it-works-step:focus-within .step-number {
    outline: 3px solid rgba(255, 90, 54, 0.25);
    outline-offset: 3px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .how-it-works-step {
        transition: none;
    }

}


