/* =========================================================
   PAINTCRAFT HOME 2
   SECTION 2 - WHAT WE OFFER
   PART 2 - MAIN CSS
========================================================= */


/* =========================================================
   SECTION
========================================================= */

.home2-offer-section {
    width: 100%;
    padding: 90px 0;
    background: var(--color-bg);
    overflow: hidden;
}

.home2-offer-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.home2-offer-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 48px;
    text-align: center;
}

.home2-offer-eyebrow {
    display: block;
    margin: 0 0 12px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 2.5px;
    text-transform: uppercase;
}

.home2-offer-title {
    margin: 0;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1px;
}

.home2-offer-title span {
    color: var(--color-orange);
}

.home2-offer-description {
    max-width: 680px;
    margin: 18px auto 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   SERVICES GRID
========================================================= */

.home2-offer-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));

    gap: 30px;
}


/* =========================================================
   SERVICE CARD
========================================================= */

.home2-offer-card {
    min-width: 0;

    background: var(--color-bg);
    border: 1px solid var(--color-border);

    overflow: hidden;

    transition:
        transform var(--transition-fast),
        border-color var(--transition-fast),
        box-shadow var(--transition-fast);
}

.home2-offer-card:hover {
    transform: translateY(-5px);

    border-color: rgba(255, 90, 54, 0.25);

    box-shadow: 0 16px 35px rgba(0, 0, 0, 0.08);
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.home2-offer-image-wrapper {
    position: relative;

    width: 100%;
    height: 270px;

    overflow: hidden;

    background: var(--color-surface);
}


/* =========================================================
   IMAGE
========================================================= */

.home2-offer-image {
    width: 100%;
    height: 100%;

    display: block;

    object-fit: cover;

    transition: transform 0.55s ease;
}

.home2-offer-card:hover .home2-offer-image {
    transform: scale(1.04);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.home2-offer-image-overlay {
    position: absolute;
    inset: 0;

    background:
        linear-gradient(
            to bottom,
            rgba(0, 0, 0, 0.05),
            rgba(0, 0, 0, 0.25)
        );

