========================================================= */

.home2-color-gallery {
    width: 100%;
    max-width: 1550px;
    margin: 0 auto;

    display: grid;
    grid-template-columns:
        minmax(0, 0.82fr)
        minmax(0, 0.82fr)
        minmax(0, 1.45fr);

    grid-template-rows: 410px 410px;

    gap: 24px;

    align-items: stretch;
    box-sizing: border-box;
}


/* =========================================================
   COLOR CARD
========================================================= */

.home2-color-card {
    position: relative;
    min-width: 0;
    width: 100%;
    height: 100%;

    margin: 0;
    padding: 0;

    overflow: hidden;

    box-sizing: border-box;
}

.home2-color-image-wrapper {
    position: relative;

    width: 100%;
    height: 100%;

    overflow: hidden;

    background: var(--color-surface);
}

.home2-color-image {
    display: block;

    width: 100%;
    height: 100%;

    margin: 0;
    padding: 0;

    object-fit: cover;

    transition:
        transform 0.7s ease,
        filter 0.5s ease;
}


/* =========================================================
   GALLERY POSITIONING
========================================================= */

/* Left top */
.home2-color-card:nth-child(1) {
    grid-column: 1;
    grid-row: 1;
}

/* Center tall */
.home2-color-card:nth-child(2) {
    grid-column: 2;
    grid-row: 1 / 3;
}

/* Right wide top */
.home2-color-card:nth-child(3) {
    grid-column: 3;
    grid-row: 1;
}

/* Left bottom */
.home2-color-card:nth-child(4) {
    grid-column: 1;
    grid-row: 2;
}

/* Right lower left */
.home2-color-card:nth-child(5) {
    grid-column: 3;
    grid-row: 2;
    width: calc(50% - 12px);
}

/* Right lower middle */
.home2-color-card:nth-child(6) {
    grid-column: 3;
    grid-row: 2;
    margin-left: calc(50% + 12px);
    width: calc(50% - 12px);
}

/* Additional cards */
.home2-color-card:nth-child(7),
.home2-color-card:nth-child(8) {
    display: none;
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.home2-color-overlay {
    position: absolute;
    inset: 0;

    background: linear-gradient(
        180deg,
        rgba(0, 0, 0, 0) 35%,
        rgba(0, 0, 0, 0.28) 100%
    );

    opacity: 0;

    transition: opacity 0.4s ease;

    pointer-events: none;
}


/* =========================================================
   PICK YOUR COLOR ACTION
========================================================= */

.home2-color-action {
    position: absolute;

    left: 50%;
    bottom: 25px;

    transform:
        translateX(-50%)
        translateY(15px);

    display: flex;
    flex-direction: column;
    align-items: center;

    opacity: 0;
    visibility: hidden;

    transition:
        opacity 0.4s ease,
        visibility 0.4s ease,
        transform 0.4s ease;

    z-index: 3;
}


/* =========================================================
   PICK YOUR COLOR LABEL
========================================================= */

.home2-color-action-title {
    position: relative;

    display: inline-flex;
    align-items: center;
    justify-content: center;

