html[dir="rtl"] .home2-color-gallery-section {
    direction: rtl;
}

html[dir="rtl"] .home2-color-gallery {
    direction: rtl;
}

html[dir="rtl"] .home2-color-swatch + .home2-color-swatch {
    border-left: 0;
    border-right: 1px solid rgba(255, 255, 255, 0.65);
}

html[dir="rtl"] .home2-color-gallery-button:hover i {
    transform: translateX(-3px);
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .home2-color-card:hover .home2-color-image {
        transform: none;
        filter: none;
    }

    .home2-color-card:hover .home2-color-overlay {
        opacity: 0;
    }

    .home2-color-card:hover .home2-color-action {
        opacity: 0;
        visibility: hidden;
        transform:
            translateX(-50%)
            translateY(15px);
    }

    .home2-color-gallery-button:hover {
        transform: none;
        box-shadow: none;
    }

}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.home2-color-gallery-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.35);
    outline-offset: 4px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .home2-color-image,
    .home2-color-overlay,
    .home2-color-action,
    .home2-color-gallery-button,
    .home2-color-gallery-button i {
        transition: none;
    }

}

/* =========================================================
   HOME 2
   SECTION 8: FAQ
   PART 2 - MAIN CSS
========================================================= */

.home2-faq-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
}

.home2-faq-container {
    width: 100%;
    max-width: 1550px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   HEADER
========================================================= */

.home2-faq-header {
    width: 100%;
    max-width: 900px;
    margin: 0 auto 52px;
    text-align: center;
}

.home2-faq-eyebrow {
    display: block;
    margin: 0 0 14px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 3px;
    text-transform: uppercase;
}

.home2-faq-title {
    margin: 0;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1.2px;
}

.home2-faq-title span {
    color: var(--color-orange);
}

.home2-faq-description {
    max-width: 720px;
    margin: 18px auto 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   FAQ TABS
========================================================= */

.home2-faq-tabs {
    width: 100%;
    max-width: 1050px;
    margin: 0 auto 45px;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 18px;

    flex-wrap: wrap;
}

.home2-faq-tab {
    min-width: 190px;
    min-height: 56px;

    padding: 0 26px;

    border: 2px solid var(--color-border);
    border-radius: 40px;

    background: var(--color-surface);
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 700;
    line-height: 1;

    cursor: pointer;
    white-space: nowrap;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        border-color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-faq-tab:hover {
    border-color: var(--color-orange);
    color: var(--color-orange);
    transform: translateY(-2px);
}

.home2-faq-tab.active {
    border-color: var(--color-orange);
    background: var(--color-orange);
    color: #ffffff;

    box-shadow:
        0 8px 20px rgba(255, 90, 54, 0.16);
}

.home2-faq-tab.active:hover {
    color: #ffffff;
    transform: translateY(-2px);
}


/* =========================================================
   FAQ LIST
========================================================= */

.home2-faq-list {
    width: 100%;
    max-width: 1350px;
    margin: 0 auto;

    display: flex;
    flex-direction: column;
    gap: 16px;
}


/* =========================================================
   FAQ ITEM
========================================================= */

.home2-faq-item {
    width: 100%;
    margin: 0;

    background: var(--color-surface);
    border: 1px solid var(--color-border);

    box-sizing: border-box;

    transition:
        border-color 0.3s ease,
        background 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-faq-item.active {
    border-color: var(--color-orange);
    background: var(--color-orange);

    box-shadow:
        0 10px 30px rgba(255, 90, 54, 0.12);
}


/* =========================================================
   QUESTION
========================================================= */

.home2-faq-question {
    width: 100%;
    min-height: 78px;

    margin: 0;
    padding: 18px 28px;

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;

    border: 0;
    outline: none;

    background: transparent;
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.4;

    text-align: left;
    cursor: pointer;

    box-sizing: border-box;
}

.home2-faq-question > span:first-child {
    min-width: 0;
    flex: 1;
}

.home2-faq-item.active .home2-faq-question {
    color: #ffffff;
}


/* =========================================================
   FAQ ICON
========================================================= */

.home2-faq-icon {
    flex: 0 0 46px;

    width: 46px;
    height: 46px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 2px solid var(--color-text);
    border-radius: 50%;

    background: transparent;
    color: var(--color-text);

    box-sizing: border-box;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        border-color 0.3s ease,
        transform 0.3s ease;
}

.home2-faq-icon i {
    font-size: 14px;
    line-height: 1;
}

.home2-faq-item.active .home2-faq-icon {
    border-color: #ffffff;
    background: #ffffff;
    color: var(--color-orange);
}


/* =========================================================
   ANSWER
========================================================= */

.home2-faq-answer {
    width: 100%;

    max-height: 0;
    overflow: hidden;

    padding: 0 28px;

    box-sizing: border-box;

    transition:
        max-height 0.4s ease,
        padding 0.4s ease;
}

.home2-faq-item.active .home2-faq-answer {
    max-height: 300px;
    padding: 0 28px 27px;
}

.home2-faq-answer p {
    max-width: 1120px;

    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.75;
}

.home2-faq-item.active .home2-faq-answer p {
    color: rgba(255, 255, 255, 0.92);
}


/* =========================================================
   FAQ FOOTER
========================================================= */

.home2-faq-footer {
    width: 100%;
    margin: 45px auto 0;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 22px;

    text-align: center;
}

.home2-faq-footer p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 500;
    line-height: 1.5;
}


/* =========================================================
   CONTACT BUTTON
========================================================= */

.home2-faq-contact-button {
    min-height: 48px;

    padding: 0 22px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;

    border: 2px solid var(--color-orange);
    border-radius: 30px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    line-height: 1;

    text-decoration: none;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-faq-contact-button i {
    font-size: 13px;

    transition: transform 0.3s ease;
}

.home2-faq-contact-button:hover {
    background: transparent;
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 10px 25px rgba(255, 90, 54, 0.15);
}

.home2-faq-contact-button:hover i {
    transform: translateX(3px);
}


/* =========================================================
   FOCUS
========================================================= */

.home2-faq-tab:focus-visible,
.home2-faq-question:focus-visible,
.home2-faq-contact-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.3);
    outline-offset: 4px;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-faq-section {
    background: var(--color-bg);
}

body.dark-mode .home2-faq-tab {
    background: var(--color-surface);
}

body.dark-mode .home2-faq-item {
    background: var(--color-surface);
}

body.dark-mode .home2-faq-item.active {
    background: var(--color-orange);
}

body.dark-mode .home2-faq-icon {
    border-color: var(--color-text);
    color: var(--color-text);
}

body.dark-mode .home2-faq-item.active .home2-faq-icon {
    border-color: #ffffff;
    background: #ffffff;
    color: var(--color-orange);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .home2-faq-section {
    direction: rtl;
}

html[dir="rtl"] .home2-faq-header,
html[dir="rtl"] .home2-faq-tabs,
html[dir="rtl"] .home2-faq-footer {
    direction: rtl;
}

html[dir="rtl"] .home2-faq-question {
    text-align: right;
}

html[dir="rtl"] .home2-faq-answer p {
    text-align: right;
}

html[dir="rtl"] .home2-faq-contact-button:hover i {
    transform: translateX(-3px);
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .home2-faq-tab:hover {
        transform: none;
        box-shadow: none;
    }

    .home2-faq-contact-button:hover {
        transform: none;
        box-shadow: none;
    }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .home2-faq-tab,
    .home2-faq-item,
    .home2-faq-icon,
    .home2-faq-answer,
    .home2-faq-contact-button,
    .home2-faq-contact-button i {
        transition: none;
    }

}

/* =========================================================
   HOME 2
   SECTION 9: GET A FREE QUOTE
   PART 2 - MAIN CSS
========================================================= */

.home2-quote-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-surface);
    overflow: hidden;
}

.home2-quote-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;

    display: grid;
    grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
    gap: 70px;
    align-items: stretch;

    box-sizing: border-box;
}


/* =========================================================
   LEFT VISUAL
========================================================= */

.home2-quote-visual {
    position: relative;
    min-width: 0;
    min-height: 700px;

    overflow: hidden;

    background: var(--color-bg);
    box-sizing: border-box;
}

.home2-quote-image-wrapper {
    position: absolute;
    inset: 0;

    width: 100%;
    height: 100%;

    overflow: hidden;
}

.home2-quote-image {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    transition: transform 0.7s ease;
}

.home2-quote-visual:hover .home2-quote-image {
    transform: scale(1.04);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.home2-quote-image-overlay {
    position: absolute;
    inset: 0;

    background:
        linear-gradient(
            180deg,
            rgba(0, 0, 0, 0.08) 15%,
            rgba(0, 0, 0, 0.18) 40%,
            rgba(0, 0, 0, 0.82) 100%
        );

    pointer-events: none;
}


/* =========================================================
   VISUAL CONTENT
========================================================= */

.home2-quote-visual-content {
    position: absolute;
    left: 45px;
    right: 45px;
    bottom: 45px;

    z-index: 2;
}

.home2-quote-visual-eyebrow {
    display: block;

    margin: 0 0 13px;

    color: #ffffff;

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 2.4px;
    text-transform: uppercase;
}

.home2-quote-visual-title {
    max-width: 600px;

    margin: 0;

    color: #ffffff;

    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -1.2px;
}

.home2-quote-visual-title span {
    display: block;
    color: var(--color-orange);
}

.home2-quote-visual-description {
    max-width: 520px;

    margin: 18px 0 0;

    color: rgba(255, 255, 255, 0.88);

    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   EXPERIENCE CARD
========================================================= */

.home2-quote-experience-card {
    position: absolute;

    top: 35px;
    left: 35px;

    z-index: 3;

    min-width: 190px;
    min-height: 78px;

    padding: 12px 18px;

    display: flex;
    align-items: center;
    gap: 13px;

    background: #ffffff;

    box-shadow:
        0 12px 30px rgba(0, 0, 0, 0.14);

    box-sizing: border-box;
}

.home2-quote-experience-icon {
    flex: 0 0 44px;

    width: 44px;
    height: 44px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: var(--color-orange);
    color: #ffffff;
}

.home2-quote-experience-icon i {
    font-size: 17px;
}

.home2-quote-experience-content {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.home2-quote-experience-content strong {
    color: #202020;

    font-family: var(--font-family);
    font-size: 22px;
    font-weight: 800;
    line-height: 1;
}

.home2-quote-experience-content span {
    color: #666666;

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 600;
    line-height: 1.3;
}


/* =========================================================
   RIGHT CONTENT
========================================================= */

.home2-quote-content {
    min-width: 0;

    padding: 35px 0;

    display: flex;
    flex-direction: column;
    justify-content: center;

    box-sizing: border-box;
}

.home2-quote-header {
    width: 100%;
    max-width: 650px;
    margin-bottom: 30px;
}

.home2-quote-eyebrow {
    display: block;

    margin: 0 0 12px;

    color: var(--color-orange);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 2.7px;
    text-transform: uppercase;
}

.home2-quote-title {
    margin: 0;

    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 44px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1px;
}

.home2-quote-title span {
    color: var(--color-orange);
}

.home2-quote-description {
    max-width: 590px;

    margin: 15px 0 0;

    color: var(--color-text-muted);

    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   FORM
========================================================= */

.home2-quote-form {
    width: 100%;
    max-width: 720px;

    display: grid;
    grid-template-columns:
        minmax(0, 1fr)
        minmax(0, 1fr);

    column-gap: 20px;
    row-gap: 18px;

    box-sizing: border-box;
}

.home2-quote-field {
    width: 100%;
    min-width: 0;

    display: flex;
    flex-direction: column;
    gap: 8px;

    box-sizing: border-box;
}

.home2-quote-field-full {
    grid-column: 1 / -1;
}


/* =========================================================
   LABEL
========================================================= */

.home2-quote-field label {
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    line-height: 1.4;
}


/* =========================================================
   INPUT WRAPPER
========================================================= */

.home2-quote-input-wrapper {
    position: relative;

    width: 100%;
    min-width: 0;
}

.home2-quote-input-wrapper > i:first-child {
    position: absolute;

    top: 50%;
    left: 17px;

    color: var(--color-orange);

    font-size: 14px;

    transform: translateY(-50%);

    pointer-events: none;
    z-index: 2;
}


/* =========================================================
   INPUT / SELECT / TEXTAREA
========================================================= */

.home2-quote-input-wrapper input,
.home2-quote-input-wrapper select,
.home2-quote-input-wrapper textarea {
    width: 100%;

    margin: 0;
    padding: 0 17px 0 46px;

    border: 1px solid var(--color-border);
    border-radius: var(--radius-small);

    outline: none;

    background: var(--color-bg);
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 400;

    box-sizing: border-box;

    transition:
        border-color 0.25s ease,
        box-shadow 0.25s ease,
        background 0.25s ease;
}

.home2-quote-input-wrapper input,
.home2-quote-input-wrapper select {
    height: 52px;
}

.home2-quote-input-wrapper textarea {
    min-height: 120px;

    padding-top: 15px;
    padding-bottom: 15px;

    resize: vertical;
    line-height: 1.6;
}


/* =========================================================
   SELECT
========================================================= */

.home2-quote-input-wrapper select {
    appearance: none;
    -webkit-appearance: none;

    padding-right: 45px;

    cursor: pointer;
}

.home2-quote-select-icon {
    position: absolute;

    top: 50%;
    right: 17px;

    color: var(--color-text-muted);

    font-size: 11px;

    transform: translateY(-50%);

    pointer-events: none;
}


/* =========================================================
   TEXTAREA ICON
========================================================= */

.home2-quote-textarea-wrapper > i:first-child {
    top: 20px;

    transform: none;
}


/* =========================================================
   PLACEHOLDER
========================================================= */

.home2-quote-input-wrapper input::placeholder,
.home2-quote-input-wrapper textarea::placeholder {
    color: var(--color-text-muted);
    opacity: 0.75;
}


/* =========================================================
   FOCUS
========================================================= */

.home2-quote-input-wrapper input:focus,
.home2-quote-input-wrapper select:focus,
.home2-quote-input-wrapper textarea:focus {
    border-color: var(--color-orange);

    box-shadow:
        0 0 0 3px rgba(255, 90, 54, 0.10);
}


/* =========================================================
   SUBMIT AREA
========================================================= */

.home2-quote-submit-area {
    grid-column: 1 / -1;

    width: 100%;

    margin-top: 5px;

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;

    box-sizing: border-box;
}


/* =========================================================
   SUBMIT BUTTON
========================================================= */

.home2-quote-submit-button {
    min-height: 54px;

    padding: 0 24px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 13px;

    border: 2px solid var(--color-orange);
    border-radius: 4px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 750;
    line-height: 1;

    cursor: pointer;

    box-sizing: border-box;

    transition:
        background 0.3s ease,
        color 0.3s ease,
        border-color 0.3s ease,
        transform 0.3s ease,
        box-shadow 0.3s ease;
}

.home2-quote-submit-button i {
    font-size: 13px;

    transition: transform 0.3s ease;
}

.home2-quote-submit-button:hover {
    background: transparent;
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 10px 25px rgba(255, 90, 54, 0.14);
}

.home2-quote-submit-button:hover i {
    transform: translateX(4px);
}


/* =========================================================
   SECURITY NOTE
========================================================= */

.home2-quote-note {
    margin: 0;

    display: flex;
    align-items: center;
    gap: 7px;

    color: var(--color-text-muted);

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 500;
    line-height: 1.4;

    white-space: nowrap;
}

.home2-quote-note i {
    color: var(--color-orange);
    font-size: 12px;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-quote-section {
    background: var(--color-surface);
}

body.dark-mode .home2-quote-experience-card {
    background: var(--color-bg);
}

body.dark-mode .home2-quote-experience-content strong {
    color: var(--color-text);
}

body.dark-mode .home2-quote-experience-content span {
    color: var(--color-text-muted);
}

body.dark-mode .home2-quote-input-wrapper input,
body.dark-mode .home2-quote-input-wrapper select,
body.dark-mode .home2-quote-input-wrapper textarea {
    background: var(--color-bg);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .home2-quote-section {
    direction: rtl;
}

html[dir="rtl"] .home2-quote-container {
    direction: rtl;
}

html[dir="rtl"] .home2-quote-visual-content {
    left: 45px;
    right: 45px;
}

html[dir="rtl"] .home2-quote-input-wrapper > i:first-child {
    left: auto;
    right: 17px;
}

html[dir="rtl"] .home2-quote-input-wrapper input,
html[dir="rtl"] .home2-quote-input-wrapper select,
html[dir="rtl"] .home2-quote-input-wrapper textarea {
    padding-left: 17px;
    padding-right: 46px;

    text-align: right;
}

