.home2-promo-shape-circle {
    left: 47%;
    bottom: -70px;

    width: 140px;
    height: 140px;

    border-radius: 50%;

    background: rgba(255, 255, 255, 0.10);
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home2-promo-section {
