/* =========================================================
   PAINTCRAFT RUNNING MARQUEE
   PART 2 — MAIN CSS
========================================================= */

.paintcraft-marquee-section {
    width: 100%;
    overflow: hidden;
    background: var(--color-orange);
    padding: 22px 0;
    box-sizing: border-box;
}

.paintcraft-marquee-track {
    width: max-content;
    display: flex;
    align-items: center;
    white-space: nowrap;
    animation: paintcraftMarquee 28s linear infinite;
    will-change: transform;
}

.paintcraft-marquee-content {
    display: flex;
    align-items: center;
    flex-shrink: 0;
}

.paintcraft-marquee-item {
    display: inline-flex;
    align-items: center;
    color: #ffffff;
    font-family: var(--font-family);
    font-size: 30px;
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: -0.5px;
    white-space: nowrap;
}

.paintcraft-marquee-star {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin: 0 42px;
    color: #ffffff;
    font-size: 25px;
    font-weight: 700;
    line-height: 1;
}


/* =========================================================
   RUNNING ANIMATION
========================================================= */

@keyframes paintcraftMarquee {
    from {
        transform: translateX(0);
    }

    to {
        transform: translateX(-50%);
    }
}


/* =========================================================
   HOVER
========================================================= */

.paintcraft-marquee-section:hover .paintcraft-marquee-track {
    animation-play-state: paused;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .paintcraft-marquee-section {
    background: var(--color-dark-orange);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .paintcraft-marquee-track {
    animation-direction: reverse;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .paintcraft-marquee-track {
        animation: none;
        transform: translateX(0);
    }
}


/* =========================================================
   ABOUT US
   SECTION 3: OUR STORY
   PART 2 — MAIN CSS
========================================================= */

.about-story-section {
