}


/* =========================================================
   SLIDES WRAPPER
========================================================= */

.painting-intro-slides {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
    background: #111;
}


/* =========================================================
   INDIVIDUAL SLIDE
========================================================= */

.painting-intro-slide {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    opacity: 0;
    visibility: hidden;
    transform: scale(1.03);
    transition:
        opacity 0.7s ease,
        visibility 0.7s ease,
        transform 1s ease;
}


.painting-intro-slide.active {
    opacity: 1;
    visibility: visible;
    transform: scale(1);
}


/* =========================================================
   SLIDE IMAGE
========================================================= */

.painting-intro-slide-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
}


/* =========================================================
   LEFT VERTICAL CONTROLS
========================================================= */

.painting-intro-slider-controls {
    position: absolute;
    left: -1px;
    top: 50%;
    width: 88px;
    height: 176px;
    transform: translateY(-50%);
    z-index: 10;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
}


/* =========================================================
   SLIDER BUTTON
========================================================= */

.painting-intro-slider-button {
    width: 88px;
    height: 88px;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--color-bg);
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 22px;
    cursor: pointer;
    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
    box-sizing: border-box;
}


.painting-intro-slider-button.painting-intro-next {
    background: #071b12;
    color: #fff;
}


.painting-intro-slider-button.painting-intro-prev {
    background: #fff;
    color: #111;
}


/* =========================================================
   BUTTON HOVER
========================================================= */

.painting-intro-slider-button:hover {
    background: var(--color-orange);
    color: #fff;
}


.painting-intro-slider-button:focus-visible {
    outline: 3px solid var(--color-orange);
    outline-offset: -3px;
}


.painting-intro-slider-button i {
    transition: transform var(--transition-fast);
}


.painting-intro-next:hover i {
    transform: translateX(4px);
}


.painting-intro-prev:hover i {
    transform: translateX(-4px);
}


/* =========================================================
   SLIDE DOTS
========================================================= */

.painting-intro-slider-dots {
    position: absolute;
    left: 50%;
    bottom: 24px;
    transform: translateX(-50%);
    z-index: 8;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}


.painting-intro-slider-dot {
    width: 9px;
    height: 9px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.55);
    cursor: pointer;
    transition:
        width var(--transition-fast),
        background-color var(--transition-fast),
        transform var(--transition-fast);
}


.painting-intro-slider-dot.active {
    width: 28px;
    border-radius: 10px;
    background: var(--color-orange);
}


.painting-intro-slider-dot:hover {
    transform: scale(1.15);
}


/* =========================================================
   RIGHT CONTENT
========================================================= */

.painting-intro-content {
    width: 100%;
    max-width: 720px;
    padding: 20px 0;
    box-sizing: border-box;
}


/* =========================================================
   EYEBROW
========================================================= */

.painting-intro-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    margin-bottom: 22px;
    padding-left: 42px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: 4px;
    text-transform: uppercase;
}


.painting-intro-eyebrow::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    width: 30px;
    height: 2px;
    background: var(--color-orange);
    transform: translateY(-50%);
}


/* =========================================================
   TITLE
========================================================= */

.painting-intro-title {
    margin: 0 0 28px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 52px;
    font-weight: 400;
    line-height: 1.08;
    letter-spacing: -1.5px;
}


.painting-intro-title strong {
    display: inline;
    color: var(--color-text);
    font-weight: 800;
}


.painting-intro-title strong::after {
    content: "";
}


/* =========================================================
   DESCRIPTION
========================================================= */

.painting-intro-description {
    max-width: 680px;
    margin: 0 0 34px;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   FEATURES
========================================================= */

.painting-intro-features {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 20px;
    margin-bottom: 34px;
}


.painting-intro-feature {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    width: 100%;
    box-sizing: border-box;
}


.painting-intro-feature-icon {
    flex: 0 0 48px;
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
    font-size: 17px;
    box-sizing: border-box;
}


.painting-intro-feature-content {
    flex: 1;
    min-width: 0;
}


.painting-intro-feature-content h3 {
    margin: 0 0 5px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 700;
    line-height: 1.4;
}


.painting-intro-feature-content p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.6;
}


/* =========================================================
   ACTION BUTTON
========================================================= */

.painting-intro-action {
    display: flex;
    align-items: center;
}


.painting-intro-button {
    min-width: 190px;
    min-height: 58px;
    padding: 6px 8px 6px 26px;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    border: 2px solid var(--color-orange);
    border-radius: 50px;
    background: var(--color-orange);
    color: #fff;
    text-decoration: none;
    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;
    box-sizing: border-box;
    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}


.painting-intro-button i {
    flex: 0 0 44px;
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #fff;
    color: var(--color-orange);
    font-size: 14px;
    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}


.painting-intro-button:hover {
    background: var(--color-dark-orange);
    border-color: var(--color-dark-orange);
    color: #fff;
    transform: translateY(-2px);
    box-shadow: 0 12px 28px rgba(255, 90, 54, 0.20);
}


.painting-intro-button:hover i {
    background: #fff;
    color: var(--color-orange);
    transform: translateX(4px);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .painting-intro-section {
    background: var(--color-bg);
}


html.dark-mode .painting-intro-slider-button.painting-intro-prev {
    background: var(--color-surface);
    color: var(--color-text);
}


html.dark-mode .painting-intro-slider-button.painting-intro-next {
    background: #0b1712;
    color: #fff;
}


html.dark-mode .painting-intro-slider-button:hover {
    background: var(--color-orange);
    color: #fff;
}


html.dark-mode .painting-intro-feature-icon {
    background: rgba(255, 90, 54, 0.14);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .painting-intro-eyebrow {
    padding-left: 0;
    padding-right: 42px;
}


html[dir="rtl"] .painting-intro-eyebrow::before {
    left: auto;
    right: 0;
}


html[dir="rtl"] .painting-intro-slider-controls {
    left: auto;
    right: -1px;
}


html[dir="rtl"] .painting-intro-button {
    padding-left: 8px;
    padding-right: 26px;
}


html[dir="rtl"] .painting-intro-button:hover i {
    transform: translateX(-4px);
}


html[dir="rtl"] .painting-intro-next:hover i {
    transform: translateX(-4px);
}


html[dir="rtl"] .painting-intro-prev:hover i {
    transform: translateX(4px);
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.painting-intro-slider-button:disabled,
.painting-intro-slider-dot:disabled {
    cursor: not-allowed;
    opacity: 0.5;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .painting-intro-slide {
        transition: none;
        transform: none;
    }

    .painting-intro-slider-button,
    .painting-intro-button,
    .painting-intro-slider-dot,
    .painting-intro-slider-button i {
        transition: none;
    }

}



/* =========================================================
   PAINTING PAGE
   SECTION 03: INTERIOR & EXTERIOR PAINTING
   PART 2 - MAIN CSS
========================================================= */


/* =========================================================
   SECTION
========================================================= */

.painting-interior-exterior-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
    box-sizing: border-box;
}


/* =========================================================
   CONTAINER
========================================================= */

.painting-interior-exterior-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.painting-interior-exterior-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 55px;
    text-align: center;
    box-sizing: border-box;
}


.painting-interior-exterior-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    margin-bottom: 18px;
    padding: 0 42px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: 3.5px;
    text-transform: uppercase;
    box-sizing: border-box;
}


.painting-interior-exterior-eyebrow::before,
.painting-interior-exterior-eyebrow::after {
    content: "";
    position: absolute;
    top: 50%;
    width: 28px;
    height: 2px;
    background: var(--color-orange);
    transform: translateY(-50%);
}


.painting-interior-exterior-eyebrow::before {
    left: 0;
}


.painting-interior-exterior-eyebrow::after {
    right: 0;
}


/* =========================================================
   TITLE
========================================================= */

.painting-interior-exterior-title {
    margin: 0 0 20px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 400;
    line-height: 1.12;
    letter-spacing: -1.2px;
}


.painting-interior-exterior-title span {
    color: var(--color-orange);
    font-weight: 800;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.painting-interior-exterior-description {
    max-width: 760px;
    margin: 0 auto;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   CARDS GRID
========================================================= */

.painting-interior-exterior-grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 30px;
    box-sizing: border-box;
}


/* =========================================================
   SERVICE CARD
========================================================= */

.painting-service-card {
    position: relative;
    width: 100%;
    min-width: 0;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 18px;
    overflow: hidden;
    box-sizing: border-box;
    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}


.painting-service-card:hover {
    transform: translateY(-8px);
    border-color: rgba(255, 90, 54, 0.30);
    box-shadow: 0 20px 45px rgba(0, 0, 0, 0.12);
}


/* =========================================================
   CARD LINK
========================================================= */

.painting-service-card-link {
    display: block;
    width: 100%;
    height: 100%;
    color: inherit;
    text-decoration: none;
    box-sizing: border-box;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.painting-service-image-wrapper {
    position: relative;
    width: 100%;
    height: 430px;
    overflow: hidden;
    background: #111;
    box-sizing: border-box;
}


/* =========================================================
   IMAGE
========================================================= */

.painting-service-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition: transform 0.7s ease;
}


.painting-service-card:hover .painting-service-image {
    transform: scale(1.06);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.painting-service-image-overlay {
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
        linear-gradient(
            to top,
            rgba(0, 0, 0, 0.48) 0%,
            rgba(0, 0, 0, 0.08) 55%,
            rgba(0, 0, 0, 0) 100%
        );
    pointer-events: none;
}


/* =========================================================
   CARD NUMBER
========================================================= */

.painting-service-card-number {
    position: absolute;
    top: 22px;
    right: 22px;
    z-index: 3;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    border: 1px solid rgba(255, 255, 255, 0.55);
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.20);
    color: #fff;
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 800;
    backdrop-filter: blur(5px);
    box-sizing: border-box;
    transition:
        background-color var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast);
}


.painting-service-card:hover .painting-service-card-number {
    background: var(--color-orange);
    border-color: var(--color-orange);
    transform: rotate(8deg);
}


/* =========================================================
   CARD CONTENT
========================================================= */

.painting-service-card-content {
    width: 100%;
    padding: 30px 30px 32px;
    box-sizing: border-box;
}


/* =========================================================
   CATEGORY
========================================================= */

.painting-service-category {
    display: block;
    margin-bottom: 10px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    line-height: 1.4;
    letter-spacing: 2.5px;
    text-transform: uppercase;
}


/* =========================================================
   CARD TITLE
========================================================= */

.painting-service-title {
    margin: 0 0 12px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 27px;
    font-weight: 750;
    line-height: 1.25;
    letter-spacing: -0.5px;
}


/* =========================================================
   CARD DESCRIPTION
========================================================= */

.painting-service-description {
    max-width: 650px;
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   CARD ACTION
========================================================= */

.painting-service-card-action {
    width: 100%;
    margin-top: 25px;
    padding-top: 20px;
    border-top: 1px solid var(--color-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    box-sizing: border-box;
}


.painting-service-action-text {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 700;
    line-height: 1.4;
    transition: color var(--transition-fast);
}


.painting-service-action-icon {
    flex: 0 0 42px;
    width: 42px;
    height: 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid var(--color-orange);
    border-radius: 50%;
    background: transparent;
    color: var(--color-orange);
    font-size: 13px;
    box-sizing: border-box;
    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}


.painting-service-card:hover .painting-service-action-text {
    color: var(--color-orange);
}


.painting-service-card:hover .painting-service-action-icon {
    background: var(--color-orange);
    color: #fff;
    transform: translateX(4px);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .painting-service-card-number {
    right: auto;
    left: 22px;
}


html[dir="rtl"] .painting-service-card:hover .painting-service-action-icon {
    transform: translateX(-4px);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .painting-interior-exterior-section {
    background: var(--color-bg);
}


html.dark-mode .painting-service-card {
    background: var(--color-surface);
    border-color: var(--color-border);
}


html.dark-mode .painting-service-card:hover {
    border-color: rgba(255, 90, 54, 0.40);
    box-shadow: 0 20px 45px rgba(0, 0, 0, 0.30);
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.painting-service-card-link:focus-visible {
    outline: 3px solid var(--color-orange);
    outline-offset: -3px;
}


.painting-service-card-link:focus-visible .painting-service-action-icon {
    background: var(--color-orange);
    color: #fff;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .painting-service-card,
    .painting-service-image,
    .painting-service-card-number,
    .painting-service-action-icon {
        transition: none;
    }

    .painting-service-card:hover {
        transform: none;
    }

    .painting-service-card:hover .painting-service-image {
        transform: none;
    }

}


/* =========================================================
   PAINTING PAGE
   SECTION 04: WHY CHOOSE PAINTCRAFT
   PART 2 - MAIN CSS
========================================================= */


/* =========================================================
   SECTION
========================================================= */

.painting-why-section {
    width: 100%;
    padding: 85px 0;
    background: var(--color-bg);
    overflow: hidden;
    box-sizing: border-box;
}


/* =========================================================
   CONTAINER
========================================================= */

.painting-why-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 55px;
    box-sizing: border-box;
}


/* =========================================================
   FEATURE ITEM
========================================================= */

.painting-why-item {
    width: 100%;
    min-width: 0;
    box-sizing: border-box;
}


/* =========================================================
   ICON
========================================================= */

.painting-why-icon {
    width: 58px;
    height: 58px;
    margin-bottom: 25px;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    color: var(--color-orange);
    font-size: 45px;
    line-height: 1;
    box-sizing: border-box;
}


.painting-why-icon i {
    display: block;
    font-size: inherit;
    line-height: 1;
}


/* =========================================================
   CONTENT
========================================================= */

.painting-why-content {
    width: 100%;
    box-sizing: border-box;
}


/* =========================================================
   TITLE
========================================================= */

.painting-why-title {
    margin: 0 0 18px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 25px;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: -0.4px;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.painting-why-description {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   HOVER
========================================================= */

.painting-why-item {
    transition:
        transform var(--transition-fast);
}


.painting-why-item:hover {
    transform: translateY(-5px);
}


.painting-why-icon {
    transition:
        transform var(--transition-fast),
        color var(--transition-fast);
}


.painting-why-item:hover .painting-why-icon {
    transform: translateY(-3px);
    color: var(--color-dark-orange);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .painting-why-icon {
    justify-content: flex-start;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .painting-why-section {
    background: var(--color-bg);
}


html.dark-mode .painting-why-item:hover .painting-why-icon {
    color: var(--color-orange);
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.painting-why-item:focus-within {
    outline: 2px solid rgba(255, 90, 54, 0.35);
    outline-offset: 8px;
    border-radius: 8px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .painting-why-item,
    .painting-why-icon {
        transition: none;
    }

    .painting-why-item:hover {
        transform: none;
    }

    .painting-why-item:hover .painting-why-icon {
        transform: none;
    }

}


/* =========================================================
   PAINTING PAGE
   SECTION 05: OUR PAINTING PROCESS
   PART 2 - MAIN CSS
========================================================= */


/* =========================================================
   SECTION
========================================================= */

.painting-process-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
    box-sizing: border-box;
}


/* =========================================================
   CONTAINER
========================================================= */

.painting-process-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   HEADER
========================================================= */

.painting-process-header {
    width: 100%;
    max-width: 820px;
    margin: 0 auto;
    text-align: center;
    box-sizing: border-box;
}


/* =========================================================
   TITLE
========================================================= */

.painting-process-title {
    margin: 0 0 18px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 400;
    line-height: 1.15;
    letter-spacing: -1.2px;
}


.painting-process-title span {
    color: var(--color-orange);
    font-weight: 800;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.painting-process-description {
    max-width: 720px;
    margin: 0 auto;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   DIVIDER
========================================================= */

.painting-process-divider {
    width: 100%;
    max-width: 750px;
    margin: 38px auto 65px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 30px;
    box-sizing: border-box;
}


.painting-process-divider-line {
    flex: 1;
    height: 1px;
    background: var(--color-border);
}


.painting-process-divider-icon {
    flex: 0 0 48px;
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-orange);
    font-size: 24px;
    box-sizing: border-box;
}


/* =========================================================
   PROCESS GRID
========================================================= */

.painting-process-grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 30px;
    box-sizing: border-box;
}


/* =========================================================
   PROCESS CARD
========================================================= */

.painting-process-step {
    position: relative;
    width: 100%;
    min-width: 0;
    min-height: 320px;
    padding: 60px 30px 35px;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    background: var(--color-surface);
    border: 2px dashed var(--color-border);
    border-radius: 10px;
    box-sizing: border-box;
    transition:
        transform var(--transition-fast),
        border-color var(--transition-fast),
        box-shadow var(--transition-fast);
}


.painting-process-step:hover {
    transform: translateY(-8px);
    border-color: rgba(255, 90, 54, 0.45);
    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.08);
}


/* =========================================================
   STEP ICON
========================================================= */

.painting-process-icon {
    width: 100px;
    height: 100px;
    margin-bottom: 25px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.08);
    color: var(--color-orange);
    font-size: 40px;
    box-sizing: border-box;
    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}


.painting-process-step:hover .painting-process-icon {
    background: var(--color-orange);
    color: #fff;
    transform: scale(1.05);
}


/* =========================================================
   STEP LABEL
========================================================= */

.painting-process-step-label {
    display: block;
    margin-bottom: 9px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: 1px;
}


/* =========================================================
   STEP TITLE
========================================================= */

.painting-process-step-title {
    margin: 0 0 14px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 25px;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: -0.4px;
}


/* =========================================================
   STEP DESCRIPTION
========================================================= */

.painting-process-step-description {
    max-width: 300px;
    margin: 0 auto;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .painting-process-section {
    background: var(--color-bg);
}


html.dark-mode .painting-process-step {
    background: var(--color-surface);
    border-color: var(--color-border);
}


html.dark-mode .painting-process-step:hover {
    border-color: rgba(255, 90, 54, 0.45);
    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.28);
}


html.dark-mode .painting-process-divider-line {
    background: var(--color-border);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .painting-process-step {
    text-align: center;
}


/* =========================================================
   ACCESSIBILITY
========================================================= */

.painting-process-step:focus-within {
    outline: 2px solid rgba(255, 90, 54, 0.35);
    outline-offset: 6px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .painting-process-step,
    .painting-process-icon {
        transition: none;
    }

    .painting-process-step:hover {
        transform: none;
    }

    .painting-process-step:hover .painting-process-icon {
        transform: none;
    }

}


/* =========================================================
   PAINTING PAGE
   SECTION 06: PAINT FINISHES & SOLUTIONS
   PART 2 - MAIN CSS
========================================================= */


/* =========================================================
   SECTION
========================================================= */

.painting-finishes-section {
