    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   DECORATIVE DIVIDER
========================================================= */

.painting-finishes-divider {
    width: 100%;
    max-width: 750px;
    margin: 38px auto 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 28px;
    box-sizing: border-box;
}


.painting-finishes-divider-line {
    flex: 1;
    height: 1px;
    background: var(--color-border);
}


.painting-finishes-divider-icon {
    flex: 0 0 46px;
    width: 46px;
    height: 46px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--color-orange);
    font-size: 24px;
    box-sizing: border-box;
}


/* =========================================================
   CARDS GRID
========================================================= */

.painting-finishes-grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 30px;
    box-sizing: border-box;
}


/* =========================================================
   CARD
========================================================= */

.painting-finish-card {
    width: 100%;
    min-width: 0;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 12px;
    overflow: hidden;
    box-sizing: border-box;
    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}


.painting-finish-card:hover {
    transform: translateY(-7px);
    border-color: rgba(255, 90, 54, 0.30);
    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.10);
}


/* =========================================================
   IMAGE
========================================================= */

.painting-finish-image-wrapper {
    position: relative;
    width: 100%;
    height: 290px;
    overflow: hidden;
    background: var(--color-border);
    box-sizing: border-box;
}


.painting-finish-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition: transform 0.7s ease;
}


.painting-finish-card:hover .painting-finish-image {
    transform: scale(1.06);
}


/* =========================================================
   CARD CONTENT
========================================================= */

.painting-finish-content {
    width: 100%;
    min-height: 260px;
    padding: 30px 28px 28px;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    box-sizing: border-box;
}


/* =========================================================
   CARD TITLE
========================================================= */

.painting-finish-content .painting-finish-title {
    margin: 0 0 14px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 25px;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: -0.4px;
}


/* =========================================================
   CARD DESCRIPTION
========================================================= */

.painting-finish-content .painting-finish-description {
    max-width: 430px;
    margin: 0 auto;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   BUTTON
========================================================= */

.painting-finish-button {
    min-width: 190px;
    min-height: 48px;
    margin-top: auto;
    padding: 5px 6px 5px 22px;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    border: 2px solid var(--color-orange);
    border-radius: 50px;
    background: var(--color-orange);
    color: #fff;
    text-decoration: none;
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    line-height: 1;
    text-transform: uppercase;
    box-sizing: border-box;
    transition:
        background-color var(--transition-fast),
        border-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}


.painting-finish-button i {
    flex: 0 0 36px;
    width: 36px;
    height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #fff;
    color: var(--color-orange);
    font-size: 12px;
    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}


/* =========================================================
   PAINTING FINISH BUTTON - HOVER
========================================================= */

.painting-finish-button:hover {
    background: #fff;
    border-color: var(--color-orange);
    color: var(--color-orange);
    transform: translateY(-2px);
    box-shadow: 0 10px 25px rgba(255, 90, 54, 0.18);
}

.painting-finish-button:hover i {
    background: var(--color-orange);
    color: #fff;
    transform: translateX(4px);
}


/* =========================================================
   RTL HOVER
========================================================= */

html[dir="rtl"] .painting-finish-button:hover i {
    transform: translateX(-4px);
}


/* =========================================================
   FOCUS
========================================================= */

.painting-finish-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.35);
    outline-offset: 4px;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .painting-finishes-section {
    background: var(--color-bg);
}


html.dark-mode .painting-finish-card {
    background: var(--color-surface);
    border-color: var(--color-border);
}


html.dark-mode .painting-finish-card:hover {
    border-color: rgba(255, 90, 54, 0.40);
    box-shadow: 0 18px 40px rgba(0, 0, 0, 0.28);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .painting-finish-button {
    padding-left: 6px;
    padding-right: 22px;
}


html[dir="rtl"] .painting-finish-button:hover i {
    transform: translateX(-4px);
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .painting-finish-card,
    .painting-finish-image,
    .painting-finish-button,
    .painting-finish-button i {
        transition: none;
    }

    .painting-finish-card:hover {
        transform: none;
    }

    .painting-finish-card:hover .painting-finish-image {
        transform: none;
    }

}


/* =========================================================
   PAINTING PAGE
   SECTION 07: RECENT PAINTING PROJECTS
   PART 2 - MAIN CSS
========================================================= */


/* =========================================================
   SECTION
========================================================= */

.painting-projects-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
    box-sizing: border-box;
}


/* =========================================================
   CONTAINER
========================================================= */

.painting-projects-container {
    width: 100%;
    max-width: 1700px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   HEADER
========================================================= */

.painting-projects-header {
    width: 100%;
    max-width: 900px;
    margin: 0 auto 60px;
    text-align: center;
    box-sizing: border-box;
}


/* =========================================================
   EYEBROW
========================================================= */

.painting-projects-eyebrow {
    display: block;
    margin-bottom: 15px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: 2.5px;
}


/* =========================================================
   HEADING
========================================================= */

.painting-projects-heading {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: -1.2px;
}


.painting-projects-heading span {
    color: var(--color-orange);
}


/* =========================================================
   SLIDER
========================================================= */

.painting-projects-slider {
    position: relative;
    width: 100%;
    box-sizing: border-box;
}


/* =========================================================
   VIEWPORT
========================================================= */

.painting-projects-slider {
    overflow: hidden;
}


/* =========================================================
   TRACK
========================================================= */

.painting-projects-track {
    width: 100%;
    display: flex;
    align-items: flex-start;
    gap: 35px;
    box-sizing: border-box;
    transition: transform 0.6s ease;
    will-change: transform;
}


/* =========================================================
   PROJECT CARD
========================================================= */

.painting-project-card {
    flex: 0 0 calc((100% - 70px) / 3);
    width: calc((100% - 70px) / 3);
    min-width: 0;
    box-sizing: border-box;
}


/* =========================================================
   PROJECT LINK
========================================================= */

.painting-project-link {
    display: block;
    width: 100%;
    color: inherit;
    text-decoration: none;
    box-sizing: border-box;
}


/* =========================================================
   IMAGE WRAPPER
========================================================= */

.painting-project-image-wrapper {
    position: relative;
    width: 100%;
    height: 420px;
    overflow: hidden;
    background: var(--color-surface);
    box-sizing: border-box;
}


/* =========================================================
   IMAGE
========================================================= */

.painting-project-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition: transform 0.7s ease;
}


.painting-project-link:hover .painting-project-image {
    transform: scale(1.06);
}


/* =========================================================
   IMAGE OVERLAY
========================================================= */

.painting-project-image-overlay {
    position: absolute;
    inset: 0;
    background: rgba(255, 90, 54, 0.0);
    transition: background-color 0.4s ease;
    pointer-events: none;
}


.painting-project-link:hover .painting-project-image-overlay {
    background: rgba(255, 90, 54, 0.18);
}


/* =========================================================
   VIEW BUTTON
========================================================= */

.painting-project-view {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 62px;
    height: 62px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #fff;
    color: var(--color-orange);
    font-size: 17px;
    transform: translate(-50%, -50%) scale(0.7);
    opacity: 0;
    visibility: hidden;
    transition:
        transform 0.35s ease,
        opacity 0.35s ease,
        visibility 0.35s ease;
    box-sizing: border-box;
}


.painting-project-link:hover .painting-project-view {
    transform: translate(-50%, -50%) scale(1);
    opacity: 1;
    visibility: visible;
}


/* =========================================================
   PROJECT CONTENT
========================================================= */

.painting-project-content {
    width: 100%;
    padding: 25px 0 0;
    box-sizing: border-box;
}


/* =========================================================
   META
========================================================= */

.painting-project-meta {
    width: 100%;
    margin-bottom: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    box-sizing: border-box;
}


.painting-project-line {
    flex: 0 0 44px;
    width: 44px;
    height: 2px;
    background: var(--color-orange);
}


.painting-project-category {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: 1px;
}


.painting-project-dot {
    color: var(--color-text-muted);
    font-size: 14px;
}


.painting-project-location {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 500;
    line-height: 1.3;
    letter-spacing: 0.5px;
}


/* =========================================================
   PROJECT TITLE
========================================================= */

.painting-project-title {
    max-width: 500px;
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 27px;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: -0.5px;
    transition: color var(--transition-fast);
}


.painting-project-link:hover .painting-project-title {
    color: var(--color-orange);
}


/* =========================================================
   SLIDER ARROWS
========================================================= */

.painting-projects-arrow {
    position: absolute;
    top: 210px;
    z-index: 5;
    width: 58px;
    height: 58px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 0;
    border-radius: 50%;
    background: var(--color-orange);
    color: #fff;
    font-family: inherit;
    font-size: 15px;
    cursor: pointer;
    box-sizing: border-box;
