    top: 25px;
    right: -25px;
    z-index: 0;

    width: 90px;
    height: 90px;

    border: 12px solid rgba(255, 90, 54, 0.14);
    border-radius: 12px;

    box-sizing: border-box;
    pointer-events: none;
}


/* =========================================================
   CONTENT
========================================================= */

.exterior-project-intro-content {
    width: 100%;
    max-width: 650px;
    min-width: 0;

    box-sizing: border-box;
}

.exterior-project-intro-eyebrow {
    position: relative;

    display: inline-flex;
    align-items: center;

    gap: 12px;
    margin-bottom: 15px;

    color: var(--color-orange);
    font-family: var(--font-family);

    font-size: 12px;
    font-weight: 700;
    line-height: 1.3;

    letter-spacing: 2.5px;
    text-transform: uppercase;
}

.exterior-project-intro-eyebrow::before {
    content: "";

    width: 34px;
    height: 2px;

    display: block;

    background: var(--color-orange);
}


.exterior-project-intro-title {
    margin: 0;

    color: var(--color-text);
    font-family: var(--font-family);

    font-size: 46px;
    font-weight: 800;
    line-height: 1.15;

    letter-spacing: -1.1px;
}

.exterior-project-intro-title span {
    color: var(--color-orange);
}


.exterior-project-intro-description {
    margin: 18px 0 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);

    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   FEATURES
========================================================= */

.exterior-project-intro-features {
    width: 100%;

    display: flex;
    flex-direction: column;

    gap: 16px;

    margin-top: 28px;
}

.exterior-project-intro-feature {
    width: 100%;

    display: grid;
    grid-template-columns: 48px minmax(0, 1fr);
    gap: 16px;
    align-items: center;

    box-sizing: border-box;
}

.exterior-project-intro-feature-icon {
    width: 48px;
    height: 48px;
    flex: 0 0 48px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 17px;

    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.exterior-project-intro-feature:hover
.exterior-project-intro-feature-icon {
    background: var(--color-orange);
    color: #fff;
    transform: scale(1.05);
}

.exterior-project-intro-feature-content {
    min-width: 0;
}

.exterior-project-intro-feature-content h3 {
    margin: 0 0 4px;

    color: var(--color-text);
    font-family: var(--font-family);

    font-size: 17px;
    font-weight: 700;
    line-height: 1.35;
}

.exterior-project-intro-feature-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);

    font-size: 12px;
    font-weight: 400;
    line-height: 1.6;
}


/* =========================================================
   BUTTON
========================================================= */

.exterior-project-intro-action {
    display: flex;
    align-items: center;

    margin-top: 30px;
}

.exterior-project-intro-button {
    min-width: 175px;
    min-height: 54px;

    display: inline-flex;
    align-items: center;
    justify-content: space-between;

    gap: 14px;

    padding: 6px 7px 6px 24px;

    background: var(--color-orange);
    border: 2px solid var(--color-orange);
    border-radius: 999px;

    color: #fff;
    font-family: var(--font-family);

    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;

    text-decoration: none;

    box-sizing: border-box;

    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast);
}

.exterior-project-intro-button i {
    width: 40px;
    height: 40px;
    flex: 0 0 40px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #fff;
    color: var(--color-orange);

    font-size: 13px;

    opacity: 1;
    visibility: visible;

    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.exterior-project-intro-button:hover {
    background: #fff;
    border-color: #fff;
    color: var(--color-orange);

    transform: translateY(-2px);
}

.exterior-project-intro-button:hover i {
    background: var(--color-orange);
    color: #fff;
    transform: translateX(4px);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .exterior-project-intro-container {
    direction: rtl;
}

html[dir="rtl"] .exterior-project-intro-content {
    direction: rtl;
}

html[dir="rtl"] .exterior-project-intro-badge {
    left: auto;
    right: -35px;
}

html[dir="rtl"] .exterior-project-intro-decoration {
    right: auto;
    left: -25px;
}

html[dir="rtl"] .exterior-project-intro-button {
    padding: 6px 24px 6px 7px;
}

html[dir="rtl"] .exterior-project-intro-button:hover i {
    transform: translateX(-4px);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .exterior-project-intro-section {
    background: var(--color-bg);
}


/* =========================================================
   FOCUS
========================================================= */

.exterior-project-intro-button:focus-visible {
    outline: 3px solid var(--color-orange);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .exterior-project-intro-image-wrapper:hover
    .exterior-project-intro-image {
        transform: none;
    }

    .exterior-project-intro-feature:hover
    .exterior-project-intro-feature-icon {
        background: rgba(255, 90, 54, 0.10);
        color: var(--color-orange);
        transform: none;
    }

    .exterior-project-intro-button:hover {
        background: var(--color-orange);
        border-color: var(--color-orange);
        color: #fff;
        transform: none;
    }

    .exterior-project-intro-button:hover i {
        background: #fff;
        color: var(--color-orange);
        transform: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .exterior-project-intro-image,
    .exterior-project-intro-feature-icon,
    .exterior-project-intro-button,
    .exterior-project-intro-button i {
        transition: none !important;
    }
}


/* =========================================================
   EXTERIOR PROJECT HIGHLIGHTS
   PART 2 - MAIN CSS
========================================================= */

.exterior-project-highlights-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-surface);
    overflow: hidden;
}

.exterior-project-highlights-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}

/* =========================
   HEADER
========================= */

.exterior-project-highlights-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 60px;
    text-align: center;
}

.exterior-project-highlights-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2.5px;
    line-height: 1.4;
}

.exterior-project-highlights-eyebrow::before,
.exterior-project-highlights-eyebrow::after {
    content: "";
    width: 34px;
    height: 2px;
    background: var(--color-orange);
    flex-shrink: 0;
}

.exterior-project-highlights-title {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1px;
}

.exterior-project-highlights-title span {
    color: var(--color-orange);
}

.exterior-project-highlights-intro {
    max-width: 720px;
    margin: 18px auto 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}

/* =========================
   HIGHLIGHTS GRID
========================= */

.exterior-project-highlights-grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}

/* =========================
   HIGHLIGHT CARD
========================= */

.exterior-project-highlight-card {
    position: relative;
    min-height: 245px;
    padding: 28px 25px 30px;
    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: 16px;
    box-sizing: border-box;
    overflow: hidden;
    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}

.exterior-project-highlight-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: var(--color-orange);
    transform: scaleX(0);
    transform-origin: left;
    transition: transform var(--transition-fast);
}

.exterior-project-highlight-card:hover {
    transform: translateY(-8px);
    border-color: rgba(255, 90, 54, 0.25);
    box-shadow: 0 14px 35px rgba(0, 0, 0, 0.08);
}

.exterior-project-highlight-card:hover::before {
    transform: scaleX(1);
}

/* =========================
   CARD TOP
========================= */

.exterior-project-highlight-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 24px;
}

.exterior-project-highlight-icon {
    width: 58px;
    height: 58px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 58px;
    background: rgba(255, 90, 54, 0.10);
    border: 1px solid rgba(255, 90, 54, 0.16);
    border-radius: 50%;
    color: var(--color-orange);
    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.exterior-project-highlight-icon i {
    font-size: 21px;
    line-height: 1;
}

.exterior-project-highlight-number {
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 1.5px;
}

.exterior-project-highlight-card:hover .exterior-project-highlight-icon {
    background: var(--color-orange);
    color: #ffffff;
    transform: scale(1.06);
}

/* =========================
   CARD CONTENT
========================= */

.exterior-project-highlight-content h3 {
    margin: 0 0 10px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 700;
    line-height: 1.3;
}

.exterior-project-highlight-content p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.75;
}

/* =========================
   BOTTOM MESSAGE
========================= */

.exterior-project-highlights-bottom {
    width: 100%;
    margin-top: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    text-align: center;
}

.exterior-project-highlights-bottom::before,
.exterior-project-highlights-bottom::after {
    content: "";
    width: 48px;
    height: 1px;
    background: var(--color-border);
    flex-shrink: 0;
}

.exterior-project-highlights-bottom i {
    color: var(--color-orange);
    font-size: 16px;
}

.exterior-project-highlights-bottom span {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 600;
    line-height: 1.5;
}

/* =========================
   RTL
========================= */

html[dir="rtl"] .exterior-project-highlight-card::before {
    left: auto;
    right: 0;
    transform-origin: right;
}

html[dir="rtl"] .exterior-project-highlights-eyebrow {
    direction: rtl;
}

/* =========================
   DARK MODE
========================= */

html.dark-mode .exterior-project-highlights-section,
body.dark-mode .exterior-project-highlights-section {
    background: var(--color-surface);
}

html.dark-mode .exterior-project-highlight-card,
body.dark-mode .exterior-project-highlight-card {
    background: var(--color-bg);
    border-color: var(--color-border);
}

html.dark-mode .exterior-project-highlight-card:hover,
body.dark-mode .exterior-project-highlight-card:hover {
    border-color: rgba(255, 90, 54, 0.35);
    box-shadow: 0 14px 35px rgba(0, 0, 0, 0.20);
}

/* =========================
   FOCUS ACCESSIBILITY
========================= */

.exterior-project-highlight-card:focus-within {
    border-color: var(--color-orange);
    box-shadow: 0 0 0 3px rgba(255, 90, 54, 0.12);
}

/* =========================
   TOUCH DEVICES
========================= */

@media (hover: none) {
    .exterior-project-highlight-card:hover {
        transform: none;
        box-shadow: none;
    }

    .exterior-project-highlight-card:hover .exterior-project-highlight-icon {
        background: rgba(255, 90, 54, 0.10);
        color: var(--color-orange);
        transform: none;
    }

    .exterior-project-highlight-card:hover::before {
        transform: scaleX(0);
    }
}

/* =========================
   REDUCED MOTION
========================= */

@media (prefers-reduced-motion: reduce) {
    .exterior-project-highlight-card,
    .exterior-project-highlight-icon,
    .exterior-project-highlight-card::before {
        transition: none;
    }
}



/* =========================================================
   EXTERIOR PAINTING PROJECT
   SECTION 04: EXTERIOR PAINTING SERVICES
   PART 2 - MAIN CSS
========================================================= */

.exterior-project-services-section {
    width: 100%;
    padding: 95px 0 85px;
    background: var(--color-bg);
    overflow: hidden;
    box-sizing: border-box;
}

.exterior-project-services-header {
    width: 100%;
    margin: 0 auto 70px;
    text-align: center;
}

.exterior-project-services-eyebrow {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    position: relative;
    margin-bottom: 8px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 18px;
    font-weight: 500;
    line-height: 1.3;
    letter-spacing: 0;
}

.exterior-project-services-eyebrow::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -5px;
    width: 100%;
    height: 1px;
    background: var(--color-orange);
}

.exterior-project-services-title {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 58px;
    font-weight: 800;
    line-height: 1.1;
    letter-spacing: -1.5px;
}


/* =========================================================
   SLIDER
========================================================= */

.exterior-project-services-slider {
    position: relative;
    width: 100%;
    padding: 0 18px 55px;
    box-sizing: border-box;
}

.exterior-project-services-track {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 36px;
    box-sizing: border-box;
}


/* =========================================================
   SERVICE CARD
========================================================= */

.exterior-project-service-card {
    position: relative;
    width: 100%;
    min-width: 0;
}

.exterior-project-service-link {
    display: block;
    width: 100%;
    color: inherit;
    text-decoration: none;
}

.exterior-project-service-image-wrapper {
    position: relative;
    width: 100%;
    height: 490px;
    overflow: hidden;
    background: var(--color-surface);
}

.exterior-project-service-image {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center;
    transition:
        transform 0.6s ease,
        filter 0.6s ease;
}

.exterior-project-service-overlay {
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
        linear-gradient(
            to bottom,
            rgba(0, 0, 0, 0.03) 20%,
            rgba(0, 0, 0, 0.08) 45%,
            rgba(0, 0, 0, 0.72) 100%
        );
    pointer-events: none;
}


/* =========================================================
   ICON
========================================================= */

.exterior-project-service-icon {
    position: absolute;
    top: 22px;
    left: 22px;
    z-index: 3;

    width: 108px;
    height: 108px;

    display: flex;
    align-items: center;
    justify-content: center;

    background: #4a3527;
    border: 1px solid rgba(255, 255, 255, 0.9);
    border-radius: 50%;

    color: #ffffff;

    transition:
        transform 0.35s ease,
        background 0.35s ease;
}

.exterior-project-service-icon i {
    font-size: 34px;
    line-height: 1;
}


/* =========================================================
   TITLE BOX
========================================================= */

.exterior-project-service-title-box {
    position: absolute;
    left: 0;
    bottom: 0;
    z-index: 3;

    width: calc(100% - 30px);
    min-height: 80px;

    padding: 18px 28px;

    display: flex;
    flex-direction: column;
    justify-content: center;

    background: var(--color-bg);
    box-sizing: border-box;

    transition:
        transform 0.35s ease,
        background 0.35s ease;
}

.exterior-project-service-category {
    display: block;
    margin-bottom: 5px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.5px;
    line-height: 1.3;
}

.exterior-project-service-title-box h3 {
    margin: 0;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 24px;
    font-weight: 700;
    line-height: 1.25;
}


/* =========================================================
   HOVER
========================================================= */

.exterior-project-service-card:hover
.exterior-project-service-image {
    transform: scale(1.06);
}

.exterior-project-service-card:hover
.exterior-project-service-icon {
    background: var(--color-orange);
    transform: scale(1.04);
}

.exterior-project-service-card:hover
.exterior-project-service-title-box {
    transform: translateY(-5px);
}


/* =========================================================
   NEXT BUTTON
========================================================= */

.exterior-project-services-next {
    position: absolute;
    right: 0;
    bottom: 80px;
    z-index: 5;

    width: 92px;
    height: 78px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 0;
    border-radius: 50px 0 0 50px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    cursor: pointer;

    transition:
        background var(--transition-fast),
        transform var(--transition-fast);
}

.exterior-project-services-next i {
    font-size: 21px;
}

.exterior-project-services-next:hover {
    background: var(--color-dark-orange);
    transform: translateX(-4px);
}

.exterior-project-services-next:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.3);
    outline-offset: 3px;
}


/* =========================================================
   PAGINATION
========================================================= */

.exterior-project-services-pagination {
    position: absolute;
    left: 50%;
    bottom: 0;

    transform: translateX(-50%);

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.exterior-project-services-dot {
    width: 30px;
    height: 30px;

    padding: 0;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid transparent;
    border-radius: 50%;

    background: transparent;
    cursor: pointer;

    position: relative;
}

.exterior-project-services-dot::before {
    content: "";

    width: 8px;
    height: 8px;

    border: 1px solid var(--color-orange);
    border-radius: 50%;

    background: transparent;

    transition:
        width var(--transition-fast),
        height var(--transition-fast),
        background var(--transition-fast);
}

.exterior-project-services-dot.active::before {
    width: 10px;
    height: 10px;
    background: var(--color-orange);
}

.exterior-project-services-dot:focus-visible {
    outline: 2px solid var(--color-orange);
    outline-offset: 2px;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .exterior-project-service-icon {
    left: auto;
    right: 22px;
}

html[dir="rtl"] .exterior-project-service-title-box {
    left: auto;
    right: 0;
}

html[dir="rtl"] .exterior-project-services-next {
    right: auto;
    left: 0;
    border-radius: 0 50px 50px 0;
}

html[dir="rtl"] .exterior-project-services-next:hover {
    transform: translateX(4px);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .exterior-project-services-section,
body.dark-mode .exterior-project-services-section {
    background: var(--color-bg);
}

html.dark-mode .exterior-project-service-title-box,
body.dark-mode .exterior-project-service-title-box {
    background: var(--color-surface);
}

html.dark-mode .exterior-project-service-icon,
body.dark-mode .exterior-project-service-icon {
    background: #3f3025;
}

html.dark-mode .exterior-project-service-card:hover
.exterior-project-service-icon,
body.dark-mode .exterior-project-service-card:hover
.exterior-project-service-icon {
    background: var(--color-orange);
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) {

    .exterior-project-service-card:hover
    .exterior-project-service-image {
        transform: none;
    }

    .exterior-project-service-card:hover
    .exterior-project-service-icon {
        background: #4a3527;
        transform: none;
    }

    .exterior-project-service-card:hover
    .exterior-project-service-title-box {
        transform: none;
    }

    .exterior-project-services-next:hover {
        transform: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .exterior-project-service-image,
    .exterior-project-service-icon,
    .exterior-project-service-title-box,
    .exterior-project-services-next,
    .exterior-project-services-dot::before {
        transition: none !important;
    }
}





/* =========================================================
   EXTERIOR PAINTING PROJECT
   SECTION 05: BEFORE & AFTER
   PART 2 - MAIN CSS
========================================================= */

.exterior-project-before-after-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-surface);
