========================================================= */

.consultation-colour-badge {
    position: absolute;
    left: -35px;
    bottom: 35px;
    z-index: 3;

    width: 145px;
    height: 145px;

    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    box-sizing: border-box;

    border: 8px solid #ffffff;
    border-radius: 50%;

    background: var(--color-orange);
    color: #ffffff;

    text-align: center;

    box-shadow:
        0 15px 35px rgba(0, 0, 0, 0.16);
}

.consultation-colour-badge-icon {
    width: 43px;
    height: 43px;

    margin-bottom: 8px;

    display: flex;
    align-items: center;
    justify-content: center;

    border: 1px solid rgba(255, 255, 255, 0.35);
    border-radius: 50%;

    background: rgba(255, 255, 255, 0.12);
    color: #ffffff;

    font-size: 17px;
}

.consultation-colour-badge-content {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.consultation-colour-badge-content strong {
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 800;
    letter-spacing: 1.4px;
    line-height: 1.2;
}

.consultation-colour-badge-content span {
    margin-top: 3px;

    font-family: var(--font-family);
    font-size: 8px;
    font-weight: 600;
    letter-spacing: 1.5px;
    line-height: 1.2;
}


/* =========================================================
   DECORATIVE DOTS
========================================================= */

.consultation-colour-decoration {
    position: absolute;
    right: -28px;
    top: 25px;
    z-index: 2;

    width: 90px;
    height: 90px;

    display: grid;
    grid-template-columns: repeat(3, 7px);
    grid-auto-rows: 7px;
    align-content: center;
    justify-content: center;
    gap: 9px;
}

.consultation-colour-decoration span {
    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.22);
}


/* =========================================================
   RIGHT CONTENT
========================================================= */

.consultation-colour-content {
    width: 100%;
    max-width: 680px;
}

.consultation-colour-eyebrow {
    position: relative;

    display: inline-flex;
    align-items: center;

    margin-bottom: 18px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2px;
    line-height: 1.3;
}

.consultation-colour-eyebrow::after {
    content: "";

    width: 70px;
    height: 2px;

    margin-left: 12px;

    background: var(--color-orange);
}


/* =========================================================
   TITLE
========================================================= */

.consultation-colour-title {
    max-width: 650px;

    margin: 0 0 24px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 46px;
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -1.1px;
}

.consultation-colour-title span {
    display: block;
    color: var(--color-orange);
}


/* =========================================================
   DESCRIPTION
========================================================= */

.consultation-colour-description {
    max-width: 650px;

    margin: 0 0 30px;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   FEATURES
========================================================= */

.consultation-colour-features {
    display: flex;
    flex-direction: column;
    gap: 19px;

    margin-bottom: 28px;
}

.consultation-colour-feature {
    display: flex;
    align-items: center;
    gap: 15px;
}

.consultation-colour-feature-icon {
    width: 48px;
    height: 48px;

    flex: 0 0 48px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 17px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-colour-feature:hover
.consultation-colour-feature-icon {
    background: var(--color-orange);
    color: #ffffff;
    transform: translateY(-3px);
}

.consultation-colour-feature-content {
    min-width: 0;
}

.consultation-colour-feature-content h3 {
    margin: 0 0 4px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 700;
    line-height: 1.35;
}

.consultation-colour-feature-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    line-height: 1.55;
}


/* =========================================================
   PALETTE
========================================================= */

.consultation-colour-palette {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;

    padding: 18px 0;

    border-top: 1px solid var(--color-border);
    border-bottom: 1px solid var(--color-border);

    margin-bottom: 25px;
}

.consultation-colour-palette-header {
    display: flex;
    align-items: center;
    gap: 9px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.4px;
}

.consultation-colour-palette-header i {
    color: var(--color-orange);
    font-size: 10px;
}

.consultation-colour-swatches {
    display: flex;
    align-items: center;
    gap: 8px;
}

.consultation-colour-swatch {
    width: 30px;
    height: 30px;

    display: block;

    border-radius: 50%;

    box-sizing: border-box;

    box-shadow:
        inset 0 0 0 1px rgba(0, 0, 0, 0.08),
        0 3px 8px rgba(0, 0, 0, 0.08);
}

.consultation-colour-swatch-orange {
    background: var(--color-orange);
}

.consultation-colour-swatch-dark-orange {
    background: var(--color-dark-orange);
}

.consultation-colour-swatch-light-orange {
    background: var(--color-light-orange);
}

.consultation-colour-swatch-white {
    background: #ffffff;
    border: 1px solid var(--color-border);
}


/* =========================================================
   BUTTON
========================================================= */

.consultation-colour-button {
    width: 205px;
    min-height: 54px;

    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;

    padding: 0 8px 0 21px;

    box-sizing: border-box;

    border: 2px solid var(--color-orange);
    border-radius: 30px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;

    text-decoration: none;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.consultation-colour-button:hover {
    background: var(--color-bg);
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 12px 28px rgba(0, 0, 0, 0.10);
}

.consultation-colour-button-icon {
    width: 40px;
    height: 40px;

    flex: 0 0 40px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #ffffff;
    color: var(--color-orange);

    font-size: 13px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast);
}

.consultation-colour-button:hover
.consultation-colour-button-icon {
    background: var(--color-orange);
    color: #ffffff;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .consultation-colour-container {
    direction: rtl;
}

html[dir="rtl"] .consultation-colour-content {
    text-align: right;
}

html[dir="rtl"] .consultation-colour-eyebrow {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-colour-eyebrow::after {
    margin-left: 0;
    margin-right: 12px;
}

html[dir="rtl"] .consultation-colour-feature {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-colour-decoration {
    right: auto;
    left: -28px;
}

html[dir="rtl"] .consultation-colour-badge {
    left: auto;
    right: -35px;
}

html[dir="rtl"] .consultation-colour-palette {
    direction: rtl;
}

html[dir="rtl"] .consultation-colour-palette-header {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-colour-button {
    padding-left: 8px;
    padding-right: 21px;
}

html[dir="rtl"] .consultation-colour-button-icon {
    transform: rotate(180deg);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .consultation-colour-section {
    background: var(--color-surface);
}

html.dark-mode .consultation-colour-badge {
    border-color: var(--color-surface);
}

html.dark-mode .consultation-colour-swatch-white {
    background: var(--color-bg);
}

html.dark-mode .consultation-colour-button:hover {
    background: var(--color-bg);
}


/* =========================================================
   FOCUS
========================================================= */

.consultation-colour-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.35);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) {

    .consultation-colour-image-wrapper:hover
    .consultation-colour-image {
        transform: none;
    }

    .consultation-colour-feature:hover
    .consultation-colour-feature-icon {
        transform: none;
    }

    .consultation-colour-button:hover {
        transform: none;
        box-shadow: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .consultation-colour-image,
    .consultation-colour-feature-icon,
    .consultation-colour-button,
    .consultation-colour-button-icon {
        transition: none !important;
    }
}



/* =========================================================
   CONSULTATION PAGE
   SECTION 06: PRICING GUIDE
   PART 2 - MAIN CSS
========================================================= */

.consultation-pricing-section {
    position: relative;
    width: 100%;
    padding: 100px 0;
    overflow: hidden;
    background: var(--color-bg);
}


/* =========================================================
   CONTAINER
========================================================= */

.consultation-pricing-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.consultation-pricing-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 60px;

    text-align: center;
}

.consultation-pricing-eyebrow {
    position: relative;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 16px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2.5px;
    line-height: 1.3;
}

.consultation-pricing-eyebrow::before,
.consultation-pricing-eyebrow::after {
    content: "";

    width: 38px;
    height: 2px;

    background: var(--color-orange);
}

.consultation-pricing-eyebrow::before {
    margin-right: 12px;
}

.consultation-pricing-eyebrow::after {
    margin-left: 12px;
}

.consultation-pricing-title {
    margin: 0 0 18px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -1px;
}

.consultation-pricing-title span {
    color: var(--color-orange);
}

.consultation-pricing-intro {
    max-width: 760px;
    margin: 0 auto;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}

.consultation-pricing-divider {
    width: 280px;
    height: 42px;

    margin: 25px auto 0;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
}

.consultation-pricing-divider span {
    width: 90px;
    height: 1px;

    background: var(--color-border);
}

.consultation-pricing-divider i {
    width: 42px;
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 14px;
}


/* =========================================================
   PRICING GRID
========================================================= */

.consultation-pricing-grid {
    width: 100%;

    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 24px;
}


/* =========================================================
   PRICING CARD
========================================================= */

.consultation-pricing-card {
    position: relative;

    min-height: 430px;
    padding: 28px 25px 25px;

    display: flex;
    flex-direction: column;

    box-sizing: border-box;

    border: 1px solid var(--color-border);
    border-radius: 16px;

    background: var(--color-surface);

    overflow: hidden;

    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}

.consultation-pricing-card:hover {
    transform: translateY(-8px);

    border-color: rgba(255, 90, 54, 0.25);

    box-shadow:
        0 18px 38px rgba(0, 0, 0, 0.10);
}


/* =========================================================
   CARD TOP
========================================================= */

.consultation-pricing-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;

    margin-bottom: 24px;
}

.consultation-pricing-number {
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 1.5px;
}

.consultation-pricing-icon {
    width: 58px;
    height: 58px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 19px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-pricing-card:hover
.consultation-pricing-icon {
    background: var(--color-orange);
    color: #ffffff;
    transform: scale(1.06);
}


/* =========================================================
   CARD CONTENT
========================================================= */

.consultation-pricing-card-content {
    flex: 1;
}

.consultation-pricing-category {
    display: block;

    margin-bottom: 8px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 1.5px;
    line-height: 1.3;
}

.consultation-pricing-card-content h3 {
    margin: 0 0 12px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 800;
    line-height: 1.3;
}

.consultation-pricing-card-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.65;
}


/* =========================================================
   PRICE
========================================================= */

.consultation-pricing-price {
    display: flex;
    align-items: baseline;
    flex-wrap: wrap;

    padding: 20px 0 18px;

    margin-top: 25px;

    border-top: 1px solid var(--color-border);
}

.consultation-pricing-price-label {
    width: 100%;

    margin-bottom: 5px;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 1.5px;
    line-height: 1.3;
}

.consultation-pricing-price strong {
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 32px;
    font-weight: 800;
    line-height: 1;
}

.consultation-pricing-unit {
    margin-left: 6px;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 500;
}


/* =========================================================
   CARD LINK
========================================================= */

.consultation-pricing-card-link {
    width: 100%;
    min-height: 45px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 0 16px;

    box-sizing: border-box;

    border: 1px solid var(--color-orange);
    border-radius: 10px;

    background: transparent;
    color: var(--color-orange);

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 700;

    text-decoration: none;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-pricing-card-link i {
    font-size: 11px;

    transition: transform var(--transition-fast);
}

.consultation-pricing-card-link:hover {
    background: var(--color-orange);
    color: #ffffff;

    transform: translateY(-2px);
}

.consultation-pricing-card-link:hover i {
    transform: translateX(4px);
}


/* =========================================================
   PRICING NOTE
========================================================= */

.consultation-pricing-note {
    width: 100%;
    max-width: 1050px;

    margin: 42px auto 0;
    padding: 18px 22px;

    display: flex;
    align-items: center;
    gap: 15px;

    box-sizing: border-box;

    border: 1px solid var(--color-border);
    border-radius: 12px;

    background: var(--color-surface);
}

.consultation-pricing-note-icon {
    width: 42px;
    height: 42px;

    flex: 0 0 42px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 15px;
}

.consultation-pricing-note-content {
    min-width: 0;
}

.consultation-pricing-note-content strong {
    display: block;

    margin-bottom: 4px;

    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
}

.consultation-pricing-note-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 400;
    line-height: 1.6;
}


/* =========================================================
   MAIN CTA
========================================================= */

.consultation-pricing-action {
    margin-top: 35px;

    display: flex;
    justify-content: center;
}

.consultation-pricing-button {
    width: 195px;
    min-height: 52px;

    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;

    padding: 0 8px 0 20px;

    box-sizing: border-box;

    border: 2px solid var(--color-orange);
    border-radius: 28px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;

    text-decoration: none;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.consultation-pricing-button:hover {
    background: var(--color-bg);
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 12px 28px rgba(0, 0, 0, 0.10);
}

.consultation-pricing-button-icon {
    width: 38px;
    height: 38px;

    flex: 0 0 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #ffffff;
    color: var(--color-orange);

    font-size: 12px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast);
}

.consultation-pricing-button:hover
.consultation-pricing-button-icon {
    background: var(--color-orange);
    color: #ffffff;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .consultation-pricing-container {
    direction: rtl;
}

html[dir="rtl"] .consultation-pricing-header {
    text-align: center;
}

html[dir="rtl"] .consultation-pricing-eyebrow {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-pricing-eyebrow::before {
    margin-right: 0;
    margin-left: 12px;
}

html[dir="rtl"] .consultation-pricing-eyebrow::after {
    margin-left: 0;
    margin-right: 12px;
}

html[dir="rtl"] .consultation-pricing-card {
    text-align: right;
}

html[dir="rtl"] .consultation-pricing-card-top {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-pricing-price {
    direction: rtl;
}

html[dir="rtl"] .consultation-pricing-unit {
    margin-left: 0;
    margin-right: 6px;
}

html[dir="rtl"] .consultation-pricing-card-link {
    direction: rtl;
}

html[dir="rtl"] .consultation-pricing-card-link:hover i {
    transform: translateX(-4px);
}

html[dir="rtl"] .consultation-pricing-note {
    flex-direction: row-reverse;
    text-align: right;
}

html[dir="rtl"] .consultation-pricing-button {
    padding-left: 8px;
    padding-right: 20px;
}

html[dir="rtl"] .consultation-pricing-button-icon {
    transform: rotate(180deg);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .consultation-pricing-card {
    background: var(--color-surface);
}

html.dark-mode .consultation-pricing-note {
    background: var(--color-surface);
}

html.dark-mode .consultation-pricing-button:hover {
    background: var(--color-bg);
}


/* =========================================================
   FOCUS
========================================================= */

.consultation-pricing-card-link:focus-visible,
.consultation-pricing-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.30);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) {

    .consultation-pricing-card:hover {
        transform: none;
        box-shadow: none;
    }

    .consultation-pricing-card:hover
    .consultation-pricing-icon {
        transform: none;
        background: rgba(255, 90, 54, 0.10);
        color: var(--color-orange);
    }

    .consultation-pricing-card-link:hover {
