    pointer-events: none;
}

.consultation-booking-textarea-wrapper > i:first-child {
    top: 17px;
    transform: none;
}


/* =========================================================
   INPUTS / SELECT
========================================================= */

.consultation-booking-input-wrapper input,
.consultation-booking-input-wrapper select,
.consultation-booking-textarea-wrapper textarea {
    width: 100%;

    box-sizing: border-box;

    border: 1px solid var(--color-border);
    border-radius: 9px;

    background: var(--color-bg);
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;

    outline: none;

    transition:
        border-color var(--transition-fast),
        box-shadow var(--transition-fast),
        background-color var(--transition-fast);
}

.consultation-booking-input-wrapper input,
.consultation-booking-input-wrapper select {
    height: 48px;

    padding: 0 42px 0 40px;
}

.consultation-booking-textarea-wrapper textarea {
    min-height: 105px;

    padding: 14px 15px 14px 40px;

    resize: vertical;

    line-height: 1.55;
}

.consultation-booking-input-wrapper input::placeholder,
.consultation-booking-textarea-wrapper textarea::placeholder {
    color: var(--color-text-muted);
    opacity: 0.75;
}

.consultation-booking-input-wrapper input:focus,
.consultation-booking-input-wrapper select:focus,
.consultation-booking-textarea-wrapper textarea:focus {
    border-color: var(--color-orange);

    box-shadow:
        0 0 0 3px rgba(255, 90, 54, 0.10);
}

.consultation-booking-input-wrapper select {
    appearance: none;
    -webkit-appearance: none;

    cursor: pointer;
}

.consultation-booking-select-arrow {
    position: absolute;

    top: 50%;
    right: 15px;

    color: var(--color-text-muted);

    font-size: 9px;

    transform: translateY(-50%);

    pointer-events: none;
}


/* =========================================================
   FORM ROW
========================================================= */

.consultation-booking-form-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 15px;
}


/* =========================================================
   CONSENT
========================================================= */

.consultation-booking-consent {
    margin: 3px 0 18px;
}

.consultation-booking-checkbox {
    display: flex;
    align-items: flex-start;
    gap: 9px;

    cursor: pointer;
}

.consultation-booking-checkbox input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.consultation-booking-checkbox-mark {
    width: 16px;
    height: 16px;

    flex: 0 0 16px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-top: 1px;

    box-sizing: border-box;

    border: 1px solid var(--color-border);
    border-radius: 4px;

    background: var(--color-bg);
    color: #ffffff;

    font-size: 8px;

    transition:
        background-color var(--transition-fast),
        border-color var(--transition-fast);
}

.consultation-booking-checkbox input:checked
+ .consultation-booking-checkbox-mark {
    border-color: var(--color-orange);
    background: var(--color-orange);
}

.consultation-booking-checkbox-text {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 9px;
    line-height: 1.45;
}


/* =========================================================
   SUBMIT BUTTON
========================================================= */

.consultation-booking-submit {
    width: 100%;
    min-height: 54px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 0 8px 0 22px;

    box-sizing: border-box;

    border: 2px solid var(--color-orange);
    border-radius: 28px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);

    cursor: pointer;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.consultation-booking-submit:hover {
    background: var(--color-bg);
    color: var(--color-orange);

    transform: translateY(-3px);

    box-shadow:
        0 12px 28px rgba(0, 0, 0, 0.10);
}

.consultation-booking-submit-icon {
    width: 40px;
    height: 40px;

    flex: 0 0 40px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #ffffff;
    color: var(--color-orange);

    font-size: 12px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast);
}

.consultation-booking-submit:hover
.consultation-booking-submit-icon {
    background: var(--color-orange);
    color: #ffffff;
}


/* =========================================================
   FORM NOTE
========================================================= */

.consultation-booking-form-note {
    margin: 12px 0 0;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 8px;
    line-height: 1.4;

    text-align: center;
}

.consultation-booking-form-note i {
    color: var(--color-orange);
    font-size: 9px;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .consultation-booking-container {
    direction: rtl;
}

html[dir="rtl"] .consultation-booking-eyebrow {
    flex-direction: row-reverse;
}

html[dir="rtl"] .consultation-booking-eyebrow::before {
    margin-right: 0;
    margin-left: 12px;
}

html[dir="rtl"] .consultation-booking-eyebrow::after {
    margin-left: 0;
    margin-right: 12px;
}

html[dir="rtl"] .consultation-booking-image-badge {
    left: auto;
    right: 25px;
}

html[dir="rtl"] .consultation-booking-info-text {
    flex-direction: row-reverse;
    text-align: right;
}

html[dir="rtl"] .consultation-booking-form-card {
    text-align: right;
}

html[dir="rtl"] .consultation-booking-input-wrapper > i:first-child,
html[dir="rtl"] .consultation-booking-textarea-wrapper > i:first-child {
    left: auto;
    right: 15px;
}

html[dir="rtl"] .consultation-booking-input-wrapper input,
html[dir="rtl"] .consultation-booking-input-wrapper select {
    padding-left: 42px;
    padding-right: 40px;
}

html[dir="rtl"] .consultation-booking-textarea-wrapper textarea {
    padding-left: 15px;
    padding-right: 40px;
}

html[dir="rtl"] .consultation-booking-select-arrow {
    right: auto;
    left: 15px;
}

html[dir="rtl"] .consultation-booking-submit {
    padding-left: 8px;
    padding-right: 22px;
}

html[dir="rtl"] .consultation-booking-submit-icon {
    transform: rotate(180deg);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .consultation-booking-form-card {
    background: var(--color-surface);
}

html.dark-mode .consultation-booking-input-wrapper input,
html.dark-mode .consultation-booking-input-wrapper select,
html.dark-mode .consultation-booking-textarea-wrapper textarea {
    background: var(--color-bg);
}

html.dark-mode .consultation-booking-submit:hover {
    background: var(--color-bg);
}


/* =========================================================
   FOCUS
========================================================= */

.consultation-booking-submit:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.30);
    outline-offset: 4px;
}

.consultation-booking-checkbox input:focus-visible
+ .consultation-booking-checkbox-mark {
    outline: 3px solid rgba(255, 90, 54, 0.25);
    outline-offset: 2px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) {

    .consultation-booking-image-wrapper:hover
    .consultation-booking-image {
        transform: none;
    }

    .consultation-booking-highlight:hover {
        transform: none;
        box-shadow: none;
    }

    .consultation-booking-submit:hover {
        transform: none;
        box-shadow: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .consultation-booking-image,
    .consultation-booking-highlight,
    .consultation-booking-submit,
    .consultation-booking-submit-icon,
    .consultation-booking-input-wrapper input,
    .consultation-booking-input-wrapper select,
    .consultation-booking-textarea-wrapper textarea,
    .consultation-booking-checkbox-mark {
        transition: none !important;
    }
}


/* =========================================================
   PAINTCRAFT CONSULTATION PAGE
   SECTION 09: CONSULTATION FAQ
   PART 2 - MAIN CSS
========================================================= */

.consultation-faq-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-surface);
    overflow: hidden;
}

.consultation-faq-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.consultation-faq-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 60px;
    text-align: center;
}

.consultation-faq-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    margin-bottom: 15px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    line-height: 1.3;
    letter-spacing: 2.5px;
    text-transform: uppercase;
}

.consultation-faq-eyebrow::before,
.consultation-faq-eyebrow::after {
    content: "";
    width: 38px;
    height: 2px;
    background: var(--color-orange);
    flex: 0 0 auto;
}

.consultation-faq-title {
    margin: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -1.2px;
}

.consultation-faq-title span {
    color: var(--color-orange);
}

.consultation-faq-intro {
    max-width: 760px;
    margin: 18px auto 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}

.consultation-faq-divider {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    width: 100%;
    max-width: 280px;
    margin: 28px auto 0;
}

.consultation-faq-divider span {
    width: 100%;
    height: 1px;
    background: var(--color-border);
}

.consultation-faq-divider i {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
    font-size: 16px;
}


/* =========================================================
   FAQ LIST
========================================================= */

.consultation-faq-list {
    width: 100%;
    max-width: 1050px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 14px;
}


/* =========================================================
   FAQ ITEM
========================================================= */

.consultation-faq-item {
    width: 100%;
    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: 14px;
    overflow: hidden;
    box-sizing: border-box;
    transition:
        transform var(--transition-fast),
        border-color var(--transition-fast),
        box-shadow var(--transition-fast),
        background-color var(--transition-fast);
}

.consultation-faq-item:hover {
    border-color: rgba(255, 90, 54, 0.28);
    box-shadow: 0 10px 28px rgba(0, 0, 0, 0.07);
}

.consultation-faq-item.active {
    border-color: rgba(255, 90, 54, 0.35);
}


/* =========================================================
   FAQ QUESTION
========================================================= */

.consultation-faq-question {
    width: 100%;
    min-height: 82px;
    padding: 15px 22px 15px 18px;

    display: grid;
    grid-template-columns: 48px minmax(0, 1fr) 40px;
    align-items: center;
    gap: 18px;

    border: 0;
    background: transparent;
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 700;
    line-height: 1.4;

    text-align: left;
    cursor: pointer;
    box-sizing: border-box;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast);
}

.consultation-faq-question:hover {
    background: rgba(255, 90, 54, 0.035);
}

.consultation-faq-question:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.25);
    outline-offset: -3px;
}


/* =========================================================
   QUESTION NUMBER
========================================================= */

.consultation-faq-question-number {
    width: 48px;
    height: 48px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    border: 1px solid rgba(255, 90, 54, 0.16);

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.5px;

    opacity: 1;
    visibility: visible;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-faq-item.active .consultation-faq-question-number,
.consultation-faq-question:hover .consultation-faq-question-number {
    background: var(--color-orange);
    border-color: var(--color-orange);
    color: #ffffff;
    transform: scale(1.05);
}


/* =========================================================
   QUESTION TEXT
========================================================= */

.consultation-faq-question-text {
    display: block;
    min-width: 0;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 17px;
    font-weight: 700;
    line-height: 1.45;
    transition: color var(--transition-fast);
}

.consultation-faq-item.active .consultation-faq-question-text {
    color: var(--color-orange);
}


/* =========================================================
   PLUS / MINUS ICON
========================================================= */

.consultation-faq-question-icon {
    width: 40px;
    height: 40px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: rgba(255, 90, 54, 0.08);
    color: var(--color-orange);

    font-size: 14px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-faq-item.active .consultation-faq-question-icon {
    background: var(--color-orange);
    color: #ffffff;
    transform: rotate(45deg);
}


/* =========================================================
   FAQ ANSWER
========================================================= */

.consultation-faq-answer {
    display: grid;
    grid-template-rows: 1fr;
    opacity: 1;
}

.consultation-faq-answer[hidden] {
    display: none;
}

.consultation-faq-answer-inner {
    padding: 0 95px 25px 84px;
}

.consultation-faq-answer-inner p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   BOTTOM CTA
========================================================= */

.consultation-faq-bottom {
    width: 100%;
    max-width: 1050px;
    margin: 45px auto 0;
    padding: 22px 25px;

    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;

    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: 14px;

    box-sizing: border-box;
}

.consultation-faq-bottom-content {
    display: flex;
    align-items: center;
    gap: 15px;
    min-width: 0;
}

.consultation-faq-bottom-icon {
    width: 46px;
    height: 46px;
    flex: 0 0 46px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    font-size: 17px;
}

.consultation-faq-bottom-text {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.consultation-faq-bottom-text strong {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 800;
    line-height: 1.3;
}

.consultation-faq-bottom-text span {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    line-height: 1.5;
}


/* =========================================================
   BOTTOM CTA BUTTON
========================================================= */

.consultation-faq-button {
    min-width: 195px;
    height: 52px;
    padding: 0 8px 0 22px;

    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;

    border: 2px solid var(--color-orange);
    border-radius: 999px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;
    text-decoration: none;
    white-space: nowrap;

    box-sizing: border-box;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.consultation-faq-button:hover {
    background: #ffffff;
    color: var(--color-orange);
    transform: translateY(-2px);
    box-shadow: 0 10px 24px rgba(255, 90, 54, 0.18);
}

.consultation-faq-button-icon {
    width: 36px;
    height: 36px;
    flex: 0 0 36px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);

    font-size: 13px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-faq-button:hover .consultation-faq-button-icon {
    background: var(--color-orange);
    color: #ffffff;
    transform: translateX(3px);
}

.consultation-faq-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.30);
    outline-offset: 4px;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .consultation-faq-question {
    grid-template-columns: 40px minmax(0, 1fr) 48px;
    text-align: right;
}

html[dir="rtl"] .consultation-faq-question-number {
    grid-column: 3;
}

html[dir="rtl"] .consultation-faq-question-text {
    grid-column: 2;
}

html[dir="rtl"] .consultation-faq-question-icon {
    grid-column: 1;
}

html[dir="rtl"] .consultation-faq-answer-inner {
    padding: 0 84px 25px 95px;
}

html[dir="rtl"] .consultation-faq-button {
    padding: 0 22px 0 8px;
}

html[dir="rtl"] .consultation-faq-button:hover .consultation-faq-button-icon {
    transform: translateX(-3px);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .consultation-faq-section {
    background: var(--color-surface);
}

html.dark-mode .consultation-faq-item:hover {
    box-shadow: 0 10px 28px rgba(0, 0, 0, 0.20);
}

html.dark-mode .consultation-faq-question:hover {
    background: rgba(255, 90, 54, 0.06);
}

html.dark-mode .consultation-faq-button:hover {
    background: var(--color-surface);
    color: var(--color-orange);
}

html.dark-mode .consultation-faq-button-icon {
    background: var(--color-surface);
    color: var(--color-orange);
}

html.dark-mode .consultation-faq-button:hover .consultation-faq-button-icon {
    background: var(--color-orange);
    color: #ffffff;
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .consultation-faq-item:hover {
        border-color: var(--color-border);
        box-shadow: none;
    }

    .consultation-faq-question:hover {
        background: transparent;
    }

    .consultation-faq-button:hover {
        transform: none;
        box-shadow: none;
    }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .consultation-faq-item,
    .consultation-faq-question,
    .consultation-faq-question-number,
    .consultation-faq-question-icon,
    .consultation-faq-button,
    .consultation-faq-button-icon {
        transition: none !important;
    }

}

/* =========================================================
   PAINTCRAFT CONSULTATION PAGE
   SECTION 10: FINAL CTA
   PART 2 - MAIN CSS
   STYLE: PREMIUM CTA PANEL
========================================================= */

.consultation-final-cta-section {
    width: 100%;
    padding: 100px 0 40px;
    background: var(--color-surface);
    overflow: hidden;
}

.consultation-final-cta-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   MAIN CTA PANEL
========================================================= */

.consultation-final-cta-panel {
    position: relative;
    width: 100%;
    min-height: 560px;

    display: grid;
    grid-template-columns: 1fr 0.9fr;
    align-items: center;

    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: 24px;

    overflow: hidden;
    box-sizing: border-box;
}


/* =========================================================
   DECORATIONS
========================================================= */

.consultation-final-cta-decoration {
    position: absolute;
    z-index: 0;
    pointer-events: none;
}

.consultation-final-cta-decoration-one {
    width: 240px;
    height: 240px;

    left: -120px;
    bottom: -120px;

    border: 55px solid rgba(255, 90, 54, 0.07);
    border-radius: 50%;
}

.consultation-final-cta-decoration-two {
    width: 130px;
    height: 130px;

    left: 43%;
    top: -65px;

    border: 28px solid rgba(255, 90, 54, 0.06);
    border-radius: 50%;
}


/* =========================================================
   CONTENT
========================================================= */

.consultation-final-cta-content {
    position: relative;
    z-index: 2;

    width: 100%;
    max-width: 680px;
    padding: 75px 55px 75px 75px;

    box-sizing: border-box;
}

.consultation-final-cta-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 12px;

    margin-bottom: 17px;

    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.3;
