    align-items: center;
    justify-content: space-between;
    gap: 10px;

    border: 2px solid var(--color-orange);
    border-radius: 999px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;
    text-decoration: none;
    white-space: nowrap;

    box-sizing: border-box;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.consultation-final-cta-primary-button:hover {
    background: #ffffff;
    color: var(--color-orange);
    transform: translateY(-3px);
    box-shadow: 0 12px 28px rgba(255, 90, 54, 0.18);
}

.consultation-final-cta-primary-icon {
    width: 39px;
    height: 39px;
    flex: 0 0 39px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);

    font-size: 13px;

    transition:
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-final-cta-primary-button:hover
.consultation-final-cta-primary-icon {
    background: var(--color-orange);
    color: #ffffff;
    transform: translateX(3px);
}


/* SECONDARY BUTTON */

.consultation-final-cta-secondary-button {
    min-width: 155px;
    height: 55px;
    padding: 0 20px;

    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;

    border: 1px solid var(--color-border);
    border-radius: 999px;

    background: var(--color-surface);
    color: var(--color-text);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    line-height: 1;
    text-decoration: none;
    white-space: nowrap;

    box-sizing: border-box;

    transition:
        border-color var(--transition-fast),
        background-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.consultation-final-cta-secondary-button i {
    color: var(--color-orange);
    font-size: 14px;
}

.consultation-final-cta-secondary-button:hover {
    border-color: var(--color-orange);
    background: rgba(255, 90, 54, 0.06);
    color: var(--color-orange);
    transform: translateY(-3px);
}


/* =========================================================
   TRUST ITEMS
========================================================= */

.consultation-final-cta-trust {
    margin-top: 31px;

    display: flex;
    align-items: center;
    gap: 28px;
    flex-wrap: wrap;
}

.consultation-final-cta-trust-item {
    display: flex;
    align-items: center;
    gap: 9px;
}

.consultation-final-cta-trust-icon {
    width: 40px;
    height: 40px;
    flex: 0 0 40px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: rgba(255, 90, 54, 0.09);
    color: var(--color-orange);

    font-size: 14px;
}

.consultation-final-cta-trust-item div {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.consultation-final-cta-trust-item strong {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    line-height: 1.3;
}

.consultation-final-cta-trust-item div span {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 8px;
    font-weight: 400;
    line-height: 1.4;
}


/* =========================================================
   RIGHT VISUAL
========================================================= */

.consultation-final-cta-visual {
    position: relative;
    z-index: 2;

    width: 100%;
    height: 100%;
    min-height: 560px;

    padding: 22px;

    box-sizing: border-box;
}

.consultation-final-cta-image-wrapper {
    position: relative;

    width: 100%;
    height: 516px;

    overflow: hidden;
    border-radius: 19px;

    background: var(--color-surface);
}

.consultation-final-cta-image {
    width: 100%;
    height: 100%;

    display: block;
    object-fit: cover;

    transition: transform 0.6s ease;
}

.consultation-final-cta-image-wrapper:hover
.consultation-final-cta-image {
    transform: scale(1.04);
}

.consultation-final-cta-image-overlay {
    position: absolute;
    inset: 0;

    background:
        linear-gradient(
            180deg,
            rgba(0, 0, 0, 0.02) 35%,
            rgba(0, 0, 0, 0.28) 100%
        );

    pointer-events: none;
}


/* =========================================================
   FLOATING CARD
========================================================= */

.consultation-final-cta-floating-card {
    position: absolute;
    left: -5px;
    bottom: 58px;
    z-index: 5;

    width: 275px;
    min-height: 105px;

    padding: 17px;

    display: flex;
    align-items: center;
    gap: 13px;

    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 15px;

    box-shadow: 0 18px 38px rgba(0, 0, 0, 0.15);

    box-sizing: border-box;
}

.consultation-final-cta-floating-icon {
    width: 52px;
    height: 52px;
    flex: 0 0 52px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: var(--color-orange);
    color: #ffffff;

    font-size: 18px;
}

.consultation-final-cta-floating-content {
    min-width: 0;

    display: flex;
    flex-direction: column;
    gap: 3px;
}

.consultation-final-cta-floating-content > span {
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 7px;
    font-weight: 800;
    letter-spacing: 1.2px;
    line-height: 1.3;
}

.consultation-final-cta-floating-content strong {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 800;
    line-height: 1.25;
}

.consultation-final-cta-floating-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 8px;
    line-height: 1.4;
}


/* =========================================================
   BOTTOM STRIP
========================================================= */

.consultation-final-cta-bottom {
    width: 100%;
    margin-top: 38px;

    display: flex;
    align-items: center;
    justify-content: center;
    gap: 18px;
}

.consultation-final-cta-bottom-line {
    width: 100%;
    max-width: 260px;
    height: 1px;
    background: var(--color-border);
}

.consultation-final-cta-bottom-content {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 9px;

    white-space: nowrap;
}

.consultation-final-cta-bottom-icon {
    width: 30px;
    height: 30px;
    flex: 0 0 30px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: rgba(255, 90, 54, 0.09);
    color: var(--color-orange);

    font-size: 12px;
}

.consultation-final-cta-bottom-content p {
    margin: 0;

    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 10px;
    line-height: 1.5;
}

.consultation-final-cta-bottom-content strong {
    color: var(--color-text);
    font-weight: 800;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .consultation-final-cta-content {
    order: 2;
    padding: 75px 75px 75px 55px;
}

html[dir="rtl"] .consultation-final-cta-visual {
    order: 1;
}

html[dir="rtl"] .consultation-final-cta-eyebrow::before {
    order: 2;
}

html[dir="rtl"] .consultation-final-cta-floating-card {
    left: auto;
    right: -5px;
}

html[dir="rtl"] .consultation-final-cta-primary-button:hover
.consultation-final-cta-primary-icon {
    transform: translateX(-3px);
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .consultation-final-cta-panel {
    box-shadow: none;
}

html.dark-mode .consultation-final-cta-primary-button:hover {
    background: var(--color-surface);
}

html.dark-mode .consultation-final-cta-primary-icon {
    background: var(--color-surface);
}

html.dark-mode .consultation-final-cta-primary-button:hover
.consultation-final-cta-primary-icon {
    background: var(--color-orange);
    color: #ffffff;
}

html.dark-mode .consultation-final-cta-floating-card {
    box-shadow: 0 18px 38px rgba(0, 0, 0, 0.28);
}


/* =========================================================
   FOCUS
========================================================= */

.consultation-final-cta-primary-button:focus-visible,
.consultation-final-cta-secondary-button:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.30);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .consultation-final-cta-image-wrapper:hover
    .consultation-final-cta-image {
        transform: none;
    }

    .consultation-final-cta-primary-button:hover,
    .consultation-final-cta-secondary-button:hover {
        transform: none;
        box-shadow: none;
    }

}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .consultation-final-cta-image,
    .consultation-final-cta-primary-button,
    .consultation-final-cta-primary-icon,
    .consultation-final-cta-secondary-button {
        transition: none !important;
    }

}









/* =========================================================
   CONTACT PAGE
   SECTION 01: CONTACT HERO
   PART 2 - MAIN CSS
   CONSULTATION-STYLE HERO
========================================================= */

.contact-hero-section {
    position: relative;
    width: 100%;
    min-height: 680px;
    display: flex;
    align-items: center;
    overflow: hidden;
    background: var(--color-bg);
}


/* =========================================================
   BACKGROUND
========================================================= */

.contact-hero-background {
    position: absolute;
    inset: 0;
    z-index: 0;
}

.contact-hero-background-image {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center;
}

.contact-hero-overlay {
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
        linear-gradient(
            90deg,
            rgba(0, 0, 0, 0.78) 0%,
            rgba(0, 0, 0, 0.68) 42%,
            rgba(0, 0, 0, 0.38) 72%,
            rgba(0, 0, 0, 0.20) 100%
        );
}


/* =========================================================
   CONTAINER
========================================================= */

.contact-hero-container {
    position: relative;
    z-index: 2;
    width: 100%;
    max-width: 1700px;
    min-height: 680px;
    margin: 0 auto;
    padding: 100px 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
}


/* =========================================================
   CONTENT
========================================================= */

.contact-hero-content {
    width: 100%;
    max-width: 950px;
    margin: 0 auto;
    text-align: center;
}

.contact-hero-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin-bottom: 18px;
    color: #ffffff;
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 800;
    letter-spacing: 2.5px;
    line-height: 1.3;
}

.contact-hero-eyebrow::before,
.contact-hero-eyebrow::after {
    content: "";
    width: 38px;
    height: 2px;
    display: inline-block;
    background: var(--color-orange);
}


.contact-hero-title {
    margin: 0 auto 22px;
    color: #ffffff;
    font-family: var(--font-family);
    font-size: 58px;
    font-weight: 800;
    line-height: 1.12;
    letter-spacing: -1.2px;
}

.contact-hero-title span {
    display: inline;
    color: var(--color-orange);
}

.contact-hero-description {
    max-width: 700px;
    margin: 0 auto 34px;
    color: rgba(255, 255, 255, 0.88);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   CONTACT HIGHLIGHTS
========================================================= */

.contact-hero-highlights {
    width: 100%;
    max-width: 760px;
    margin: 0 auto 35px;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
}

.contact-hero-highlight {
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 15px;
    box-sizing: border-box;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(5px);
    text-align: left;
    transition:
        background var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast);
}

.contact-hero-highlight:hover {
    background: rgba(255, 255, 255, 0.13);
    border-color: rgba(255, 90, 54, 0.65);
    transform: translateY(-4px);
}

.contact-hero-highlight-icon {
    flex: 0 0 44px;
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: var(--color-orange);
    color: #ffffff;
}

.contact-hero-highlight-icon i {
    font-size: 15px;
}

.contact-hero-highlight-content {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.contact-hero-highlight-content strong {
    color: #ffffff;
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    line-height: 1.3;
}

.contact-hero-highlight-content span {
    overflow-wrap: anywhere;
    color: rgba(255, 255, 255, 0.72);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 400;
    line-height: 1.4;
}


/* =========================================================
   ACTIONS
========================================================= */

.contact-hero-actions {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    flex-wrap: wrap;
}

.contact-hero-primary-button,
.contact-hero-secondary-button {
    min-height: 58px;
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 0 18px;
    border-radius: 999px;
    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;
    text-decoration: none;
    cursor: pointer;
    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.contact-hero-primary-button {
    width: 210px;
    background: var(--color-orange);
    color: #ffffff;
    border: 2px solid var(--color-orange);
}

.contact-hero-primary-button:hover {
    background: var(--color-dark-orange);
    border-color: var(--color-dark-orange);
    color: #ffffff;
    transform: translateY(-3px);
    box-shadow: 0 12px 25px rgba(255, 90, 54, 0.28);
}

.contact-hero-secondary-button {
    width: 190px;
    background: rgba(255, 255, 255, 0.08);
    color: #ffffff;
    border: 2px solid rgba(255, 255, 255, 0.70);
}

.contact-hero-secondary-button:hover {
    background: #ffffff;
    border-color: #ffffff;
    color: var(--color-orange);
    transform: translateY(-3px);
}

.contact-hero-button-icon {
    flex: 0 0 40px;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);
}

.contact-hero-button-icon i {
    font-size: 13px;
}

.contact-hero-secondary-button .contact-hero-button-icon {
    background: rgba(255, 255, 255, 0.15);
    color: #ffffff;
}

.contact-hero-secondary-button:hover .contact-hero-button-icon {
    background: var(--color-orange);
    color: #ffffff;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .contact-hero-overlay {
    background:
        linear-gradient(
            270deg,
            rgba(0, 0, 0, 0.78) 0%,
            rgba(0, 0, 0, 0.68) 42%,
            rgba(0, 0, 0, 0.38) 72%,
            rgba(0, 0, 0, 0.20) 100%
        );
}

html[dir="rtl"] .contact-hero-container {
    direction: rtl;
}

html[dir="rtl"] .contact-hero-highlight {
    direction: rtl;
    text-align: right;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .contact-hero-overlay {
    background:
        linear-gradient(
            90deg,
            rgba(0, 0, 0, 0.84) 0%,
            rgba(0, 0, 0, 0.74) 45%,
            rgba(0, 0, 0, 0.48) 75%,
            rgba(0, 0, 0, 0.30) 100%
        );
}

html[dir="rtl"].dark-mode .contact-hero-overlay {
    background:
        linear-gradient(
            270deg,
            rgba(0, 0, 0, 0.84) 0%,
            rgba(0, 0, 0, 0.74) 45%,
            rgba(0, 0, 0, 0.48) 75%,
            rgba(0, 0, 0, 0.30) 100%
        );
}


/* =========================================================
   FOCUS
========================================================= */

.contact-hero-primary-button:focus-visible,
.contact-hero-secondary-button:focus-visible {
    outline: 3px solid rgba(255, 255, 255, 0.65);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) {

    .contact-hero-highlight:hover {
        transform: none;
        background: rgba(255, 255, 255, 0.08);
        border-color: rgba(255, 255, 255, 0.18);
    }

    .contact-hero-primary-button:hover,
    .contact-hero-secondary-button:hover {
        transform: none;
        box-shadow: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .contact-hero-highlight,
    .contact-hero-primary-button,
    .contact-hero-secondary-button {
        transition: none;
    }
}



/* =========================================================
   CONTACT PAGE
   SECTION 02: CONTACT INFORMATION
   PART 2 - MAIN CSS
   CONSISTENT TYPOGRAPHY
