    gap: 24px;
}


/* =========================================================
   CARD
========================================================= */

.contact-information-card {
    position: relative;
    min-width: 0;
    min-height: 300px;
    padding: 28px 25px 30px;
    box-sizing: border-box;
    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: 16px;
    overflow: hidden;
    transition:
        transform var(--transition-fast),
        box-shadow var(--transition-fast),
        border-color var(--transition-fast);
}

.contact-information-card::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: 3px;
    background: var(--color-orange);
    transform: scaleX(0);
    transform-origin: center;
    transition: transform var(--transition-fast);
}

.contact-information-card:hover {
    transform: translateY(-7px);
    border-color: rgba(255, 90, 54, 0.30);
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.09);
}

.contact-information-card:hover::after {
    transform: scaleX(1);
}


/* =========================================================
   CARD TOP
========================================================= */

.contact-information-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 25px;
}

.contact-information-icon {
    width: 58px;
    height: 58px;
    flex: 0 0 58px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.contact-information-icon i {
    font-size: 18px;
}

.contact-information-number {
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 1px;
}


/* =========================================================
   CARD CONTENT
========================================================= */

.contact-information-card-content h3 {
    margin: 0 0 10px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 800;
    line-height: 1.3;
}

.contact-information-card-content p {
    margin: 0 0 18px;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   CONTACT LINK
========================================================= */

.contact-information-link {
    display: inline-flex;
    align-items: center;
    gap: 9px;
    max-width: 100%;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    line-height: 1.4;
    text-decoration: none;
    overflow-wrap: anywhere;
    transition:
        color var(--transition-fast),
        gap var(--transition-fast);
}

.contact-information-link i {
    font-size: 10px;
}

.contact-information-link:hover {
    color: var(--color-dark-orange);
    gap: 13px;
}


/* =========================================================
   WORKING HOURS
========================================================= */

.contact-information-hours {
    display: flex;
    flex-direction: column;
    gap: 9px;
    margin-top: 2px;
}

.contact-information-hours div {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.contact-information-hours span {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 500;
    line-height: 1.4;
}

.contact-information-hours strong {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 700;
    line-height: 1.4;
}


/* =========================================================
   BOTTOM NOTE
========================================================= */

.contact-information-bottom {
    max-width: 1050px;
    min-height: 70px;
    margin: 45px auto 0;
    padding: 12px 25px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 13px;
    box-sizing: border-box;
    border: 1px solid var(--color-border);
    border-radius: 12px;
    background: var(--color-bg);
}

.contact-information-bottom-icon {
    width: 44px;
    height: 44px;
    flex: 0 0 44px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
}

.contact-information-bottom-icon i {
    font-size: 15px;
}

.contact-information-bottom p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 500;
    line-height: 1.5;
}

.contact-information-bottom strong {
    color: var(--color-orange);
    font-weight: 800;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .contact-information-container {
    direction: rtl;
}

html[dir="rtl"] .contact-information-card {
    text-align: right;
}

html[dir="rtl"] .contact-information-link {
    flex-direction: row-reverse;
}

html[dir="rtl"] .contact-information-bottom {
    direction: rtl;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .contact-information-card:hover {
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.25);
}

html.dark-mode .contact-information-bottom {
    background: var(--color-bg);
}


/* =========================================================
   FOCUS
========================================================= */

.contact-information-link:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.25);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) {

    .contact-information-card:hover {
        transform: none;
        box-shadow: none;
        border-color: var(--color-border);
    }

    .contact-information-card:hover::after {
        transform: scaleX(0);
    }

    .contact-information-link:hover {
        gap: 9px;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .contact-information-card,
    .contact-information-card::after,
    .contact-information-icon,
    .contact-information-link {
        transition: none;
    }
}




/* =========================================================
   CONTACT PAGE
   SECTION 03: SEND US A MESSAGE
   PART 2 - MAIN CSS
   REWRITTEN FOR CONSISTENCY
========================================================= */

.contact-message-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-bg);
    overflow: hidden;
}

.contact-message-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.contact-message-header {
    width: 100%;
    max-width: 850px;
    margin: 0 auto 60px;
    text-align: center;
}

.contact-message-eyebrow {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin-bottom: 15px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2.5px;
    line-height: 1.3;
}

.contact-message-eyebrow::before,
.contact-message-eyebrow::after {
    content: "";
    width: 38px;
    height: 2px;
    background: var(--color-orange);
    display: inline-block;
}

.contact-message-title {
    margin: 0 0 17px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -0.8px;
}

.contact-message-title span {
    color: var(--color-orange);
}

.contact-message-intro {
    max-width: 700px;
    margin: 0 auto;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}

.contact-message-divider {
    width: 280px;
    margin: 25px auto 0;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
}

.contact-message-divider span {
    flex: 1;
    height: 1px;
    background: var(--color-border);
}

.contact-message-divider i {
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
    font-size: 15px;
}


/* =========================================================
   MAIN CONTENT
========================================================= */

.contact-message-content {
    width: 100%;
    display: grid;
    grid-template-columns: 1.05fr 0.95fr;
    gap: 55px;
    align-items: start;
}


/* =========================================================
   FORM CARD
========================================================= */

.contact-message-form-wrapper {
    width: 100%;
    min-width: 0;
    padding: 35px 40px 38px;
    box-sizing: border-box;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 18px;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.06);
}


/* =========================================================
   FORM HEADING
========================================================= */

.contact-message-form-heading {
    margin-bottom: 25px;
}

.contact-message-form-eyebrow {
    display: block;
    margin-bottom: 7px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 2px;
    line-height: 1.3;
}

.contact-message-form-heading h3 {
    margin: 0 0 6px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 24px;
    font-weight: 800;
    line-height: 1.3;
}

.contact-message-form-heading p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   FORM ROW
========================================================= */

.contact-message-form {
    width: 100%;
}

.contact-message-form-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 18px;
}

.contact-message-form-group {
    min-width: 0;
    margin-bottom: 17px;
}

.contact-message-form-group label {
    display: block;
    margin-bottom: 7px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 700;
    line-height: 1.4;
}


/* =========================================================
   INPUTS
========================================================= */

.contact-message-input-wrapper,
.contact-message-textarea-wrapper {
    position: relative;
    width: 100%;
}

.contact-message-input-wrapper > i,
.contact-message-textarea-wrapper > i {
    position: absolute;
    left: 15px;
    z-index: 2;
    color: var(--color-orange);
    pointer-events: none;
}

.contact-message-input-wrapper > i {
    top: 50%;
    font-size: 13px;
    transform: translateY(-50%);
}

.contact-message-textarea-wrapper > i {
    top: 17px;
    font-size: 13px;
}


.contact-message-input-wrapper input,
.contact-message-input-wrapper select,
.contact-message-textarea-wrapper textarea {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid var(--color-border);
    border-radius: 9px;
    background: var(--color-bg);
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    outline: none;
    transition:
        border-color var(--transition-fast),
        box-shadow var(--transition-fast);
}

.contact-message-input-wrapper input,
.contact-message-input-wrapper select {
    height: 48px;
    padding: 0 15px 0 43px;
}

.contact-message-input-wrapper select {
    appearance: none;
    -webkit-appearance: none;
    padding-right: 42px;
    cursor: pointer;
}

.contact-message-select-icon {
    position: absolute !important;
    top: 50% !important;
    right: 15px;
    left: auto !important;
    z-index: 2;
    color: var(--color-text-muted) !important;
    font-size: 10px !important;
    transform: translateY(-50%) !important;
    pointer-events: none;
}

.contact-message-textarea-wrapper textarea {
    min-height: 125px;
    padding: 14px 15px 14px 43px;
    resize: vertical;
    line-height: 1.6;
}

.contact-message-input-wrapper input::placeholder,
.contact-message-textarea-wrapper textarea::placeholder {
    color: var(--color-text-muted);
    opacity: 0.7;
}

.contact-message-input-wrapper input:focus,
.contact-message-input-wrapper select:focus,
.contact-message-textarea-wrapper textarea:focus {
    border-color: var(--color-orange);
    box-shadow: 0 0 0 3px rgba(255, 90, 54, 0.08);
}


/* =========================================================
   CONSENT
========================================================= */

.contact-message-form-consent {
    margin: 2px 0 20px;
}

.contact-message-checkbox {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    cursor: pointer;
}

.contact-message-checkbox input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
}

.contact-message-checkmark {
    width: 20px;
    height: 20px;
    flex: 0 0 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    border: 1px solid var(--color-border);
    border-radius: 5px;
    background: var(--color-bg);
    color: #ffffff;
}

.contact-message-checkmark i {
    font-size: 10px;
    opacity: 0;
}

.contact-message-checkbox input:checked + .contact-message-checkmark {
    background: var(--color-orange);
    border-color: var(--color-orange);
}

.contact-message-checkbox input:checked + .contact-message-checkmark i {
    opacity: 1;
}

.contact-message-consent-text {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 9px;
    line-height: 1.5;
}


/* =========================================================
   SUBMIT BUTTON
========================================================= */

.contact-message-form-submit {
    display: flex;
    align-items: center;
}

.contact-message-submit-button {
    width: 205px;
    min-height: 55px;
    padding: 0 13px 0 22px;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    box-sizing: border-box;
    border: 2px solid var(--color-orange);
    border-radius: 999px;
    background: var(--color-orange);
    color: #ffffff;
    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;
    cursor: pointer;
    transition:
        background var(--transition-fast),
        border-color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.contact-message-submit-icon {
    width: 39px;
    height: 39px;
    flex: 0 0 39px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);
}

.contact-message-submit-icon i {
    font-size: 13px;
}


/* =========================================================
   FORM NOTE
========================================================= */

.contact-message-form-note {
    margin: 13px 0 0;
    display: flex;
    align-items: center;
    gap: 7px;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 8px;
    line-height: 1.5;
}

.contact-message-form-note i {
    color: var(--color-orange);
    font-size: 10px;
}


/* =========================================================
   RIGHT SIDE
========================================================= */

.contact-message-visual {
    position: relative;
    width: 100%;
    min-width: 0;
    padding-bottom: 0;
}


/* =========================================================
   IMAGE
========================================================= */

.contact-message-image-wrapper {
    position: relative;
    width: 100%;
    height: 350px;
    overflow: hidden;
    border-radius: 18px;
    background: var(--color-surface);
}

.contact-message-image {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center;
    transition: transform 0.6s ease;
}

.contact-message-image-overlay {
    position: absolute;
    inset: 0;
    background:
        linear-gradient(
            180deg,
            rgba(0, 0, 0, 0.02) 30%,
            rgba(0, 0, 0, 0.35) 100%
        );
    pointer-events: none;
}

.contact-message-image-wrapper:hover .contact-message-image {
    transform: scale(1.04);
}


/* =========================================================
   FLOATING SUPPORT CARD
========================================================= */

.contact-message-floating-card {
    position: absolute;
    left: 20px;
    bottom: -42px;
    z-index: 5;
    width: 300px;
    min-height: 105px;
    padding: 17px 20px;
    display: flex;
    align-items: center;
    gap: 14px;
    box-sizing: border-box;
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: 15px;
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.14);
}

.contact-message-floating-icon {
    width: 48px;
    height: 48px;
    flex: 0 0 48px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: var(--color-orange);
    color: #ffffff;
}

.contact-message-floating-icon i {
    font-size: 17px;
}

.contact-message-floating-content {
    min-width: 0;
}

.contact-message-floating-content span {
    display: block;
    margin-bottom: 5px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 8px;
    font-weight: 800;
    letter-spacing: 1.4px;
}

.contact-message-floating-content strong {
    display: block;
    margin-bottom: 3px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 800;
    line-height: 1.3;
}

.contact-message-floating-content p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 9px;
    line-height: 1.4;
}


/* =========================================================
   SUPPORT CONTENT
========================================================= */

.contact-message-support {
    margin-top: 75px;
    padding: 0 5px;
}

.contact-message-support-eyebrow {
    display: block;
    margin-bottom: 9px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 800;
    letter-spacing: 2px;
    line-height: 1.3;
}

.contact-message-support h3 {
    margin: 0 0 11px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 27px;
    font-weight: 800;
    line-height: 1.25;
}

.contact-message-support h3 span {
    color: var(--color-orange);
}

.contact-message-support > p {
    max-width: 650px;
    margin: 0 0 25px;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   SUPPORT LIST
========================================================= */

.contact-message-support-list {
    display: grid;
    grid-template-columns: 1fr;
    gap: 13px;
}

.contact-message-support-item {
    display: flex;
    align-items: center;
    gap: 13px;
}

.contact-message-support-icon {
    width: 46px;
    height: 46px;
    flex: 0 0 46px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);
}

.contact-message-support-icon i {
    font-size: 14px;
}

.contact-message-support-item div {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.contact-message-support-item strong {
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 800;
    line-height: 1.3;
}

.contact-message-support-item div span {
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 400;
    line-height: 1.4;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .contact-message-container {
    direction: rtl;
}

html[dir="rtl"] .contact-message-form-group,
html[dir="rtl"] .contact-message-form-heading,
html[dir="rtl"] .contact-message-support {
    text-align: right;
}

html[dir="rtl"] .contact-message-input-wrapper > i,
html[dir="rtl"] .contact-message-textarea-wrapper > i {
    left: auto;
    right: 15px;
}

html[dir="rtl"] .contact-message-input-wrapper input,
html[dir="rtl"] .contact-message-input-wrapper select {
    padding-left: 15px;
    padding-right: 43px;
}

html[dir="rtl"] .contact-message-input-wrapper select {
    padding-left: 42px;
}

html[dir="rtl"] .contact-message-textarea-wrapper textarea {
    padding-left: 15px;
    padding-right: 43px;
}

html[dir="rtl"] .contact-message-select-icon {
    right: auto !important;
    left: 15px;
}

html[dir="rtl"] .contact-message-floating-card {
    left: auto;
    right: 20px;
}

html[dir="rtl"] .contact-message-submit-button {
    padding-left: 13px;
    padding-right: 22px;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .contact-message-form-wrapper,
html.dark-mode .contact-message-floating-card {
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.25);
}


/* =========================================================
   FOCUS
========================================================= */

.contact-message-submit-button:focus-visible,
.contact-message-checkbox:focus-within .contact-message-checkmark,
.contact-message-input-wrapper input:focus-visible,
.contact-message-input-wrapper select:focus-visible,
.contact-message-textarea-wrapper textarea:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.20);
    outline-offset: 3px;
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) {

    .contact-message-image-wrapper:hover .contact-message-image {
        transform: none;
    }

    .contact-message-submit-button:hover {
        transform: none;
        box-shadow: none;
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .contact-message-image,
    .contact-message-submit-button {
        transition: none;
    }
}





/* =========================================================
   CONTACT PAGE
   SECTION 04: OUR LOCATION
   PART 2 - MAIN CSS
   CONSISTENT TYPOGRAPHY
========================================================= */

.contact-location-section {
    width: 100%;
    padding: 100px 0;
    background: var(--color-surface);
    overflow: hidden;
}

.contact-location-container {
    width: 100%;
    max-width: 1500px;
    margin: 0 auto;
    padding: 0 30px;
    box-sizing: border-box;

    display: grid;
    grid-template-columns: 0.82fr 1.18fr;
    gap: 80px;
    align-items: center;
}


/* =========================================================
   LEFT CONTENT
========================================================= */

.contact-location-content {
    width: 100%;
    max-width: 620px;
}

.contact-location-eyebrow {
    display: inline-block;
    margin-bottom: 14px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 2.5px;
    line-height: 1.3;
}

.contact-location-title {
    margin: 0 0 17px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 48px;
    font-weight: 800;
    line-height: 1.15;
    letter-spacing: -0.8px;
}

.contact-location-title span {
    color: var(--color-orange);
}

.contact-location-description {
    max-width: 600px;
    margin: 0 0 30px;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   LOCATION DETAILS
========================================================= */

.contact-location-detail {
    width: 100%;
    display: flex;
    align-items: flex-start;
    gap: 15px;
    margin-bottom: 20px;
}

.contact-location-detail-icon {
    width: 48px;
    height: 48px;
    flex: 0 0 48px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: rgba(255, 90, 54, 0.10);
    color: var(--color-orange);

    transition:
        background var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast);
}

.contact-location-detail-icon i {
    font-size: 15px;
}

.contact-location-detail-content {
    min-width: 0;
    padding-top: 2px;
}

.contact-location-detail-content > span {
    display: block;
    margin-bottom: 4px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 800;
    letter-spacing: 1.5px;
    line-height: 1.3;
}

.contact-location-detail-content strong,
.contact-location-detail-content a {
    display: block;
    margin-bottom: 3px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 800;
    line-height: 1.4;
    text-decoration: none;
}

.contact-location-detail-content a {
    transition: color var(--transition-fast);
}

.contact-location-detail-content a:hover {
    color: var(--color-orange);
}

.contact-location-detail-content p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    line-height: 1.5;
}


/* =========================================================
   BUTTON
========================================================= */

.contact-location-action {
    margin-top: 30px;
}

.contact-location-button {
    width: 190px;
    min-height: 54px;
    padding: 0 13px 0 22px;

    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;

    box-sizing: border-box;

    border: 2px solid var(--color-orange);
    border-radius: 999px;

    background: var(--color-orange);
    color: #ffffff;

    font-family: var(--font-family);
    font-size: var(--fs-button);
    font-weight: var(--fw-semibold);
    line-height: 1;
    text-decoration: none;

    transition:
        background var(--transition-fast),
        border-color var(--transition-fast),
        color var(--transition-fast),
        transform var(--transition-fast),
        box-shadow var(--transition-fast);
}

.contact-location-button:hover {
    background: var(--color-dark-orange);
    border-color: var(--color-dark-orange);
    color: #ffffff;
    transform: translateY(-3px);
    box-shadow: 0 10px 22px rgba(255, 90, 54, 0.22);
}

.contact-location-button-icon {
    width: 38px;
    height: 38px;
    flex: 0 0 38px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: #ffffff;
    color: var(--color-orange);
}

.contact-location-button-icon i {
    font-size: 12px;
}


/* =========================================================
   MAP WRAPPER
========================================================= */

.contact-location-map-wrapper {
    position: relative;
    width: 100%;
    min-width: 0;
    padding-bottom: 45px;
}

.contact-location-map {
    width: 100%;
    height: 500px;
    overflow: hidden;

    border: 1px solid var(--color-border);
    border-radius: 20px;

    background: var(--color-bg);
    box-shadow: 0 14px 35px rgba(0, 0, 0, 0.08);
}

.contact-location-map iframe {
    width: 100%;
    height: 100%;
    display: block;
    border: 0;
}


/* =========================================================
   FLOATING LOCATION CARD
========================================================= */

.contact-location-floating-card {
    position: absolute;
    left: 25px;
    bottom: 0;
    z-index: 5;

    width: 315px;
    min-height: 105px;
    padding: 17px 20px;

    display: flex;
    align-items: center;
    gap: 14px;

    box-sizing: border-box;

    background: var(--color-bg);
    border: 1px solid var(--color-border);
    border-radius: 15px;

    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.14);
}

.contact-location-floating-icon {
    width: 48px;
    height: 48px;
    flex: 0 0 48px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background: var(--color-orange);
    color: #ffffff;
}

.contact-location-floating-icon i {
    font-size: 17px;
}

.contact-location-floating-content {
    min-width: 0;
}

.contact-location-floating-content > span {
    display: block;
    margin-bottom: 4px;
    color: var(--color-orange);
    font-family: var(--font-family);
    font-size: 8px;
    font-weight: 800;
    letter-spacing: 1.4px;
    line-height: 1.3;
}

.contact-location-floating-content strong {
    display: block;
    margin-bottom: 3px;
    color: var(--color-text);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 800;
    line-height: 1.3;
}

.contact-location-floating-content p {
    margin: 0;
    color: var(--color-text-muted);
    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 400;
    line-height: 1.4;
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .contact-location-container {
    direction: rtl;
}

html[dir="rtl"] .contact-location-content {
    text-align: right;
}

html[dir="rtl"] .contact-location-detail {
    flex-direction: row;
}

html[dir="rtl"] .contact-location-floating-card {
    left: auto;
    right: 25px;
}

html[dir="rtl"] .contact-location-button {
    padding-left: 13px;
    padding-right: 22px;
}


/* =========================================================
   DARK MODE
========================================================= */

html.dark-mode .contact-location-map {
    box-shadow: 0 14px 35px rgba(0, 0, 0, 0.24);
}

html.dark-mode .contact-location-floating-card {
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.28);
}


/* =========================================================
   FOCUS
========================================================= */

.contact-location-button:focus-visible,
.contact-location-detail-content a:focus-visible {
    outline: 3px solid rgba(255, 90, 54, 0.20);
    outline-offset: 4px;
}


/* =========================================================
   TOUCH
========================================================= */

@media (hover: none) {

    .contact-location-button:hover {
        transform: none;
        box-shadow: none;
    }

    .contact-location-detail-content a:hover {
        color: var(--color-text);
    }
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .contact-location-button,
    .contact-location-detail-icon {
        transition: none;
    }
}













/* =========================================================
   PAINTCRAFT LOGIN PAGE
   PART 2 — MAIN CSS + DARK MODE
   FONT: INTER
========================================================= */


/* =========================================================
   FONT
========================================================= */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');


/* =========================================================
   ROOT VARIABLES
========================================================= */

:root {

    /* =====================================================
       FONT
    ===================================================== */

    --font-primary: 'Inter', sans-serif;


    /* =====================================================
       BRAND COLORS
    ===================================================== */

    --color-orange: #ff5a36;
    --color-orange-dark: #e94a28;
    --color-orange-light: #ff704d;

    --color-green: #63b83f;
    --color-green-dark: #4f9d31;
    --color-green-light: #7acb55;


    /* =====================================================
       LIGHT THEME
    ===================================================== */

    --color-bg: #ffffff;
    --color-bg-soft: #f8f8f6;
    --color-bg-alt: #f3f4f2;

    --color-surface: #ffffff;
    --color-surface-soft: #fafafa;

    --color-text: #252525;
    --color-text-dark: #1d1d1d;
    --color-text-light: #666666;
    --color-text-muted: #888888;

    --color-border: #e4e4e4;
    --color-border-light: #eeeeee;


    /* =====================================================
       LOGIN VARIABLES
    ===================================================== */

    --login-bg: var(--color-bg-soft);
    --login-card-bg: var(--color-surface);

    --login-heading: var(--color-text-dark);
    --login-text: var(--color-text-light);
    --login-muted: var(--color-text-muted);

    --login-border: var(--color-border);
    --login-input-bg: var(--color-surface);
    --login-input-border: var(--color-border);

    --login-control-bg: var(--color-surface);
    --login-control-text: var(--color-text);

    --login-social-bg: var(--color-surface);
    --login-social-hover: var(--color-bg-soft);

    --login-shadow:
        0 18px 50px rgba(37, 37, 37, 0.08);

    --login-radius-sm: 8px;
    --login-radius-md: 12px;
    --login-radius-lg: 20px;

    --login-transition: all 0.3s ease;

}


/* =========================================================
   RESET
========================================================= */

*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}


/* =========================================================
   HTML
========================================================= */

html {
    scroll-behavior: smooth;
}


/* =========================================================
   BODY
========================================================= */

body {

    margin: 0;

    font-family: var(--font-primary);

    font-size: 16px;

    font-weight: 400;

    line-height: 1.6;

    color: var(--color-text);

    background: var(--color-bg-soft);

    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;

    transition:
        background-color 0.3s ease,
        color 0.3s ease;

}


/* =========================================================
   COMMON ELEMENTS
========================================================= */

a {
    color: inherit;
    text-decoration: none;
}

button,
input {
    font-family: var(--font-primary);
}

button {
    border: 0;
}

img {
    max-width: 100%;
}


/* =========================================================
   AUTH CONTROLS
   DARK MODE + RTL
   OUTSIDE LOGIN CARD
========================================================= */

.auth-controls {

    position: absolute;

    top: 28px;
    right: 30px;

    z-index: 1000;

    display: flex;

    align-items: center;

    gap: 10px;

}


/* =========================================================
   AUTH CONTROL BUTTON
========================================================= */

.auth-control-btn {

    width: 44px;
    height: 44px;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 0;

    border: 1px solid var(--color-border);

    border-radius: 50%;

    background: var(--color-surface);

    color: var(--color-text);

    font-size: 16px;

    cursor: pointer;

    transition: var(--login-transition);

}


.auth-control-btn:hover {

    background: var(--color-orange);

    border-color: var(--color-orange);

    color: #ffffff;

    transform: translateY(-2px);

}


/* =========================================================
   LOGIN PAGE
========================================================= */

.paintcraft-login-page {

    width: 100%;

    min-height: 100vh;
    min-height: 100dvh;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 100px 20px 50px;

    background: var(--login-bg);

    transition:
        background-color 0.3s ease;

}


/* =========================================================
   LOGIN SECTION
========================================================= */

.paintcraft-login-section {

    width: 100%;

    display: flex;

    align-items: center;

    justify-content: center;

}


/* =========================================================
   LOGIN CONTAINER
========================================================= */

.paintcraft-login-container {

    width: 100%;

    max-width: 500px;

    margin: 0 auto;

}


/* =========================================================
   LOGIN CARD
========================================================= */

.paintcraft-login-card {

    width: 100%;

    padding: 42px 42px 36px;

    background: var(--login-card-bg);

    border: 1px solid var(--login-border);

    border-radius: var(--login-radius-lg);

    box-shadow: var(--login-shadow);

    transition:
        background-color 0.3s ease,
        border-color 0.3s ease,
        box-shadow 0.3s ease;

}


/* =========================================================
   LOGO
========================================================= */

.paintcraft-login-logo {

    display: flex;

    align-items: center;

    justify-content: center;

    margin-bottom: 28px;

}


.paintcraft-login-logo a {

    display: inline-flex;

    align-items: center;

    justify-content: center;

}


.paintcraft-login-logo img {

    display: block;

    width: auto;

    max-width: 180px;

    max-height: 65px;

    object-fit: contain;

}


/* =========================================================
   LOGIN HEADER
========================================================= */

.paintcraft-login-header {

    margin-bottom: 30px;

    text-align: center;

}


/* =========================================================
   EYEBROW
========================================================= */

.paintcraft-login-eyebrow {

    display: block;

    margin-bottom: 8px;

    color: var(--color-orange);

    font-size: 12px;

    font-weight: 700;

    line-height: 1.4;

    letter-spacing: 1.5px;

    text-transform: uppercase;

}


/* =========================================================
   LOGIN TITLE
========================================================= */

.paintcraft-login-title {

    margin: 0 0 10px;

    color: var(--login-heading);

    font-size: 30px;

    font-weight: 700;

    line-height: 1.25;

    letter-spacing: -0.5px;

}


/* =========================================================
   LOGIN DESCRIPTION
========================================================= */

.paintcraft-login-description {

    max-width: 410px;

    margin: 0 auto;

    color: var(--login-text);

    font-size: 14px;

    font-weight: 400;

    line-height: 1.7;

}


/* =========================================================
   LOGIN FORM
========================================================= */

.paintcraft-login-form {

    width: 100%;

}


/* =========================================================
   FORM GROUP
========================================================= */

.paintcraft-login-form-group {

    width: 100%;

    margin-bottom: 20px;

}


/* =========================================================
   LABEL ROW
========================================================= */

.paintcraft-login-label-row {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    margin-bottom: 8px;

}


/* =========================================================
   LABEL
========================================================= */

.paintcraft-login-form-group label {

    display: block;

    color: var(--login-heading);

    font-size: 14px;

    font-weight: 600;

    line-height: 1.5;

}


/* =========================================================
   FORGOT PASSWORD
========================================================= */

.paintcraft-login-forgot-link {

    flex-shrink: 0;

    color: var(--color-orange);

    font-size: 13px;

    font-weight: 600;

    line-height: 1.5;

    transition: var(--login-transition);

}


.paintcraft-login-forgot-link:hover {

    color: var(--color-orange-dark);

    text-decoration: underline;

}


/* =========================================================
   INPUT WRAPPER
========================================================= */

.paintcraft-login-input-wrapper {

    position: relative;

    width: 100%;

}


/* =========================================================
   INPUT ICON
========================================================= */

.paintcraft-login-input-wrapper > i {

    position: absolute;

    top: 50%;
    left: 16px;

    z-index: 2;

    color: var(--login-muted);

    font-size: 15px;

    transform: translateY(-50%);

    pointer-events: none;

    transition: var(--login-transition);

}


/* =========================================================
   INPUT
========================================================= */

.paintcraft-login-input-wrapper input {

    width: 100%;

    height: 52px;

    padding: 0 46px;

    border: 1px solid var(--login-input-border);

    border-radius: var(--login-radius-md);

    outline: none;

    background: var(--login-input-bg);

    color: var(--login-heading);

    font-family: var(--font-primary);

    font-size: 14px;

    font-weight: 400;

    line-height: 1.5;

    transition: var(--login-transition);

}


.paintcraft-login-input-wrapper input::placeholder {

    color: var(--color-text-muted);

    opacity: 1;

}


.paintcraft-login-input-wrapper input:hover {

    border-color: var(--color-orange-light);

}


.paintcraft-login-input-wrapper input:focus {

    border-color: var(--color-orange);

    box-shadow:
        0 0 0 3px rgba(255, 90, 54, 0.10);

}


.paintcraft-login-input-wrapper:focus-within > i {

    color: var(--color-orange);

}


/* =========================================================
   PASSWORD TOGGLE
========================================================= */

.paintcraft-login-password-toggle {

    position: absolute;

    top: 50%;
    right: 14px;

    width: 32px;
    height: 32px;

    display: flex;

    align-items: center;
    justify-content: center;

    padding: 0;

    background: transparent;

    color: var(--login-muted);

    font-size: 14px;

    cursor: pointer;

    transform: translateY(-50%);

    transition: var(--login-transition);

}


.paintcraft-login-password-toggle:hover {

    color: var(--color-orange);

}


/* =========================================================
   LOGIN OPTIONS
========================================================= */

.paintcraft-login-options {

    display: flex;

    align-items: center;

    justify-content: space-between;

    margin: 2px 0 22px;

}


/* =========================================================
   REMEMBER ME
========================================================= */

.paintcraft-login-remember {

    display: inline-flex !important;

    align-items: center;

    gap: 9px;

    cursor: pointer;

    user-select: none;

}


/* =========================================================
   HIDDEN CHECKBOX
========================================================= */

.paintcraft-login-remember input {

    position: absolute;

    width: 1px;
    height: 1px;

    opacity: 0;

    pointer-events: none;

}


/* =========================================================
   CUSTOM CHECKBOX
========================================================= */

.paintcraft-login-checkbox {

    position: relative;

    width: 18px;
    height: 18px;

    flex: 0 0 18px;

    border: 1px solid var(--login-input-border);

    border-radius: 5px;

    background: var(--login-input-bg);

    transition: var(--login-transition);

}


/* =========================================================
   CHECKED CHECKBOX
========================================================= */

.paintcraft-login-remember input:checked
+ .paintcraft-login-checkbox {

    border-color: var(--color-orange);

    background: var(--color-orange);

}


.paintcraft-login-remember input:checked
+ .paintcraft-login-checkbox::after {

    content: '';

    position: absolute;

    top: 3px;
    left: 6px;

    width: 5px;
    height: 9px;

    border: solid #ffffff;

    border-width: 0 2px 2px 0;

    transform: rotate(45deg);

}


/* =========================================================
   REMEMBER TEXT
========================================================= */

.paintcraft-login-remember > span:last-child {

    color: var(--login-text);

    font-size: 13px;

    font-weight: 400;

    line-height: 1.5;

}


/* =========================================================
   SUBMIT BUTTON
========================================================= */

.paintcraft-login-submit-btn {

    width: 100%;

    min-height: 52px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 10px;

    padding: 12px 20px;

    border: 1px solid var(--color-orange);

    border-radius: var(--login-radius-md);

    background: var(--color-orange);

    color: #ffffff;

    font-family: var(--font-primary);

    font-size: 14px;

    font-weight: 600;

    line-height: 1.5;

    cursor: pointer;

    transition: var(--login-transition);

}


.paintcraft-login-submit-btn:hover {

    background: var(--color-orange-dark);

    border-color: var(--color-orange-dark);

    transform: translateY(-2px);

    box-shadow:
        0 8px 20px rgba(255, 90, 54, 0.20);

}


.paintcraft-login-submit-btn:active {

    transform: translateY(0);

}


/* =========================================================
   SUBMIT ICON
========================================================= */

.paintcraft-login-submit-btn i {

    font-size: 13px;

    transition: transform 0.3s ease;

}


.paintcraft-login-submit-btn:hover i {

    transform: translateX(3px);

}


/* =========================================================
   DIVIDER
========================================================= */

.paintcraft-login-divider {

    display: flex;

    align-items: center;

    justify-content: center;

    margin: 28px 0 22px;

}


.paintcraft-login-divider::before,
.paintcraft-login-divider::after {

    content: '';

    flex: 1;

    height: 1px;

    background: var(--login-border);

}


.paintcraft-login-divider span {

    padding: 0 14px;

    color: var(--login-muted);

    background: var(--login-card-bg);

    font-size: 12px;

    font-weight: 500;

    line-height: 1.5;

    white-space: nowrap;

}


/* =========================================================
   SOCIAL LOGIN
========================================================= */

.paintcraft-login-social {

    display: flex;

    flex-direction: column;

    gap: 10px;

}


/* =========================================================
   SOCIAL BUTTON
========================================================= */

.paintcraft-login-social-btn {

    width: 100%;

    min-height: 48px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 10px;

    padding: 10px 18px;

    border: 1px solid var(--login-border);

    border-radius: var(--login-radius-md);

    background: var(--login-social-bg);

    color: var(--login-heading);

    font-family: var(--font-primary);

    font-size: 14px;

    font-weight: 600;

    line-height: 1.5;

    transition: var(--login-transition);

}


.paintcraft-login-social-btn:hover {

    background: var(--login-social-hover);

    border-color: var(--color-orange-light);

    transform: translateY(-1px);

}


/* =========================================================
   GOOGLE SVG
========================================================= */

.paintcraft-google-logo {

    width: 18px;
    height: 18px;

    display: block;

    flex: 0 0 18px;

}


/* =========================================================
   FACEBOOK
========================================================= */

.paintcraft-login-facebook i {

    color: #1877f2;

    font-size: 17px;

}


/* =========================================================
   APPLE
========================================================= */

.paintcraft-login-apple i {

    color: var(--login-heading);

    font-size: 18px;

}


/* =========================================================
   REGISTER
========================================================= */

