    ===================================================== */

    --font-primary: 'Inter', sans-serif;


    /* =====================================================
       BRAND COLORS
    ===================================================== */

    --color-orange: #ff5a36;
    --color-orange-dark: #e94a28;
    --color-orange-light: #ff704d;

    --color-green: #63b83f;
    --color-green-dark: #4f9d31;
    --color-green-light: #7acb55;


    /* =====================================================
       LIGHT THEME
    ===================================================== */

    --color-bg: #ffffff;
    --color-bg-soft: #f8f8f6;
    --color-bg-alt: #f3f4f2;

    --color-surface: #ffffff;
    --color-surface-soft: #fafafa;

    --color-text: #252525;
    --color-text-dark: #1d1d1d;
    --color-text-light: #666666;
    --color-text-muted: #888888;

    --color-border: #e4e4e4;
    --color-border-light: #eeeeee;


    /* =====================================================
       REGISTER VARIABLES
    ===================================================== */

    --register-bg: var(--color-bg-soft);

    --register-card-bg: var(--color-surface);

    --register-heading: var(--color-text-dark);
    --register-text: var(--color-text-light);
    --register-muted: var(--color-text-muted);

    --register-border: var(--color-border);

    --register-input-bg: var(--color-surface);
    --register-input-border: var(--color-border);

    --register-control-bg: var(--color-surface);
    --register-control-text: var(--color-text);

    --register-social-bg: var(--color-surface);
    --register-social-hover: var(--color-bg-soft);

    --register-shadow:
        0 18px 50px rgba(37, 37, 37, 0.08);

    --register-radius-sm: 8px;
    --register-radius-md: 12px;
    --register-radius-lg: 20px;

    --register-transition: all 0.3s ease;

}


/* =========================================================
   RESET
========================================================= */

*,
*::before,
*::after {

    box-sizing: border-box;

    margin: 0;

    padding: 0;

}


/* =========================================================
   HTML
========================================================= */

html {

    scroll-behavior: smooth;

}


/* =========================================================
   BODY
========================================================= */

body {

    margin: 0;

    font-family: var(--font-primary);

    font-size: 16px;

    font-weight: 400;

    line-height: 1.6;

    color: var(--color-text);

    background: var(--color-bg-soft);

    -webkit-font-smoothing: antialiased;

    -moz-osx-font-smoothing: grayscale;

    transition:
        background-color 0.3s ease,
        color 0.3s ease;

}


/* =========================================================
   COMMON
========================================================= */

a {

    color: inherit;

    text-decoration: none;

}


button,
input {

    font-family: var(--font-primary);

}


button {

    border: 0;

}


img {

    max-width: 100%;

}


/* =========================================================
   AUTH CONTROLS
========================================================= */

.auth-controls {

    position: absolute;

    top: 28px;

    right: 30px;

    z-index: 1000;

    display: flex;

    align-items: center;

    gap: 10px;

}


/* =========================================================
   AUTH CONTROL BUTTON
========================================================= */

.auth-control-btn {

    width: 44px;

    height: 44px;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 0;

    border: 1px solid var(--color-border);

    border-radius: 50%;

    background: var(--color-surface);

    color: var(--color-text);

    font-size: 16px;

