   FONT
========================================================= */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');


/* =========================================================
   ROOT VARIABLES
========================================================= */

:root {

    /* =====================================================
       FONT
    ===================================================== */

    --font-primary: 'Inter', sans-serif;


    /* =====================================================
       PAINTCRAFT BRAND COLORS
    ===================================================== */

    --color-orange: #ff5a36;
    --color-orange-dark: #e94a28;
    --color-orange-light: #ff704d;

    --color-green: #63b83f;
    --color-green-dark: #4f9d31;
    --color-green-light: #7acb55;


    /* =====================================================
       LIGHT THEME
    ===================================================== */

    --color-bg: #ffffff;
    --color-bg-soft: #f8f8f6;
    --color-bg-alt: #f3f4f2;

    --color-surface: #ffffff;
    --color-surface-soft: #fafafa;

    --color-text: #252525;
    --color-text-dark: #1d1d1d;
    --color-text-light: #666666;
    --color-text-muted: #888888;

    --color-border: #e4e4e4;
    --color-border-light: #eeeeee;


    /* =====================================================
       QUOTE PAGE VARIABLES
    ===================================================== */

    --quote-bg: var(--color-bg-soft);

    --quote-card-bg: var(--color-surface);

    --quote-heading: var(--color-text-dark);

    --quote-text: var(--color-text-light);

    --quote-muted: var(--color-text-muted);

    --quote-border: var(--color-border);

    --quote-input-bg: var(--color-surface);

    --quote-input-border: var(--color-border);

    --quote-control-bg: var(--color-surface);

    --quote-control-text: var(--color-text);

    --quote-shadow:
        0 18px 50px rgba(37, 37, 37, 0.08);

    --quote-radius-sm: 8px;

    --quote-radius-md: 12px;

    --quote-radius-lg: 20px;

    --quote-transition: all 0.3s ease;

}


/* =========================================================
   RESET
========================================================= */

*,
*::before,
*::after {

    box-sizing: border-box;

    margin: 0;

    padding: 0;

}


/* =========================================================
   HTML
========================================================= */

html {

    scroll-behavior: smooth;

}


/* =========================================================
   BODY
========================================================= */

body {

    margin: 0;

    font-family: var(--font-primary);

    font-size: 16px;

    font-weight: 400;

    line-height: 1.6;

    color: var(--color-text);

    background: var(--color-bg-soft);

    -webkit-font-smoothing: antialiased;

    -moz-osx-font-smoothing: grayscale;

    transition:
        background-color 0.3s ease,
        color 0.3s ease;

}


/* =========================================================
   COMMON
========================================================= */

a {

    color: inherit;

    text-decoration: none;

}


button,
input,
select,
textarea {

    font-family: var(--font-primary);

}


button {

    border: 0;

}


img {

    display: block;

    max-width: 100%;

}


/* =========================================================
   TOP BAR
   LOGO LEFT / CONTROLS RIGHT
========================================================= */

.quote-topbar {

    width: 100%;

    min-height: 112px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 20px 7.5%;

    background: var(--color-surface);

    border-bottom: 1px solid var(--color-border-light);

    transition:
        background-color 0.3s ease,
        border-color 0.3s ease;

}


/* =========================================================
   QUOTE LOGO
========================================================= */

.quote-logo {

    display: flex;

    align-items: center;

    justify-content: flex-start;

}


.quote-logo a {

    display: inline-flex;

    align-items: center;

}


.quote-logo img {

    width: auto;

    max-width: 190px;

    max-height: 70px;

    object-fit: contain;

}


/* =========================================================
   QUOTE AUTH CONTROLS
========================================================= */

.quote-auth-controls {

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 12px;

}


/* =========================================================
   QUOTE CONTROL BUTTON
========================================================= */

.quote-control-btn {

    width: 48px;

    height: 48px;

    display: flex;

    align-items: center;

    justify-content: center;

    padding: 0;

    border: 1px solid var(--color-border);

    border-radius: 12px;

    background: var(--quote-control-bg);

    color: var(--quote-control-text);

    font-size: 17px;

    cursor: pointer;

    transition: var(--quote-transition);

}


.quote-control-btn:hover {

    background: var(--color-orange);

    border-color: var(--color-orange);

    color: #ffffff;

    transform: translateY(-2px);

}


/* =========================================================
   QUOTE PAGE
========================================================= */

.paintcraft-quote-page {

    width: 100%;

    min-height: calc(100vh - 112px);

    min-height: calc(100dvh - 112px);

    padding: 70px 20px 80px;

    background: var(--quote-bg);

    transition:
        background-color 0.3s ease;

}


/* =========================================================
   QUOTE SECTION
========================================================= */

.paintcraft-quote-section {

    width: 100%;

    display: flex;

    align-items: center;

    justify-content: center;

}


/* =========================================================
   QUOTE CONTAINER
========================================================= */

.paintcraft-quote-container {

    width: 100%;

    max-width: 1120px;

    margin: 0 auto;

}


/* =========================================================
   QUOTE CARD
========================================================= */

.paintcraft-quote-card {

    width: 100%;

    padding: 58px 58px 60px;

    background: var(--quote-card-bg);

    border: 1px solid var(--quote-border);

    border-radius: 24px;

    box-shadow: var(--quote-shadow);

    transition:
        background-color 0.3s ease,
        border-color 0.3s ease,
        box-shadow 0.3s ease;

}


/* =========================================================
   QUOTE HEADER
========================================================= */

.paintcraft-quote-header {

    margin-bottom: 42px;

    text-align: left;

}


/* =========================================================
   EYEBROW
========================================================= */

.paintcraft-quote-eyebrow {

    display: block;

    margin-bottom: 8px;

    color: var(--color-orange);

    font-size: 12px;

    font-weight: 700;

    line-height: 1.4;

    letter-spacing: 1.5px;

    text-transform: uppercase;

}


/* =========================================================
   QUOTE TITLE
========================================================= */

.paintcraft-quote-title {

    margin: 0 0 14px;

    color: var(--quote-heading);

    font-size: 40px;

    font-weight: 700;

    line-height: 1.2;

    letter-spacing: -0.8px;

}


/* =========================================================
   TITLE ACCENT LINE
========================================================= */

.paintcraft-quote-title-line {

    display: block;

    width: 92px;

    height: 3px;

    margin-bottom: 14px;

    border-radius: 5px;

    background: var(--color-orange);

}


/* =========================================================
   DESCRIPTION
========================================================= */

.paintcraft-quote-description {

    max-width: 850px;

    margin: 0;

    color: var(--quote-text);

    font-size: 15px;

    font-weight: 400;

    line-height: 1.7;

}


/* =========================================================
   QUOTE FORM
========================================================= */

.paintcraft-quote-form {

    width: 100%;

}


/* =========================================================
   FORM ROW
========================================================= */

.paintcraft-quote-form-row {

    width: 100%;

    display: grid;

    grid-template-columns: repeat(2, minmax(0, 1fr));

    gap: 28px 24px;

    margin-bottom: 28px;

}


/* =========================================================
   FORM GROUP
========================================================= */

.paintcraft-quote-form-group {

    width: 100%;

}


/* =========================================================
   FULL WIDTH
========================================================= */

.paintcraft-quote-form-group.quote-full-width {

    margin-bottom: 28px;

}


/* =========================================================
   LABEL
========================================================= */

.paintcraft-quote-form-group label {

    display: block;

    margin-bottom: 10px;

    color: var(--quote-heading);

    font-size: 16px;

    font-weight: 600;

    line-height: 1.5;

}


/* =========================================================
   INPUT WRAPPER
========================================================= */

.paintcraft-quote-input-wrapper {

    position: relative;

    width: 100%;

}


/* =========================================================
   INPUT ICON
========================================================= */

.paintcraft-quote-input-wrapper > i:not(.quote-select-icon) {

    position: absolute;

    top: 50%;

    left: 17px;

    z-index: 2;

    color: var(--quote-muted);

    font-size: 15px;

    transform: translateY(-50%);

    pointer-events: none;

    transition: var(--quote-transition);

}


/* =========================================================
   INPUT
========================================================= */

.paintcraft-quote-input-wrapper input {

    width: 100%;

    height: 58px;

    padding: 0 48px;

    border: 1px solid var(--quote-input-border);

    border-radius: var(--quote-radius-md);

    outline: none;

    background: var(--quote-input-bg);

    color: var(--quote-heading);

    font-size: 14px;

    font-weight: 400;

    line-height: 1.5;

    transition: var(--quote-transition);

}


.paintcraft-quote-input-wrapper input::placeholder {

    color: var(--color-text-muted);

    opacity: 1;

}


.paintcraft-quote-input-wrapper input:hover {

    border-color: var(--color-orange-light);

}


.paintcraft-quote-input-wrapper input:focus {

    border-color: var(--color-orange);

    box-shadow:
        0 0 0 3px rgba(255, 90, 54, 0.10);

}


.paintcraft-quote-input-wrapper:focus-within
> i:not(.quote-select-icon) {

    color: var(--color-orange);

}


/* =========================================================
   DATE INPUT
========================================================= */

.paintcraft-quote-input-wrapper input[type="date"] {

    padding-right: 48px;

    color-scheme: light;

}


.paintcraft-quote-input-wrapper input[type="date"]::-webkit-calendar-picker-indicator {

    cursor: pointer;

    opacity: 0.85;

}


/* =========================================================
   SELECT
========================================================= */

.paintcraft-quote-input-wrapper select {

    width: 100%;

    height: 58px;

    padding: 0 48px;

    border: 1px solid var(--quote-input-border);

    border-radius: var(--quote-radius-md);

    outline: none;

    appearance: none;

    -webkit-appearance: none;

    background: var(--quote-input-bg);

    color: var(--quote-heading);

    font-size: 14px;

    font-weight: 400;

    line-height: 1.5;

    cursor: pointer;

    transition: var(--quote-transition);

}


.paintcraft-quote-input-wrapper select:hover {

    border-color: var(--color-orange-light);

}


.paintcraft-quote-input-wrapper select:focus {

    border-color: var(--color-orange);

    box-shadow:
        0 0 0 3px rgba(255, 90, 54, 0.10);

}


/* =========================================================
   SELECT ARROW
========================================================= */

.paintcraft-quote-input-wrapper
.quote-select-icon {

    position: absolute;

    top: 50%;

    right: 17px;

    color: var(--quote-muted);

    font-size: 12px;

    transform: translateY(-50%);

    pointer-events: none;

}


/* =========================================================
   TEXTAREA
========================================================= */

.paintcraft-quote-textarea-wrapper {

    width: 100%;

}


.paintcraft-quote-textarea-wrapper textarea {

    width: 100%;

    min-height: 165px;

    display: block;

    padding: 17px 18px;

    border: 1px solid var(--quote-input-border);

    border-radius: var(--quote-radius-md);

    outline: none;

    resize: vertical;

    background: var(--quote-input-bg);

    color: var(--quote-heading);

    font-family: var(--font-primary);

    font-size: 14px;

    font-weight: 400;

    line-height: 1.7;

    transition: var(--quote-transition);

}


.paintcraft-quote-textarea-wrapper textarea::placeholder {

    color: var(--color-text-muted);

    opacity: 1;

}


.paintcraft-quote-textarea-wrapper textarea:hover {

    border-color: var(--color-orange-light);

}


.paintcraft-quote-textarea-wrapper textarea:focus {

    border-color: var(--color-orange);

    box-shadow:
        0 0 0 3px rgba(255, 90, 54, 0.10);

}


/* =========================================================
   SUBMIT BUTTON
========================================================= */

.paintcraft-quote-submit-btn {

    width: 100%;

    min-height: 60px;

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 12px;

    margin-top: 4px;

    padding: 14px 24px;

    border: 1px solid var(--color-orange);

    border-radius: 14px;

    background: var(--color-orange);

    color: #ffffff;

    font-family: var(--font-primary);

    font-size: 16px;

    font-weight: 700;

    line-height: 1.5;

    cursor: pointer;

    transition: var(--quote-transition);

}


.paintcraft-quote-submit-btn:hover {

    background: var(--color-green-dark);

    border-color: var(--color-green-dark);

    transform: translateY(-2px);

    box-shadow:
        0 8px 20px rgba(99, 184, 63, 0.20);

}


.paintcraft-quote-submit-btn:active {

    transform: translateY(0);

}


/* =========================================================
   SUBMIT ICON
========================================================= */

.paintcraft-quote-submit-btn i {

    font-size: 14px;

    transition: transform 0.3s ease;

}


.paintcraft-quote-submit-btn:hover i {

    transform: translateX(4px);

}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode {

    /* =====================================================
       BRAND COLORS
    ===================================================== */

    --color-orange: #ff5a36;
    --color-orange-dark: #e94a28;
    --color-orange-light: #ff704d;

    --color-green: #63b83f;
    --color-green-dark: #4f9d31;
    --color-green-light: #7acb55;


    /* =====================================================
       DARK THEME
    ===================================================== */

    --color-bg: #151515;
    --color-bg-soft: #1b1b1b;
    --color-bg-alt: #202020;

    --color-surface: #202020;
    --color-surface-soft: #252525;

    --color-text: #f5f5f5;
    --color-text-dark: #ffffff;
    --color-text-light: #c5c5c5;
    --color-text-muted: #999999;

    --color-border: #363636;
    --color-border-light: #424242;


    /* =====================================================
       QUOTE DARK MODE
    ===================================================== */

    --quote-bg: var(--color-bg);

    --quote-card-bg: var(--color-surface);

    --quote-heading: var(--color-text-dark);

    --quote-text: var(--color-text-light);

    --quote-muted: var(--color-text-muted);

    --quote-border: var(--color-border);

    --quote-input-bg: var(--color-bg-alt);

    --quote-input-border: var(--color-border);

    --quote-control-bg: var(--color-surface);

    --quote-control-text: var(--color-text);

    --quote-shadow:
        0 18px 50px rgba(0, 0, 0, 0.35);

}


/* =========================================================
   DARK MODE — TOP BAR
========================================================= */

body.dark-mode
.quote-topbar {

    background: var(--color-surface);

    border-color: var(--color-border);

}


/* =========================================================
   DARK MODE — INPUT
========================================================= */

body.dark-mode
.paintcraft-quote-input-wrapper input {

    color: var(--color-text);

    color-scheme: dark;

}


body.dark-mode
.paintcraft-quote-input-wrapper input::placeholder {

    color: var(--color-text-muted);

}


/* =========================================================
   DARK MODE — DATE
========================================================= */

body.dark-mode
.paintcraft-quote-input-wrapper
input[type="date"] {

    color-scheme: dark;

}


/* =========================================================
   DARK MODE — SELECT
========================================================= */

body.dark-mode
.paintcraft-quote-input-wrapper select {

    color: var(--color-text);

}


/* =========================================================
   DARK MODE — TEXTAREA
========================================================= */

body.dark-mode
.paintcraft-quote-textarea-wrapper textarea {

    color: var(--color-text);

}


body.dark-mode
.paintcraft-quote-textarea-wrapper textarea::placeholder {

    color: var(--color-text-muted);

}


/* =========================================================
   DARK MODE — CONTROL
========================================================= */

body.dark-mode
.quote-control-btn {

    background: var(--color-surface);

    border-color: var(--color-border);

    color: var(--color-text);

}


/* =========================================================
   DARK MODE — CONTROL HOVER
========================================================= */

body.dark-mode
.quote-control-btn:hover {

    background: var(--color-orange);

    border-color: var(--color-orange);

    color: #ffffff;

}


/* =========================================================
   TEXT SELECTION
========================================================= */

::selection {

    background: var(--color-orange);

    color: #ffffff;

}


/* =========================================================
   ACCESSIBILITY
========================================================= */

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {

    outline: 2px solid var(--color-orange);

    outline-offset: 3px;

}


/* =========================================================
   PREVENT HORIZONTAL OVERFLOW
========================================================= */

html,
body {

    max-width: 100%;

    overflow-x: hidden;

}







