/* =========================================================
   SCROLL TO TOP BUTTON
========================================================= */

.scroll-top-button {
    position: fixed !important;
    right: 24px !important;
    bottom: 24px !important;

    width: 48px !important;
    height: 48px !important;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    background: #ff573d !important;
    color: #ffffff !important;

    border: 1px solid #ff573d !important;
    border-radius: 50% !important;

    cursor: pointer !important;

    z-index: 9999 !important;

    opacity: 0 !important;
    visibility: hidden !important;
    transform: translateY(15px) !important;

    transition:
        opacity 0.3s ease,
        visibility 0.3s ease,
        transform 0.3s ease,
        background 0.3s ease !important;
}


/* SHOW */

.scroll-top-button.show {
    opacity: 1 !important;
    visibility: visible !important;
    transform: translateY(0) !important;
}


/* ICON */

.scroll-top-button i {
    color: #ffffff !important;
    font-size: 16px !important;
}


/* HOVER */

.scroll-top-button:hover {
    background: #ffffff !important;
    color: #ff573d !important;
}

.scroll-top-button:hover i {
    color: #ff573d !important;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .scroll-top-button,
html.dark-mode .scroll-top-button {
    background: #ff573d !important;
    color: #ffffff !important;
    border-color: #ff573d !important;
}

body.dark-mode .scroll-top-button i,
html.dark-mode .scroll-top-button i {
    color: #ffffff !important;
}


/* DARK MODE HOVER */

body.dark-mode .scroll-top-button:hover,
html.dark-mode .scroll-top-button:hover {
